fn persist_spreadsheet_comparison_source_file(
    path: &Path,
    extension: &str,
) -> Result<(tempfile::TempDir, PathBuf, usize), String> {
    let source_size = fs::metadata(path)
        .map_err(|error| format!("No se pudo inspeccionar la fuente comparada: {error}"))?
        .len();
    let sheets = inspect_workbook(path)?;
    let sheet = sheets
        .first()
        .ok_or_else(|| "El libro no contiene hojas que se puedan comparar.".to_owned())?;
    let directory = tempfile::tempdir()
        .map_err(|error| format!("No se pudo preparar el snapshot comparado: {error}"))?;
    let temporary = directory.path().join("compared.partial.parquet");
    let row_count = if matches!(extension, "xlsx" | "xlsb") {
        let plan = spreadsheet_snapshot_plan_from_stream(
            path,
            sheet,
            SpreadsheetHeaderMode::FirstRow,
            || false,
        )?;
        write_streamed_spreadsheet_snapshot(path, sheet, &plan, &temporary, || false)?;
        plan.data_rows
    } else {
        let mut workbook = open_workbook_auto(path)
            .map_err(|error| format!("No se pudo abrir el libro seleccionado: {error}"))?;
        let range = workbook
            .worksheet_range(sheet)
            .map_err(|error| format!("No se pudo leer la hoja seleccionada: {error}"))?;
        write_spreadsheet_range_snapshot(&range, SpreadsheetHeaderMode::FirstRow, &temporary)?
    };
    let final_size = fs::metadata(path)
        .map_err(|error| format!("No se pudo verificar la fuente comparada: {error}"))?
        .len();
    if final_size != source_size {
        return Err("La fuente comparada cambió durante la creación del snapshot.".to_owned());
    }
    let destination = directory.path().join("compared.parquet");
    fs::rename(&temporary, &destination)
        .map_err(|error| format!("No se pudo publicar el snapshot comparado: {error}"))?;
    Ok((directory, destination, row_count))
}

fn row_signature(
    frame: &DataFrame,
    columns: &[String],
    row_index: usize,
) -> Result<String, String> {
    let mut signature = String::new();
    for name in columns {
        let value = frame
            .column(name)
            .map_err(|error| format!("No se pudo leer la columna '{name}': {error}"))?
            .get(row_index)
            .map_err(|error| format!("No se pudo comparar la fila {row_index}: {error}"))?;
        match preview_value(value) {
            Some(value) => {
                use std::fmt::Write;
                write!(&mut signature, "v{}:{value};", value.len())
                    .map_err(|_| "No se pudo preparar la comparación.".to_owned())?;
            }
            None => signature.push_str("n;"),
        }
    }
    Ok(signature)
}

struct SpilledKeyRows {
    _directory: tempfile::TempDir,
    bucket_paths: Vec<PathBuf>,
}

#[derive(Clone, Copy)]
struct KeyRowGroup {
    first_row_index: usize,
    count: usize,
}

fn comparison_key_bucket(signature: &str) -> usize {
    (xxh3_64(signature.as_bytes()) as usize) % COMPARISON_KEY_BUCKETS
}

fn create_spilled_key_rows() -> Result<SpilledKeyRows, String> {
    let directory = tempfile::tempdir().map_err(|error| {
        format!("No se pudo preparar el índice temporal de comparación: {error}")
    })?;
    let bucket_paths = (0..COMPARISON_KEY_BUCKETS)
        .map(|bucket| directory.path().join(format!("keys-{bucket:03}.bin")))
        .collect::<Vec<_>>();
    Ok(SpilledKeyRows {
        _directory: directory,
        bucket_paths,
    })
}

fn spill_key_rows_with_cancel<C>(
    frame: &DataFrame,
    key_columns: &[String],
    is_cancelled: &C,
) -> Result<SpilledKeyRows, String>
where
    C: Fn() -> bool + Sync,
{
    let spill = create_spilled_key_rows()?;
    let mut writers = (0..COMPARISON_KEY_BUCKETS)
        .map(|_| None::<BufWriter<File>>)
        .collect::<Vec<_>>();

    for row_index in 0..frame.height() {
        if row_index % LOCAL_QUERY_CANCEL_CHECK_ROWS == 0 {
            ensure_not_cancelled(is_cancelled())?;
        }
        let signature = row_signature(frame, key_columns, row_index)?;
        let bucket = comparison_key_bucket(&signature);
        let writer = if let Some(writer) = writers[bucket].as_mut() {
            writer
        } else {
            let file = File::create(&spill.bucket_paths[bucket]).map_err(|error| {
                format!("No se pudo crear el índice temporal de comparación: {error}")
            })?;
            writers[bucket].get_or_insert_with(|| BufWriter::with_capacity(64 * 1024, file))
        };
        let key_bytes = signature.as_bytes();
        let key_length = u64::try_from(key_bytes.len()).map_err(|_| {
            "La clave de comparación supera la capacidad del índice temporal.".to_owned()
        })?;
        let row_number = u64::try_from(row_index)
            .map_err(|_| "El índice de fila supera la capacidad del índice temporal.".to_owned())?;
        writer
            .write_all(&key_length.to_le_bytes())
            .and_then(|_| writer.write_all(&row_number.to_le_bytes()))
            .and_then(|_| writer.write_all(key_bytes))
            .map_err(|error| {
                format!("No se pudo escribir el índice temporal de comparación: {error}")
            })?;
    }

    for writer in writers.iter_mut().flatten() {
        writer.flush().map_err(|error| {
            format!("No se pudo sincronizar el índice temporal de comparación: {error}")
        })?;
    }
    ensure_not_cancelled(is_cancelled())?;
    drop(writers);
    Ok(spill)
}

fn spill_key_rows(frame: &DataFrame, key_columns: &[String]) -> Result<SpilledKeyRows, String> {
    spill_key_rows_with_cancel(frame, key_columns, &|| false)
}

fn append_spilled_key_rows(
    spill: &SpilledKeyRows,
    frame: &DataFrame,
    key_columns: &[String],
    row_offset: usize,
) -> Result<(), String> {
    let mut writers = (0..COMPARISON_KEY_BUCKETS)
        .map(|_| None::<BufWriter<File>>)
        .collect::<Vec<_>>();
    append_spilled_key_rows_with_writers(spill, frame, key_columns, row_offset, &mut writers)?;

    for writer in writers.iter_mut().flatten() {
        writer.flush().map_err(|error| {
            format!("No se pudo sincronizar el índice temporal de comparación: {error}")
        })?;
    }
    Ok(())
}

fn append_spilled_key_rows_with_writers(
    spill: &SpilledKeyRows,
    frame: &DataFrame,
    key_columns: &[String],
    row_offset: usize,
    writers: &mut [Option<BufWriter<File>>],
) -> Result<(), String> {
    for row_index in 0..frame.height() {
        let signature = row_signature(frame, key_columns, row_index)?;
        let bucket = comparison_key_bucket(&signature);
        let writer = if let Some(writer) = writers[bucket].as_mut() {
            writer
        } else {
            let file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(&spill.bucket_paths[bucket])
                .map_err(|error| {
                    format!("No se pudo abrir el índice temporal de comparación: {error}")
                })?;
            writers[bucket].get_or_insert_with(|| BufWriter::with_capacity(64 * 1024, file))
        };
        let key_bytes = signature.as_bytes();
        let key_length = u64::try_from(key_bytes.len()).map_err(|_| {
            "La clave de comparación supera la capacidad del índice temporal.".to_owned()
        })?;
        let row_number = row_offset
            .checked_add(row_index)
            .and_then(|index| u64::try_from(index).ok())
            .ok_or_else(|| {
                "El índice de fila supera la capacidad del índice temporal.".to_owned()
            })?;
        writer
            .write_all(&key_length.to_le_bytes())
            .and_then(|_| writer.write_all(&row_number.to_le_bytes()))
            .and_then(|_| writer.write_all(key_bytes))
            .map_err(|error| {
                format!("No se pudo escribir el índice temporal de comparación: {error}")
            })?;
    }
    Ok(())
}

fn spill_parquet_rows(
    path: &Path,
    row_count: usize,
    columns: &[String],
) -> Result<SpilledKeyRows, String> {
    let spill = create_spilled_key_rows()?;
    for_each_parquet_block(path, row_count, |start, block| {
        append_spilled_key_rows(&spill, block, columns, start)
    })?;
    Ok(spill)
}

