fn strict_column_text(column: &Column) -> Result<Vec<Option<String>>, String> {
    (0..column.len())
        .map(|row| {
            column
                .get(row)
                .map(preview_value)
                .map_err(|error| format!("No se pudo leer la fila {}: {error}", row + 1))
        })
        .collect()
}

fn recipe_column<'a>(frame: &'a DataFrame, name: &str) -> Result<&'a Column, String> {
    frame
        .column(name)
        .map_err(|_| format!("La columna '{name}' no existe en el dataset activo."))
}

fn strict_cast_column(column: &Column, target: RecipeCastTarget) -> Result<Column, String> {
    let name = column.name().clone();
    let values = strict_column_text(column)?;
    let invalid = |row: usize, value: &str, target: &str| {
        format!(
            "La columna '{}' no se puede convertir a {target}: fila {}, valor '{}'.",
            name,
            row + 1,
            value
        )
    };

    match target {
        RecipeCastTarget::String => Ok(Series::new(name, values).into_column()),
        RecipeCastTarget::Integer => {
            let parsed = values
                .iter()
                .enumerate()
                .map(|(row, value)| {
                    value
                        .as_deref()
                        .map(|value| {
                            value
                                .trim()
                                .parse::<i64>()
                                .map_err(|_| invalid(row, value, "entero"))
                        })
                        .transpose()
                })
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Series::new(name, parsed).into_column())
        }
        RecipeCastTarget::Decimal => {
            let parsed = values
                .iter()
                .enumerate()
                .map(|(row, value)| {
                    value
                        .as_deref()
                        .map(|value| {
                            value
                                .trim()
                                .parse::<f64>()
                                .ok()
                                .filter(|number| number.is_finite())
                                .ok_or_else(|| invalid(row, value, "decimal"))
                        })
                        .transpose()
                })
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Series::new(name, parsed).into_column())
        }
        RecipeCastTarget::Boolean => {
            let parsed = values
                .iter()
                .enumerate()
                .map(|(row, value)| {
                    value
                        .as_deref()
                        .map(|value| match value.trim().to_ascii_lowercase().as_str() {
                            "true" => Ok(true),
                            "false" => Ok(false),
                            _ => Err(invalid(row, value, "booleano (true/false)")),
                        })
                        .transpose()
                })
                .collect::<Result<Vec<_>, _>>()?;
            Ok(Series::new(name, parsed).into_column())
        }
    }
}

fn parse_recipe_datetime(value: &str, format: RecipeDateFormat) -> Result<NaiveDateTime, ()> {
    let value = value.trim();
    let date_format = match format {
        RecipeDateFormat::Ymd => Some("%Y-%m-%d"),
        RecipeDateFormat::Dmy => Some("%d/%m/%Y"),
        RecipeDateFormat::Mdy => Some("%m/%d/%Y"),
        RecipeDateFormat::Iso8601 => None,
    };
    if let Some(format) = date_format {
        return NaiveDate::parse_from_str(value, format)
            .ok()
            .and_then(|date| date.and_hms_opt(0, 0, 0))
            .ok_or(());
    }

    if let Ok(date) = NaiveDate::parse_from_str(value, "%Y-%m-%d") {
        return date.and_hms_opt(0, 0, 0).ok_or(());
    }
    DateTime::parse_from_rfc3339(value)
        .map(|date| date.naive_utc())
        .or_else(|_| NaiveDateTime::parse_from_str(value, "%Y-%m-%dT%H:%M:%S%.f"))
        .or_else(|_| NaiveDateTime::parse_from_str(value, "%Y-%m-%d %H:%M:%S%.f"))
        .map_err(|_| ())
}

fn recipe_filter_is_ordered(operator: RecipeFilterOperator) -> bool {
    matches!(
        operator,
        RecipeFilterOperator::Gt
            | RecipeFilterOperator::Lt
            | RecipeFilterOperator::Gte
            | RecipeFilterOperator::Lte
    )
}

fn recipe_filter_uses_temporal_literal(operator: RecipeFilterOperator) -> bool {
    recipe_filter_is_ordered(operator)
        || matches!(
            operator,
            RecipeFilterOperator::Eq | RecipeFilterOperator::Neq
        )
}

fn parse_recipe_filter_datetime(value: &str, column: &str) -> Result<NaiveDateTime, String> {
    parse_recipe_datetime(value, RecipeDateFormat::Iso8601).map_err(|_| {
        format!("El valor del filtro para '{column}' debe ser una fecha ISO 8601 válida.")
    })
}

fn datetime_timestamp_in_unit(value: NaiveDateTime, unit: TimeUnit) -> Result<i64, String> {
    match unit {
        TimeUnit::Nanoseconds => value
            .and_utc()
            .timestamp_nanos_opt()
            .ok_or_else(|| "La fecha del filtro está fuera del rango admitido.".to_owned()),
        TimeUnit::Microseconds => Ok(value.and_utc().timestamp_micros()),
        TimeUnit::Milliseconds => Ok(value.and_utc().timestamp_millis()),
    }
}

fn strict_date_column(
    column: &Column,
    format: RecipeDateFormat,
    target: RecipeDateTarget,
) -> Result<Column, String> {
    let name = column.name().clone();
    let values = strict_column_text(column)?;
    let parsed = values
        .iter()
        .enumerate()
        .map(|(row, value)| {
            value
                .as_deref()
                .map(|value| {
                    parse_recipe_datetime(value, format).map_err(|_| {
                        format!(
                            "La columna '{}' contiene una fecha inválida en la fila {}: '{}'.",
                            name,
                            row + 1,
                            value
                        )
                    })
                })
                .transpose()
        })
        .collect::<Result<Vec<_>, _>>()?;

    match target {
        RecipeDateTarget::Date => {
            let epoch = NaiveDate::from_ymd_opt(1970, 1, 1).expect("la época Unix es válida");
            let days = parsed
                .into_iter()
                .map(|value| value.map(|value| (value.date() - epoch).num_days() as i32))
                .collect::<Vec<_>>();
            Ok(Series::new(name, days)
                .cast(&polars::prelude::DataType::Date)
                .map_err(|error| format!("No se pudo crear la columna de fecha: {error}"))?
                .into_column())
        }
        RecipeDateTarget::Datetime => {
            let milliseconds = parsed
                .into_iter()
                .map(|value| value.map(|value| value.and_utc().timestamp_millis()))
                .collect::<Vec<_>>();
            Ok(Series::new(name, milliseconds)
                .cast(&polars::prelude::DataType::Datetime(
                    TimeUnit::Milliseconds,
                    None,
                ))
                .map_err(|error| format!("No se pudo crear la columna de fecha y hora: {error}"))?
                .into_column())
        }
    }
}

fn remapped_name<'a>(name: &'a str, renames: &HashMap<&'a str, &'a str>) -> &'a str {
    renames.get(name).copied().unwrap_or(name)
}

fn strict_f64(value: &str, context: &str) -> Result<f64, String> {
    let trimmed = value.trim();
    if !trimmed.contains(['.', 'e', 'E'])
        && trimmed
            .parse::<i128>()
            .is_ok_and(|integer| integer.unsigned_abs() > (1_u128 << 53))
    {
        return Err(format!(
            "{context} excede la precisión numérica segura: '{value}'."
        ));
    }
    trimmed
        .trim()
        .parse::<f64>()
        .ok()
        .filter(|number| number.is_finite())
        .ok_or_else(|| format!("{context} debe ser un número finito: '{value}'."))
}

fn apply_recipe_filters(
    frame: DataFrame,
    filters: &[RecipeFilter],
    renames: &HashMap<&str, &str>,
) -> Result<(DataFrame, usize), String> {
    if filters.len() > 3 {
        return Err("La receta admite como máximo tres filtros combinados con AND.".into());
    }
    let original_height = frame.height();
    let mut combined_mask = vec![true; original_height];
    for filter in filters {
        let name = remapped_name(&filter.column, renames);
        let values = strict_column_text(recipe_column(&frame, name)?)?;
        let unary = matches!(
            filter.operator,
            RecipeFilterOperator::IsNull | RecipeFilterOperator::NotNull
        );
        if unary != filter.value.is_none() {
            return Err(format!(
                "El filtro '{}' {} un valor.",
                filter.column,
                if unary { "no acepta" } else { "requiere" }
            ));
        }
        let literal = filter.value.as_deref().unwrap_or_default();
        if matches!(
            filter.operator,
            RecipeFilterOperator::Gt
                | RecipeFilterOperator::Lt
                | RecipeFilterOperator::Gte
                | RecipeFilterOperator::Lte
                | RecipeFilterOperator::Contains
                | RecipeFilterOperator::NotContains
        ) && literal.is_empty()
        {
            return Err(format!(
                "El filtro '{}' requiere un valor no vacío.",
                filter.column
            ));
        }

        let column_dtype = recipe_column(&frame, name)?.dtype();
        let temporal_literal = if recipe_filter_uses_temporal_literal(filter.operator)
            && matches!(
                column_dtype,
                polars::prelude::DataType::Date | polars::prelude::DataType::Datetime(_, None)
            ) {
            Some(parse_recipe_filter_datetime(literal, name)?)
        } else {
            None
        };
        let numeric_literal =
            if recipe_filter_is_ordered(filter.operator) && temporal_literal.is_none() {
                Some(strict_f64(literal, "El valor del filtro")?)
            } else {
                None
            };
        let temporal_values = temporal_literal
            .as_ref()
            .map(|_| {
                values
                    .iter()
                    .enumerate()
                    .map(|(row, value)| {
                        value
                            .as_deref()
                            .map(|value| {
                                parse_recipe_filter_datetime(value, name).map_err(|_| {
                                    format!(
                                        "La fila {} de la columna '{}' contiene una fecha no válida.",
                                        row + 1,
                                        name
                                    )
                                })
                            })
                            .transpose()
                    })
                    .collect::<Result<Vec<_>, String>>()
            })
            .transpose()?;
        let numeric_values = if numeric_literal.is_some() {
            Some(
                values
                    .iter()
                    .enumerate()
                    .map(|(row, value)| {
                        value
                            .as_deref()
                            .map(|value| {
                                strict_f64(
                                    value,
                                    &format!("La fila {} de la columna '{name}'", row + 1),
                                )
                            })
                            .transpose()
                    })
                    .collect::<Result<Vec<_>, _>>()?,
            )
        } else {
            None
        };
        let needle = literal.to_lowercase();
        let mask = values
            .iter()
            .enumerate()
            .map(|(row, value)| match filter.operator {
                RecipeFilterOperator::IsNull => value.is_none(),
                RecipeFilterOperator::NotNull => value.is_some(),
                RecipeFilterOperator::Eq => temporal_values.as_ref().map_or_else(
                    || value.as_deref() == Some(literal),
                    |values| {
                        values[row].is_some_and(|value| {
                            value == temporal_literal.expect("el filtro requiere una fecha")
                        })
                    },
                ),
                RecipeFilterOperator::Neq => temporal_values.as_ref().map_or_else(
                    || value.as_deref().is_some_and(|value| value != literal),
                    |values| {
                        values[row].is_some_and(|value| {
                            value != temporal_literal.expect("el filtro requiere una fecha")
                        })
                    },
                ),
                RecipeFilterOperator::Contains => value
                    .as_deref()
                    .is_some_and(|value| value.to_lowercase().contains(&needle)),
                RecipeFilterOperator::NotContains => value
                    .as_deref()
                    .is_some_and(|value| !value.to_lowercase().contains(&needle)),
                RecipeFilterOperator::Gt => temporal_values.as_ref().map_or_else(
                    || {
                        numeric_values.as_ref().expect("el filtro requiere números")[row]
                            .is_some_and(|value| {
                                value > numeric_literal.expect("el filtro requiere un literal")
                            })
                    },
                    |values| {
                        values[row].is_some_and(|value| {
                            value > temporal_literal.expect("el filtro requiere una fecha")
                        })
                    },
                ),
                RecipeFilterOperator::Lt => temporal_values.as_ref().map_or_else(
                    || {
                        numeric_values.as_ref().expect("el filtro requiere números")[row]
                            .is_some_and(|value| {
                                value < numeric_literal.expect("el filtro requiere un literal")
                            })
                    },
                    |values| {
                        values[row].is_some_and(|value| {
                            value < temporal_literal.expect("el filtro requiere una fecha")
                        })
                    },
                ),
                RecipeFilterOperator::Gte => temporal_values.as_ref().map_or_else(
                    || {
                        numeric_values.as_ref().expect("el filtro requiere números")[row]
                            .is_some_and(|value| {
                                value >= numeric_literal.expect("el filtro requiere un literal")
                            })
                    },
                    |values| {
                        values[row].is_some_and(|value| {
                            value >= temporal_literal.expect("el filtro requiere una fecha")
                        })
                    },
                ),
                RecipeFilterOperator::Lte => temporal_values.as_ref().map_or_else(
                    || {
                        numeric_values.as_ref().expect("el filtro requiere números")[row]
                            .is_some_and(|value| {
                                value <= numeric_literal.expect("el filtro requiere un literal")
                            })
                    },
                    |values| {
                        values[row].is_some_and(|value| {
                            value <= temporal_literal.expect("el filtro requiere una fecha")
                        })
                    },
                ),
            })
            .collect::<Vec<_>>();
        combined_mask
            .iter_mut()
            .zip(mask)
            .for_each(|(combined, current)| *combined &= current);
    }
    let filtered = frame
        .filter(&BooleanChunked::from_slice("filter".into(), &combined_mask))
        .map_err(|error| format!("No se pudieron aplicar los filtros: {error}"))?;
    let removed = original_height.saturating_sub(filtered.height());
    Ok((filtered, removed))
}

fn date_parts(column: &Column, operation: CalculatedOperation) -> Result<Vec<Option<i32>>, String> {
    let name = column.name();
    match column.dtype() {
        polars::prelude::DataType::Date => {
            let physical = column
                .cast(&polars::prelude::DataType::Int32)
                .map_err(|error| error.to_string())?;
            let epoch = NaiveDate::from_ymd_opt(1970, 1, 1).unwrap();
            Ok((0..physical.len())
                .map(|row| {
                    let days = match physical.get(row).map_err(|error| error.to_string())? {
                        AnyValue::Null => None,
                        AnyValue::Int32(value) => Some(value),
                        _ => {
                            return Err("La fecha no tiene una representación física válida.".into())
                        }
                    };
                    let date = days
                        .map(|days| {
                            epoch
                                .checked_add_signed(chrono::Duration::days(days.into()))
                                .ok_or_else(|| {
                                    format!(
                                        "La fecha de la fila {} está fuera del rango admitido.",
                                        row + 1
                                    )
                                })
                        })
                        .transpose()?;
                    Ok(date.map(|date| match operation {
                        CalculatedOperation::Year => date.year(),
                        CalculatedOperation::Month => date.month() as i32,
                        CalculatedOperation::Day => date.day() as i32,
                        _ => unreachable!(),
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?)
        }
        polars::prelude::DataType::Datetime(unit, _) => {
            let physical = column
                .cast(&polars::prelude::DataType::Int64)
                .map_err(|error| error.to_string())?;
            let divisor = match unit {
                TimeUnit::Nanoseconds => 1_000_000_000,
                TimeUnit::Microseconds => 1_000_000,
                TimeUnit::Milliseconds => 1_000,
            };
            Ok((0..physical.len())
                .map(|row| {
                    let raw = match physical.get(row).map_err(|error| error.to_string())? {
                        AnyValue::Null => None,
                        AnyValue::Int64(value) => Some(value),
                        _ => {
                            return Err(
                                "La fecha y hora no tiene una representación física válida.".into(),
                            )
                        }
                    };
                    let date = raw
                        .map(|raw| {
                            DateTime::from_timestamp(
                                raw.div_euclid(divisor),
                                (raw.rem_euclid(divisor) as u64 * (1_000_000_000 / divisor as u64))
                                    as u32,
                            )
                            .ok_or_else(|| {
                                format!(
                                    "La fecha y hora de la fila {} está fuera del rango admitido.",
                                    row + 1
                                )
                            })
                        })
                        .transpose()?;
                    Ok(date.map(|date| match operation {
                        CalculatedOperation::Year => date.year(),
                        CalculatedOperation::Month => date.month() as i32,
                        CalculatedOperation::Day => date.day() as i32,
                        _ => unreachable!(),
                    }))
                })
                .collect::<Result<Vec<_>, String>>()?)
        }
        _ => Err(format!(
            "La columna '{name}' debe ser date o datetime para extraer componentes."
        )),
    }
}

fn validate_date_parts_column(column: &Column) -> Result<(), String> {
    let name = column.name();
    match column.dtype() {
        polars::prelude::DataType::Date => {
            let physical = column
                .cast(&polars::prelude::DataType::Int32)
                .map_err(|error| error.to_string())?;
            let epoch = NaiveDate::from_ymd_opt(1970, 1, 1).unwrap();
            for row in 0..physical.len() {
                let value = physical.get(row).map_err(|error| error.to_string())?;
                let AnyValue::Int32(days) = value else {
                    if matches!(value, AnyValue::Null) {
                        continue;
                    }
                    return Err("La fecha no tiene una representación física válida.".into());
                };
                epoch
                    .checked_add_signed(chrono::Duration::days(days.into()))
                    .ok_or_else(|| {
                        format!(
                            "La fecha de la fila {} está fuera del rango admitido.",
                            row + 1
                        )
                    })?;
            }
            Ok(())
        }
        polars::prelude::DataType::Datetime(unit, None) => {
            let physical = column
                .cast(&polars::prelude::DataType::Int64)
                .map_err(|error| error.to_string())?;
            let divisor = match unit {
                TimeUnit::Nanoseconds => 1_000_000_000,
                TimeUnit::Microseconds => 1_000_000,
                TimeUnit::Milliseconds => 1_000,
            };
            for row in 0..physical.len() {
                let value = physical.get(row).map_err(|error| error.to_string())?;
                let AnyValue::Int64(raw) = value else {
                    if matches!(value, AnyValue::Null) {
                        continue;
                    }
                    return Err("La fecha y hora no tiene una representación física válida.".into());
                };
                DateTime::from_timestamp(
                    raw.div_euclid(divisor),
                    (raw.rem_euclid(divisor) as u64 * (1_000_000_000 / divisor as u64)) as u32,
                )
                .ok_or_else(|| {
                    format!(
                        "La fecha y hora de la fila {} está fuera del rango admitido.",
                        row + 1
                    )
                })?;
            }
            Ok(())
        }
        _ => Err(format!(
            "La columna '{name}' debe ser date o datetime para extraer componentes."
        )),
    }
}

fn add_calculated_column(
    frame: &mut DataFrame,
    calculation: &CalculatedColumnRecipe,
    renames: &HashMap<&str, &str>,
) -> Result<(), String> {
    if calculation.name.trim().is_empty() || calculation.name != calculation.name.trim() {
        return Err(
            "El nombre de la columna calculada no puede estar vacío ni tener espacios exteriores."
                .into(),
        );
    }
    if frame.column(&calculation.name).is_ok() {
        return Err(format!(
            "La columna calculada '{}' ya existe.",
            calculation.name
        ));
    }
    let source_name = remapped_name(&calculation.source, renames);
    let source = recipe_column(frame, source_name)?;
    let unary = matches!(
        calculation.operation,
        CalculatedOperation::Year | CalculatedOperation::Month | CalculatedOperation::Day
    );
    if unary != calculation.operand.is_none() {
        return Err(if unary {
            "year, month y day no aceptan operando.".into()
        } else {
            "La operación calculada requiere un operando.".into()
        });
    }
    let column = if unary {
        Series::new(
            calculation.name.clone().into(),
            date_parts(source, calculation.operation)?,
        )
        .into_column()
    } else {
        let source_values = strict_column_text(source)?;
        let operand = calculation.operand.as_ref().unwrap();
        let operand_values = match operand.kind {
            CalculatedOperandKind::Literal => vec![Some(operand.value.clone()); frame.height()],
            CalculatedOperandKind::Column => strict_column_text(recipe_column(
                frame,
                remapped_name(&operand.value, renames),
            )?)?,
        };
        match calculation.operation {
            CalculatedOperation::Concat => Series::new(
                calculation.name.clone().into(),
                source_values
                    .iter()
                    .zip(&operand_values)
                    .map(|(left, right)| {
                        left.as_ref()
                            .zip(right.as_ref())
                            .map(|(left, right)| format!("{left}{right}"))
                    })
                    .collect::<Vec<_>>(),
            )
            .into_column(),
            CalculatedOperation::Add
            | CalculatedOperation::Subtract
            | CalculatedOperation::Multiply
            | CalculatedOperation::Divide => {
                if operand.kind == CalculatedOperandKind::Literal && operand.value.is_empty() {
                    return Err("El operando numérico no puede estar vacío.".into());
                }
                let values = source_values
                    .iter()
                    .zip(&operand_values)
                    .enumerate()
                    .map(|(row, (left, right))| {
                        left.as_deref()
                            .zip(right.as_deref())
                            .map(|(left, right)| {
                                let left = strict_f64(
                                    left,
                                    &format!("La fila {} de '{source_name}'", row + 1),
                                )?;
                                let right = strict_f64(
                                    right,
                                    &format!("El operando de la fila {}", row + 1),
                                )?;
                                if calculation.operation == CalculatedOperation::Divide
                                    && right == 0.0
                                {
                                    return Err(format!(
                                        "División por cero en la fila {}.",
                                        row + 1
                                    ));
                                }
                                let result = match calculation.operation {
                                    CalculatedOperation::Add => left + right,
                                    CalculatedOperation::Subtract => left - right,
                                    CalculatedOperation::Multiply => left * right,
                                    CalculatedOperation::Divide => left / right,
                                    _ => unreachable!(),
                                };
                                if !result.is_finite() {
                                    return Err(format!(
                                        "El cálculo produjo un valor no finito en la fila {}.",
                                        row + 1
                                    ));
                                }
                                Ok(result)
                            })
                            .transpose()
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                Series::new(calculation.name.clone().into(), values).into_column()
            }
            _ => unreachable!(),
        }
    };
    frame
        .with_column(column)
        .map_err(|error| format!("No se pudo agregar la columna calculada: {error}"))?;
    Ok(())
}

fn apply_find_replace(
    frame: &mut DataFrame,
    recipe: &FindReplaceRecipe,
    renames: &HashMap<&str, &str>,
) -> Result<usize, String> {
    let regex = compile_find_replace_pattern(recipe)?;
    let targets = match recipe.scope {
        FindReplaceScope::Column => {
            let column = recipe
                .column
                .as_deref()
                .ok_or_else(|| "La búsqueda por columna requiere una columna.".to_owned())?;
            vec![remapped_name(column, renames).to_owned()]
        }
        FindReplaceScope::AllTextColumns => {
            if recipe.column.is_some() {
                return Err(
                    "La búsqueda en todas las columnas no acepta una columna concreta.".into(),
                );
            }
            frame
                .columns()
                .iter()
                .filter(|column| column.dtype() == &polars::prelude::DataType::String)
                .map(|column| column.name().to_string())
                .collect()
        }
    };
    let mut count = 0;
    for name in targets {
        let column = recipe_column(frame, &name)?;
        if column.dtype() != &polars::prelude::DataType::String {
            return Err(format!(
                "La columna '{name}' debe ser de texto para buscar y reemplazar."
            ));
        }
        let values = strict_column_text(column)?;
        let replaced = values
            .into_iter()
            .map(|value| {
                value.map(|value| {
                    let updated = regex
                        .as_ref()
                        .map(|regex| {
                            regex
                                .replace_all(value.as_str(), recipe.replace.as_str())
                                .into_owned()
                        })
                        .unwrap_or_else(|| value.replace(&recipe.find, &recipe.replace));
                    if updated != value {
                        count += 1;
                        updated
                    } else {
                        value
                    }
                })
            })
            .collect::<Vec<_>>();
        frame
            .replace(
                &name,
                Series::new(name.clone().into(), replaced).into_column(),
            )
            .map_err(|error| format!("No se pudo reemplazar texto en '{name}': {error}"))?;
    }
    Ok(count)
}

fn validate_find_replace_pattern(recipe: &FindReplaceRecipe) -> Result<(), String> {
    if recipe.regex && !recipe.find.is_empty() {
        Regex::new(&recipe.find).map_err(|_| {
            "El patrón de búsqueda no es una expresión regular válida compatible con Rust."
                .to_owned()
        })?;
    }
    Ok(())
}

fn compile_find_replace_pattern(recipe: &FindReplaceRecipe) -> Result<Option<Regex>, String> {
    if recipe.find.is_empty() {
        return Err("El texto buscado no puede estar vacío.".into());
    }
    validate_find_replace_pattern(recipe)?;
    if recipe.regex {
        Regex::new(&recipe.find).map(Some).map_err(|_| {
            "El patrón de búsqueda no es una expresión regular válida compatible con Rust."
                .to_owned()
        })
    } else {
        Ok(None)
    }
}

fn resolve_keep_column_names(
    frame: &DataFrame,
    keep_columns: Option<&[String]>,
    renames: &HashMap<&str, &str>,
) -> Result<(Vec<String>, usize, bool), String> {
    let Some(keep_columns) = keep_columns else {
        return Ok((Vec::new(), 0, false));
    };
    if keep_columns.is_empty() {
        return Err("Debes conservar al menos una columna.".into());
    }
    let mut seen = HashSet::new();
    let names = keep_columns
        .iter()
        .map(|name| {
            if !seen.insert(name) {
                return Err(format!(
                    "La columna '{name}' aparece más de una vez en la selección."
                ));
            }
            let effective = remapped_name(name, renames).to_owned();
            recipe_column(frame, &effective)?;
            Ok(effective)
        })
        .collect::<Result<Vec<_>, String>>()?;
    let order_changed = frame
        .get_column_names()
        .iter()
        .map(|name| name.as_str())
        .ne(names.iter().map(String::as_str));
    Ok((
        names,
        frame.width().saturating_sub(keep_columns.len()),
        order_changed,
    ))
}

fn apply_keep_columns(
    frame: DataFrame,
    keep_columns: Option<&[String]>,
    renames: &HashMap<&str, &str>,
) -> Result<(DataFrame, usize, bool), String> {
    let (names, dropped_count, order_changed) =
        resolve_keep_column_names(&frame, keep_columns, renames)?;
    if keep_columns.is_none() {
        return Ok((frame, 0, false));
    }
    let selected = frame
        .select(&names)
        .map_err(|error| format!("No se pudieron conservar las columnas seleccionadas: {error}"))?;
    Ok((selected, dropped_count, order_changed))
}

fn apply_split_column(
    frame: &mut DataFrame,
    split: &SplitColumnRecipe,
    renames: &HashMap<&str, &str>,
) -> Result<(usize, usize), String> {
    if split.delimiter.is_empty() {
        return Err("El delimitador de división no puede estar vacío.".into());
    }
    if !(2..=16).contains(&split.names.len()) {
        return Err("La división requiere entre 2 y 16 columnas de destino.".into());
    }
    let source_name = remapped_name(&split.source, renames);
    let source = recipe_column(frame, source_name)?;
    if source.dtype() != &polars::prelude::DataType::String {
        return Err(format!(
            "La columna '{source_name}' debe ser de texto para dividirse."
        ));
    }
    let mut unique = HashSet::new();
    let names = split
        .names
        .iter()
        .map(|name| {
            let trimmed = name.trim();
            if trimmed.is_empty() || trimmed != name {
                return Err(
                    "Los nombres divididos no pueden estar vacíos ni tener espacios exteriores."
                        .into(),
                );
            }
            if !unique.insert(trimmed) {
                return Err(format!("El nombre dividido '{trimmed}' está duplicado."));
            }
            if frame.column(trimmed).is_ok() {
                return Err(format!("La columna dividida '{trimmed}' ya existe."));
            }
            Ok(trimmed.to_owned())
        })
        .collect::<Result<Vec<_>, String>>()?;
    let source_values = strict_column_text(source)?;
    let mut outputs = vec![Vec::with_capacity(frame.height()); names.len()];
    for value in source_values {
        if let Some(value) = value {
            let parts = value
                .splitn(names.len(), &split.delimiter)
                .collect::<Vec<_>>();
            for (index, output) in outputs.iter_mut().enumerate() {
                output.push(parts.get(index).map(|part| (*part).to_owned()));
            }
        } else {
            outputs.iter_mut().for_each(|output| output.push(None));
        }
    }
    for (name, values) in names.into_iter().zip(outputs) {
        frame
            .with_column(Series::new(name.into(), values).into_column())
            .map_err(|error| format!("No se pudo crear una columna dividida: {error}"))?;
    }
    let dropped = if split.drop_source {
        frame
            .drop_in_place(source_name)
            .map_err(|error| format!("No se pudo descartar '{source_name}': {error}"))?;
        1
    } else {
        0
    };
    Ok((split.names.len(), dropped))
}

fn apply_merge_columns(
    frame: &mut DataFrame,
    merge: &MergeColumnsRecipe,
    renames: &HashMap<&str, &str>,
) -> Result<(usize, usize), String> {
    if !(2..=16).contains(&merge.sources.len()) {
        return Err("La unión requiere entre 2 y 16 columnas fuente.".into());
    }
    if merge.name.trim().is_empty() || merge.name != merge.name.trim() {
        return Err(
            "El nombre de la columna unida no puede estar vacío ni tener espacios exteriores."
                .into(),
        );
    }
    if frame.column(&merge.name).is_ok() {
        return Err(format!("La columna unida '{}' ya existe.", merge.name));
    }
    let mut unique = HashSet::new();
    let sources = merge
        .sources
        .iter()
        .map(|source| {
            if !unique.insert(source) {
                return Err(format!("La columna fuente '{source}' está duplicada."));
            }
            let effective = remapped_name(source, renames).to_owned();
            let column = recipe_column(frame, &effective)?;
            if column.dtype() != &polars::prelude::DataType::String {
                return Err(format!(
                    "La columna '{effective}' debe ser de texto para unirse."
                ));
            }
            Ok(effective)
        })
        .collect::<Result<Vec<_>, String>>()?;
    let columns = sources
        .iter()
        .map(|name| strict_column_text(recipe_column(frame, name)?))
        .collect::<Result<Vec<_>, _>>()?;
    let merged = (0..frame.height())
        .map(|row| {
            let values = columns
                .iter()
                .filter_map(|column| column[row].as_deref())
                .collect::<Vec<_>>();
            (!values.is_empty()).then(|| values.join(&merge.separator))
        })
        .collect::<Vec<_>>();
    frame
        .with_column(Series::new(merge.name.clone().into(), merged).into_column())
        .map_err(|error| format!("No se pudo crear la columna unida: {error}"))?;
    let dropped = if merge.drop_sources {
        for source in &sources {
            frame
                .drop_in_place(source)
                .map_err(|error| format!("No se pudo descartar '{source}': {error}"))?;
        }
        sources.len()
    } else {
        0
    };
    Ok((1, dropped))
}

fn outlier_linear_quantile(sorted: &[f64], probability: f64) -> f64 {
    let position = probability * (sorted.len() - 1) as f64;
    let lower = position.floor() as usize;
    let upper = position.ceil() as usize;
    let weight = position - lower as f64;
    sorted[lower] * (1.0 - weight) + sorted[upper] * weight
}

fn physical_numeric_values(column: &Column) -> Result<Vec<Option<f64>>, String> {
    let name = column.name();
    (0..column.len())
        .map(|row| {
            let value = column.get(row).map_err(|error| error.to_string())?;
            match value {
                AnyValue::Null => Ok(None),
                AnyValue::Int64(value) if value.unsigned_abs() <= (1_u64 << 53) => Ok(Some(value as f64)),
                AnyValue::Int64(value) => Err(format!("La columna '{name}' contiene un entero fuera de la precisión segura en la fila {}: {value}.", row + 1)),
                AnyValue::Float64(value) if value.is_finite() => Ok(Some(value)),
                AnyValue::Float64(_) => Err(format!(
                    "La columna '{name}' contiene NaN o infinito en la fila {}.",
                    row + 1
                )),
                _ => Err(format!("La columna '{name}' debe ser Int64 o Float64 para tratar valores numéricos.")),
            }
        })
        .collect()
}

type PreparedOutlierTreatment = (
    String,
    OutlierAction,
    Vec<Option<f64>>,
    f64,
    f64,
    f64,
    DataType,
);

fn prepare_outlier_treatments(
    frame: &DataFrame,
    treatments: &[OutlierTreatment],
    renames: &HashMap<&str, &str>,
) -> Result<Vec<PreparedOutlierTreatment>, String> {
    if treatments.len() > 16 {
        return Err("La receta admite como máximo 16 tratamientos de atípicos.".into());
    }
    let mut unique = HashSet::new();
    let mut prepared = Vec::with_capacity(treatments.len());
    for treatment in treatments {
        if !unique.insert(treatment.column.as_str()) {
            return Err(format!(
                "La columna '{}' tiene más de un tratamiento de atípicos.",
                treatment.column
            ));
        }
        let name = remapped_name(&treatment.column, renames).to_owned();
        let column = recipe_column(frame, &name)?;
        if !matches!(
            column.dtype(),
            polars::prelude::DataType::Int64 | polars::prelude::DataType::Float64
        ) {
            return Err(format!(
                "La columna '{name}' debe ser Int64 o Float64 para tratar valores numéricos."
            ));
        }
        let values = physical_numeric_values(column)?;
        let mut valid = values.iter().flatten().copied().collect::<Vec<_>>();
        if valid.len() < 4 {
            return Err(format!(
                "La columna '{name}' requiere al menos cuatro valores numéricos válidos."
            ));
        }
        valid.sort_by(f64::total_cmp);
        let q1 = outlier_linear_quantile(&valid, 0.25);
        let q3 = outlier_linear_quantile(&valid, 0.75);
        let iqr = q3 - q1;
        let lower = q1 - 1.5 * iqr;
        let upper = q3 + 1.5 * iqr;
        if ![q1, q3, iqr, lower, upper].into_iter().all(f64::is_finite) {
            return Err(format!(
                "Los umbrales IQR de '{name}' exceden el rango numérico finito."
            ));
        }
        let median = if column.dtype() == &DataType::Int64 {
            valid[(valid.len() - 1) / 2]
        } else {
            outlier_linear_quantile(&valid, 0.5)
        };
        prepared.push((
            name,
            treatment.action,
            values,
            lower,
            upper,
            median,
            column.dtype().clone(),
        ));
    }
    Ok(prepared)
}

fn apply_outlier_treatments(
    mut frame: DataFrame,
    treatments: &[OutlierTreatment],
    renames: &HashMap<&str, &str>,
) -> Result<(DataFrame, usize, usize, usize), String> {
    let prepared = prepare_outlier_treatments(&frame, treatments, renames)?;

    let baseline_height = frame.height();
    let mut drop_mask = vec![false; baseline_height];
    let mut adjusted = 0;
    for (name, action, values, lower, upper, median, dtype) in prepared {
        match action {
            OutlierAction::Cap => {
                let capped = values
                    .into_iter()
                    .map(|value| {
                        value.map(|value| {
                            let capped = value.clamp(lower, upper);
                            if capped != value {
                                adjusted += 1;
                            }
                            capped
                        })
                    })
                    .collect::<Vec<_>>();
                if capped
                    .iter()
                    .zip((0..baseline_height).map(|row| {
                        frame
                            .column(&name)
                            .unwrap()
                            .get(row)
                            .ok()
                            .and_then(numeric_value)
                    }))
                    .any(|(left, right)| *left != right)
                {
                    frame
                        .replace(
                            &name,
                            Series::new(name.clone().into(), capped).into_column(),
                        )
                        .map_err(|error| format!("No se pudo limitar '{name}': {error}"))?;
                }
            }
            OutlierAction::Drop => {
                for (row, value) in values.into_iter().enumerate() {
                    if value.is_some_and(|value| value < lower || value > upper) {
                        drop_mask[row] = true;
                    }
                }
            }
            OutlierAction::Impute => {
                let imputed = values
                    .into_iter()
                    .map(|value| {
                        value.map(|value| {
                            if value < lower || value > upper {
                                adjusted += 1;
                                median
                            } else {
                                value
                            }
                        })
                    })
                    .collect::<Vec<_>>();
                let replacement_column = Column::new(name.clone().into(), imputed)
                    .cast(&dtype)
                    .map_err(|error| format!("No se pudo imputar '{name}': {error}"))?;
                frame
                    .replace(&name, replacement_column)
                    .map_err(|error| format!("No se pudo actualizar '{name}': {error}"))?;
            }
        }
    }
    let keep = drop_mask.iter().map(|drop| !drop).collect::<Vec<_>>();
    let removed = drop_mask.iter().filter(|drop| **drop).count();
    if removed > 0 {
        frame = frame
            .filter(&BooleanChunked::from_slice("outliers".into(), &keep))
            .map_err(|error| format!("No se pudieron retirar filas atípicas: {error}"))?;
    }
    Ok((frame, adjusted, removed, treatments.len()))
}

fn apply_group_summary(
    frame: DataFrame,
    summary: &GroupSummaryRecipe,
    renames: &HashMap<&str, &str>,
) -> Result<(DataFrame, usize, usize, usize), String> {
    if summary.group_by.is_empty() || summary.group_by.len() > 8 {
        return Err("Agrupar requiere entre 1 y 8 columnas clave.".into());
    }
    if summary.aggregations.is_empty() || summary.aggregations.len() > 32 {
        return Err("Resumir requiere entre 1 y 32 agregaciones.".into());
    }
    let groups = summary
        .group_by
        .iter()
        .map(|name| remapped_name(name, renames).to_owned())
        .collect::<Vec<_>>();
    let mut group_unique = HashSet::new();
    for name in &groups {
        if !group_unique.insert(name) {
            return Err(format!("La clave de grupo '{name}' está duplicada."));
        }
        recipe_column(&frame, name)?;
    }
    let mut aggregation_unique = HashSet::new();
    let mut output_names = HashSet::new();
    let aggregations = summary
        .aggregations
        .iter()
        .map(|aggregation| {
            let name = remapped_name(&aggregation.column, renames).to_owned();
            if !aggregation_unique.insert((name.clone(), aggregation.operation)) {
                return Err(format!(
                    "La agregación '{}_{}' está duplicada.",
                    name,
                    aggregation.operation.suffix()
                ));
            }
            let output = format!("{}_{}", name, aggregation.operation.suffix());
            if group_unique.contains(&output) || !output_names.insert(output.clone()) {
                return Err(format!(
                    "El nombre de salida '{output}' colisiona con otra columna."
                ));
            }
            let column = recipe_column(&frame, &name)?;
            match aggregation.operation {
                SummaryOperation::Sum | SummaryOperation::Mean
                    if !matches!(
                        column.dtype(),
                        polars::prelude::DataType::Int64 | polars::prelude::DataType::Float64
                    ) =>
                {
                    return Err(format!(
                        "La agregación {} requiere que '{name}' sea Int64 o Float64.",
                        aggregation.operation.suffix()
                    ))
                }
                SummaryOperation::Min | SummaryOperation::Max
                    if !matches!(
                        column.dtype(),
                        polars::prelude::DataType::Int64
                            | polars::prelude::DataType::Float64
                            | polars::prelude::DataType::String
                            | polars::prelude::DataType::Date
                            | polars::prelude::DataType::Datetime(_, _)
                    ) =>
                {
                    return Err(format!(
                        "La agregación {} no admite el tipo de '{name}'.",
                        aggregation.operation.suffix()
                    ))
                }
                _ => {}
            }
            Ok((name, output, aggregation.operation))
        })
        .collect::<Result<Vec<_>, String>>()?;

    let mut positions: HashMap<Vec<Option<String>>, usize> = HashMap::new();
    let mut buckets: Vec<Vec<IdxSize>> = Vec::new();
    for row in 0..frame.height() {
        let key = groups
            .iter()
            .map(|name| {
                match frame
                    .column(name)
                    .unwrap()
                    .get(row)
                    .map_err(|error| error.to_string())?
                {
                    AnyValue::Null => Ok(None),
                    AnyValue::Float64(value) if !value.is_finite() => Err(format!(
                        "La clave de grupo '{name}' contiene NaN o infinito."
                    )),
                    AnyValue::Float64(0.0) => Ok(Some("0".into())),
                    value => Ok(Some(value.to_string())),
                }
            })
            .collect::<Result<Vec<_>, String>>()?;
        let index = if let Some(index) = positions.get(&key) {
            *index
        } else {
            let index = buckets.len();
            positions.insert(key, index);
            buckets.push(Vec::new());
            index
        };
        buckets[index].push(row as IdxSize);
    }
    let first_rows = buckets.iter().map(|rows| rows[0]).collect::<Vec<_>>();
    let mut columns = groups
        .iter()
        .map(|name| {
            frame
                .column(name)
                .unwrap()
                .take_slice(&first_rows)
                .map_err(|error| error.to_string())
        })
        .collect::<Result<Vec<_>, _>>()?;
    for (name, output, operation) in aggregations {
        let source = frame.column(&name).map_err(|error| error.to_string())?;
        let result = match operation {
            SummaryOperation::Count => Series::new(
                output.clone().into(),
                buckets
                    .iter()
                    .map(|rows| rows.len() as i64)
                    .collect::<Vec<_>>(),
            )
            .into_column(),
            SummaryOperation::CountUnique => {
                let counts = buckets
                    .iter()
                    .map(|rows| {
                        let mut unique = HashSet::new();
                        for row in rows {
                            match source.get(*row as usize).unwrap() {
                                AnyValue::Null => {}
                                AnyValue::Float64(value) if !value.is_finite() => {
                                    return Err(format!(
                                        "La columna '{name}' contiene NaN o infinito."
                                    ));
                                }
                                AnyValue::Float64(0.0) => {
                                    unique.insert("0".to_owned());
                                }
                                value => {
                                    unique.insert(value.to_string());
                                }
                            }
                        }
                        Ok(unique.len() as i64)
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                Series::new(output.clone().into(), counts).into_column()
            }
            SummaryOperation::Sum if source.dtype() == &polars::prelude::DataType::Int64 => {
                let values = buckets
                    .iter()
                    .map(|rows| {
                        rows.iter().try_fold(0_i64, |total, row| {
                            match source.get(*row as usize).unwrap() {
                                AnyValue::Null => Ok(total),
                                AnyValue::Int64(value) => total
                                    .checked_add(value)
                                    .ok_or_else(|| format!("La suma de '{name}' desbordó Int64.")),
                                _ => unreachable!(),
                            }
                        })
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                Series::new(output.clone().into(), values).into_column()
            }
            SummaryOperation::Sum | SummaryOperation::Mean => {
                let is_mean = operation == SummaryOperation::Mean;
                let values = buckets
                    .iter()
                    .map(|rows| {
                        let mut sum = 0.0;
                        let mut count = 0;
                        for row in rows {
                            match source.get(*row as usize).unwrap() {
                                AnyValue::Null => {}
                                AnyValue::Int64(value) => {
                                    if value.unsigned_abs() > (1_u64 << 53) {
                                        return Err(format!(
                                            "La media de '{name}' excede la precisión segura."
                                        ));
                                    }
                                    sum += value as f64;
                                    count += 1;
                                }
                                AnyValue::Float64(value) if value.is_finite() => {
                                    sum += value;
                                    count += 1;
                                }
                                AnyValue::Float64(_) => {
                                    return Err(format!(
                                        "La columna '{name}' contiene NaN o infinito."
                                    ))
                                }
                                _ => unreachable!(),
                            }
                        }
                        if !sum.is_finite() {
                            return Err(format!(
                                "La agregación de '{name}' produjo un valor no finito."
                            ));
                        }
                        Ok(if is_mean {
                            (count > 0).then(|| sum / count as f64)
                        } else {
                            Some(sum)
                        })
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                Series::new(output.clone().into(), values).into_column()
            }
            SummaryOperation::Min | SummaryOperation::Max => {
                let take_max = operation == SummaryOperation::Max;
                let selected = buckets
                    .iter()
                    .map(|rows| {
                        let mut best: Option<(IdxSize, AnyValue<'_>)> = None;
                        for row in rows {
                            let value = source.get(*row as usize).unwrap();
                            if !matches!(value, AnyValue::Null) {
                                if matches!(value, AnyValue::Float64(v) if !v.is_finite()) {
                                    return Err(format!(
                                        "La columna '{name}' contiene NaN o infinito."
                                    ));
                                }
                                let better = best.as_ref().is_none_or(|(_, current)| {
                                    match (&value, current) {
                                        (AnyValue::Int64(a), AnyValue::Int64(b)) => {
                                            if take_max {
                                                a > b
                                            } else {
                                                a < b
                                            }
                                        }
                                        (AnyValue::Float64(a), AnyValue::Float64(b)) => {
                                            if take_max {
                                                a > b
                                            } else {
                                                a < b
                                            }
                                        }
                                        _ => {
                                            if take_max {
                                                value.to_string() > current.to_string()
                                            } else {
                                                value.to_string() < current.to_string()
                                            }
                                        }
                                    }
                                });
                                if better {
                                    best = Some((*row, value));
                                }
                            }
                        }
                        Ok(best.map(|(row, _)| row))
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                match source.dtype() {
                    polars::prelude::DataType::Int64 => Series::new(
                        output.clone().into(),
                        selected
                            .iter()
                            .map(|row| {
                                row.map(|row| match source.get(row as usize).unwrap() {
                                    AnyValue::Int64(value) => value,
                                    _ => unreachable!(),
                                })
                            })
                            .collect::<Vec<_>>(),
                    )
                    .into_column(),
                    polars::prelude::DataType::Float64 => Series::new(
                        output.clone().into(),
                        selected
                            .iter()
                            .map(|row| {
                                row.map(|row| match source.get(row as usize).unwrap() {
                                    AnyValue::Float64(value) => value,
                                    _ => unreachable!(),
                                })
                            })
                            .collect::<Vec<_>>(),
                    )
                    .into_column(),
                    polars::prelude::DataType::String => Series::new(
                        output.clone().into(),
                        selected
                            .iter()
                            .map(|row| {
                                row.map(|row| match source.get(row as usize).unwrap() {
                                    AnyValue::String(value) => value.to_owned(),
                                    AnyValue::StringOwned(value) => value.to_string(),
                                    _ => unreachable!(),
                                })
                            })
                            .collect::<Vec<_>>(),
                    )
                    .into_column(),
                    polars::prelude::DataType::Date => {
                        let physical = source
                            .cast(&polars::prelude::DataType::Int32)
                            .map_err(|error| error.to_string())?;
                        Series::new(
                            output.clone().into(),
                            selected
                                .iter()
                                .map(|row| {
                                    row.map(|row| match physical.get(row as usize).unwrap() {
                                        AnyValue::Int32(value) => value,
                                        _ => unreachable!(),
                                    })
                                })
                                .collect::<Vec<_>>(),
                        )
                        .cast(&polars::prelude::DataType::Date)
                        .map_err(|error| error.to_string())?
                        .into_column()
                    }
                    polars::prelude::DataType::Datetime(unit, zone) => {
                        let physical = source
                            .cast(&polars::prelude::DataType::Int64)
                            .map_err(|error| error.to_string())?;
                        Series::new(
                            output.clone().into(),
                            selected
                                .iter()
                                .map(|row| {
                                    row.map(|row| match physical.get(row as usize).unwrap() {
                                        AnyValue::Int64(value) => value,
                                        _ => unreachable!(),
                                    })
                                })
                                .collect::<Vec<_>>(),
                        )
                        .cast(&polars::prelude::DataType::Datetime(*unit, zone.clone()))
                        .map_err(|error| error.to_string())?
                        .into_column()
                    }
                    _ => unreachable!(),
                }
            }
        };
        columns.push(result);
    }
    let group_count = buckets.len();
    let collapsed = frame.height().saturating_sub(group_count);
    Ok((
        DataFrame::new(group_count, columns).map_err(|error| error.to_string())?,
        group_count,
        summary.aggregations.len(),
        collapsed,
    ))
}

fn apply_contact_normalizations(
    frame: &mut DataFrame,
    treatments: &[ContactNormalization],
    renames: &HashMap<&str, &str>,
) -> Result<(usize, usize), String> {
    if treatments.len() > 16 {
        return Err("La receta admite como máximo 16 normalizaciones de contacto.".into());
    }
    let mut unique = HashSet::new();
    let mut changed_cells = 0;
    for treatment in treatments {
        if !unique.insert(treatment.column.as_str()) {
            return Err(format!(
                "La columna '{}' tiene más de una normalización de contacto.",
                treatment.column
            ));
        }
        let name = remapped_name(&treatment.column, renames).to_owned();
        let column = recipe_column(frame, &name)?;
        if column.dtype() != &polars::prelude::DataType::String {
            return Err(format!(
                "La columna '{name}' debe ser de texto para normalizar contactos."
            ));
        }
        let values = strict_column_text(column)?
            .into_iter()
            .map(|value| {
                value.map(|value| {
                    let normalized = match treatment.kind {
                        ContactKind::Email => value.trim().to_lowercase(),
                        ContactKind::Phone => {
                            let trimmed = value.trim();
                            let plus = trimmed.starts_with('+');
                            let digits = trimmed
                                .chars()
                                .filter(char::is_ascii_digit)
                                .collect::<String>();
                            if plus {
                                format!("+{digits}")
                            } else {
                                digits
                            }
                        }
                        ContactKind::Address => {
                            value.split_whitespace().collect::<Vec<_>>().join(" ")
                        }
                    };
                    if normalized != value {
                        changed_cells += 1;
                    }
                    normalized
                })
            })
            .collect::<Vec<_>>();
        frame
            .replace(
                &name,
                Series::new(name.clone().into(), values).into_column(),
            )
            .map_err(|error| error.to_string())?;
    }
    Ok((changed_cells, treatments.len()))
}

fn first_run(value: &str, matches: impl Fn(char) -> bool) -> Option<String> {
    let mut output = String::new();
    let mut started = false;
    for character in value.chars() {
        if matches(character) {
            started = true;
            output.push(character);
        } else if started {
            break;
        }
    }
    started.then_some(output)
}

fn apply_text_extractions(
    frame: &mut DataFrame,
    extractions: &[TextExtraction],
    renames: &HashMap<&str, &str>,
) -> Result<usize, String> {
    if extractions.len() > 16 {
        return Err("La receta admite como máximo 16 extracciones de texto.".into());
    }
    let mut names = HashSet::new();
    for extraction in extractions {
        if extraction.name.trim().is_empty() || extraction.name != extraction.name.trim() {
            return Err(
                "El nombre extraído no puede estar vacío ni tener espacios exteriores.".into(),
            );
        }
        if !names.insert(extraction.name.as_str()) {
            return Err(format!(
                "La columna extraída '{}' está duplicada.",
                extraction.name
            ));
        }
        if frame.column(&extraction.name).is_ok() {
            return Err(format!(
                "La columna extraída '{}' ya existe.",
                extraction.name
            ));
        }
        let delimiter_based = matches!(
            extraction.kind,
            ExtractionKind::Before | ExtractionKind::After
        );
        if delimiter_based != extraction.delimiter.is_some() {
            return Err(format!(
                "La extracción '{}' {} delimitador.",
                extraction.name,
                if delimiter_based {
                    "requiere"
                } else {
                    "no acepta"
                }
            ));
        }
        if extraction.delimiter.as_deref().is_some_and(str::is_empty) {
            return Err("El delimitador de extracción no puede estar vacío.".into());
        }
        let source_name = remapped_name(&extraction.source, renames);
        let source = recipe_column(frame, source_name)?;
        if source.dtype() != &polars::prelude::DataType::String {
            return Err(format!(
                "La columna '{source_name}' debe ser de texto para extraerse."
            ));
        }
        let values = strict_column_text(source)?
            .into_iter()
            .map(|value| {
                value.and_then(|value| match extraction.kind {
                    ExtractionKind::FirstToken => {
                        value.split_whitespace().next().map(str::to_owned)
                    }
                    ExtractionKind::LastToken => value.split_whitespace().last().map(str::to_owned),
                    ExtractionKind::Digits => {
                        first_run(&value, |character| character.is_ascii_digit())
                    }
                    ExtractionKind::Letters => first_run(&value, char::is_alphabetic),
                    ExtractionKind::Before => value
                        .find(extraction.delimiter.as_deref().unwrap())
                        .map(|index| value[..index].to_owned()),
                    ExtractionKind::After => value
                        .find(extraction.delimiter.as_deref().unwrap())
                        .map(|index| {
                            value[index + extraction.delimiter.as_deref().unwrap().len()..]
                                .to_owned()
                        }),
                })
            })
            .collect::<Vec<_>>();
        frame
            .with_column(Series::new(extraction.name.clone().into(), values).into_column())
            .map_err(|error| error.to_string())?;
    }
    Ok(extractions.len())
}

type RecipeFrameOutcome = (
    DataFrame,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    bool,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
    usize,
);

type LazySummaryAggregation = (String, String, SummaryOperation);
type LazySummaryPlan = (Vec<String>, Vec<LazySummaryAggregation>);
type LazyContactTarget = (String, ContactKind);
type LazyTextExtractionTarget = (String, ExtractionKind, Option<String>);

fn lazy_renames_have_no_cycles(recipe: &TransformRecipe) -> bool {
    recipe.renames.iter().all(|rename| {
        let mut current = rename.from.as_str();
        let mut visited = HashSet::new();
        while let Some(next) = recipe
            .renames
            .iter()
            .find(|candidate| candidate.from == current)
            .map(|candidate| candidate.to.as_str())
        {
            if !visited.insert(current) {
                return false;
            }
            current = next;
        }
        true
    })
}

fn lazy_outlier_columns_survive_keep(recipe: &TransformRecipe) -> bool {
    let remap = |name: &str| {
        recipe
            .renames
            .iter()
            .find(|rename| rename.from == name)
            .map_or_else(|| name.to_owned(), |rename| rename.to.clone())
    };
    recipe.keep_columns.as_ref().is_none_or(|keep_columns| {
        recipe.outlier_treatments.iter().all(|treatment| {
            let effective_name = remap(&treatment.column);
            keep_columns
                .iter()
                .any(|name| remap(name) == effective_name)
        })
    })
}

fn lazy_iso8601_value_supported(value: &str) -> bool {
    let trimmed = value.trim();
    parse_recipe_datetime(trimmed, RecipeDateFormat::Iso8601).is_ok()
        && (DateTime::parse_from_rfc3339(trimmed).is_err() || trimmed.ends_with('Z'))
}

fn lazy_iso8601_column_supported(column: &Column) -> bool {
    column.dtype() == &DataType::String
        && strict_column_text(column).is_ok_and(|values| {
            values
                .iter()
                .flatten()
                .all(|value| lazy_iso8601_value_supported(value))
        })
}

fn lazy_recipe_supported(source: &DataFrame, recipe: &TransformRecipe) -> bool {
    lazy_renames_have_no_cycles(recipe)
        && lazy_outlier_columns_survive_keep(recipe)
        && recipe
            .date_parses
            .iter()
            .all(|parse| match recipe_column(source, &parse.column) {
                Ok(column)
                    if matches!(
                        parse.format,
                        RecipeDateFormat::Ymd
                            | RecipeDateFormat::Dmy
                            | RecipeDateFormat::Mdy
                            | RecipeDateFormat::Iso8601
                    ) =>
                {
                    (if matches!(parse.format, RecipeDateFormat::Iso8601) {
                        lazy_iso8601_column_supported(column)
                    } else {
                        matches!(column.dtype(), DataType::String)
                    }) || matches!(
                        (column.dtype(), parse.target),
                        (DataType::Date, RecipeDateTarget::Date)
                            | (DataType::Datetime(_, _), RecipeDateTarget::Datetime)
                    )
                }
                _ => false,
            })
        && !recipe
            .date_parses
            .iter()
            .any(|parse| recipe.casts.iter().any(|cast| cast.column == parse.column))
        && (recipe.outlier_treatments.is_empty()
            || (recipe.casts.is_empty()
                && recipe.date_parses.is_empty()
                && recipe.find_replace.is_none()
                && recipe.calculated_column.is_none()
                && recipe.split_column.is_none()
                && recipe.merge_columns.is_none()
                && recipe.group_summary.is_none()
                && recipe.contact_normalizations.is_empty()
                && recipe.text_extractions.is_empty()
                && recipe.outlier_treatments.iter().all(|treatment| {
                    recipe_column(source, &treatment.column).is_ok_and(|column| {
                        matches!(column.dtype(), DataType::Int64 | DataType::Float64)
                    })
                })))
        && recipe.calculated_column.as_ref().is_none_or(|calculation| {
            matches!(
                calculation.operation,
                CalculatedOperation::Add
                    | CalculatedOperation::Subtract
                    | CalculatedOperation::Multiply
                    | CalculatedOperation::Divide
                    | CalculatedOperation::Concat
            ) || (matches!(
                calculation.operation,
                CalculatedOperation::Year | CalculatedOperation::Month | CalculatedOperation::Day
            ) && recipe
                .casts
                .iter()
                .all(|cast| cast.column != calculation.source)
                && (recipe_column(source, &calculation.source).is_ok_and(|column| {
                    matches!(column.dtype(), DataType::Date | DataType::Datetime(_, None))
                }) || recipe.date_parses.iter().any(|parse| {
                    parse.column == calculation.source
                        && matches!(
                            parse.target,
                            RecipeDateTarget::Date | RecipeDateTarget::Datetime
                        )
                })))
        })
}

fn validate_lazy_recipe_inputs(source: &DataFrame, recipe: &TransformRecipe) -> Result<(), String> {
    for cast in &recipe.casts {
        let column = recipe_column(source, &cast.column)?;
        let already_target = matches!(
            (column.dtype(), cast.target),
            (DataType::String, RecipeCastTarget::String)
                | (DataType::Int64, RecipeCastTarget::Integer)
                | (DataType::Float64, RecipeCastTarget::Decimal)
                | (DataType::Boolean, RecipeCastTarget::Boolean)
        );
        if !already_target {
            strict_cast_column(column, cast.target)?;
        }
    }

    for filter in &recipe.filters {
        let name = filter.column.as_str();
        let column = recipe_column(source, name)?;
        let date_parse = recipe.date_parses.iter().find(|parse| parse.column == name);
        let native_temporal =
            matches!(column.dtype(), DataType::Date | DataType::Datetime(_, None));
        if !recipe_filter_is_ordered(filter.operator)
            && !(recipe_filter_uses_temporal_literal(filter.operator) && date_parse.is_some())
            && !native_temporal
        {
            continue;
        }
        let values = strict_column_text(column)?;
        for (row, value) in values.iter().enumerate() {
            if let Some(value) = value {
                if let Some(parse) = date_parse {
                    parse_recipe_datetime(value, parse.format).map_err(|_| {
                        format!(
                            "La fila {} de la columna '{}' contiene una fecha no válida.",
                            row + 1,
                            name
                        )
                    })?;
                } else if matches!(column.dtype(), DataType::Date | DataType::Datetime(_, None)) {
                    parse_recipe_filter_datetime(value, name).map_err(|_| {
                        format!(
                            "La fila {} de la columna '{}' contiene una fecha no válida.",
                            row + 1,
                            name
                        )
                    })?;
                } else if recipe_filter_is_ordered(filter.operator) {
                    strict_f64(
                        value,
                        &format!("La fila {} de la columna '{name}'", row + 1),
                    )?;
                }
            }
        }
    }

    if let Some(calculation) = &recipe.calculated_column {
        let unary = matches!(
            calculation.operation,
            CalculatedOperation::Year | CalculatedOperation::Month | CalculatedOperation::Day
        );
        if unary != calculation.operand.is_none() {
            return Err(if unary {
                "year, month y day no aceptan operando.".into()
            } else {
                "La operación calculada requiere un operando.".into()
            });
        }
        if unary {
            let source_column = recipe_column(source, &calculation.source)?;
            let parsed_as_date = recipe.date_parses.iter().any(|parse| {
                parse.column == calculation.source
                    && matches!(
                        parse.target,
                        RecipeDateTarget::Date | RecipeDateTarget::Datetime
                    )
            });
            if !parsed_as_date {
                validate_date_parts_column(source_column)?;
            }
        }
        if matches!(
            calculation.operation,
            CalculatedOperation::Add
                | CalculatedOperation::Subtract
                | CalculatedOperation::Multiply
                | CalculatedOperation::Divide
        ) {
            let source_name = calculation.source.as_str();
            let source_values = strict_column_text(recipe_column(source, source_name)?)?;
            let source_numbers = source_values
                .iter()
                .enumerate()
                .map(|(row, value)| {
                    value
                        .as_deref()
                        .map(|value| {
                            strict_f64(value, &format!("La fila {} de '{source_name}'", row + 1))
                        })
                        .transpose()
                })
                .collect::<Result<Vec<_>, String>>()?;
            let operand_numbers = match calculation.operand.as_ref().unwrap() {
                CalculatedOperand {
                    kind: CalculatedOperandKind::Literal,
                    value,
                } => {
                    if value.is_empty() {
                        return Err("El operando numérico no puede estar vacío.".into());
                    }
                    vec![Some(strict_f64(value, "El operando numérico")?); source.height()]
                }
                CalculatedOperand {
                    kind: CalculatedOperandKind::Column,
                    value,
                } => strict_column_text(recipe_column(source, value)?)?
                    .iter()
                    .enumerate()
                    .map(|(row, value)| {
                        value
                            .as_deref()
                            .map(|value| {
                                strict_f64(value, &format!("El operando de la fila {}", row + 1))
                            })
                            .transpose()
                    })
                    .collect::<Result<Vec<_>, String>>()?,
            };
            for (row, (left, right)) in source_numbers.iter().zip(&operand_numbers).enumerate() {
                let (Some(left), Some(right)) = (left, right) else {
                    continue;
                };
                if calculation.operation == CalculatedOperation::Divide && *right == 0.0 {
                    return Err(format!("División por cero en la fila {}.", row + 1));
                }
                let result = match calculation.operation {
                    CalculatedOperation::Add => left + right,
                    CalculatedOperation::Subtract => left - right,
                    CalculatedOperation::Multiply => left * right,
                    CalculatedOperation::Divide => left / right,
                    _ => unreachable!(),
                };
                if !result.is_finite() {
                    return Err(format!(
                        "El cálculo produjo un valor no finito en la fila {}.",
                        row + 1
                    ));
                }
            }
        }
    }
    Ok(())
}

fn lazy_filter_expression(
    column_dtype: &DataType,
    filter: &RecipeFilter,
    effective_name: &str,
) -> Result<Expr, String> {
    let unary = matches!(
        filter.operator,
        RecipeFilterOperator::IsNull | RecipeFilterOperator::NotNull
    );
    if unary != filter.value.is_none() {
        return Err(format!(
            "El filtro '{}' {} un valor.",
            filter.column,
            if unary { "no acepta" } else { "requiere" }
        ));
    }
    let literal = filter.value.as_deref().unwrap_or_default();
    if matches!(
        filter.operator,
        RecipeFilterOperator::Gt
            | RecipeFilterOperator::Lt
            | RecipeFilterOperator::Gte
            | RecipeFilterOperator::Lte
            | RecipeFilterOperator::Contains
            | RecipeFilterOperator::NotContains
    ) && literal.is_empty()
    {
        return Err(format!(
            "El filtro '{}' requiere un valor no vacío.",
            filter.column
        ));
    }

    let value = col(effective_name);
    Ok(match filter.operator {
        RecipeFilterOperator::IsNull => value.is_null(),
        RecipeFilterOperator::NotNull => value.is_not_null(),
        RecipeFilterOperator::Eq | RecipeFilterOperator::Neq
            if matches!(column_dtype, DataType::Date | DataType::Datetime(_, None)) =>
        {
            let datetime = parse_recipe_filter_datetime(literal, effective_name)?;
            let (value, literal) = match column_dtype {
                DataType::Date => {
                    let epoch =
                        NaiveDate::from_ymd_opt(1970, 1, 1).expect("la época Unix es válida");
                    let days =
                        i32::try_from((datetime.date() - epoch).num_days()).map_err(|_| {
                            "La fecha del filtro está fuera del rango admitido.".to_owned()
                        })?;
                    (value.cast(DataType::Int32), lit(days))
                }
                DataType::Datetime(unit, None) => (
                    value.cast(DataType::Int64),
                    lit(datetime_timestamp_in_unit(datetime, *unit)?),
                ),
                _ => unreachable!("el match exterior limita esta rama a fechas"),
            };
            if filter.operator == RecipeFilterOperator::Eq {
                value.eq(literal)
            } else {
                value.neq(literal)
            }
        }
        RecipeFilterOperator::Eq => value.cast(DataType::String).eq(lit(literal.to_owned())),
        RecipeFilterOperator::Neq => value.cast(DataType::String).neq(lit(literal.to_owned())),
        RecipeFilterOperator::Contains => value
            .cast(DataType::String)
            .str()
            .to_lowercase()
            .str()
            .contains_literal(lit(literal.to_lowercase())),
        RecipeFilterOperator::NotContains => value
            .cast(DataType::String)
            .str()
            .to_lowercase()
            .str()
            .contains_literal(lit(literal.to_lowercase()))
            .not(),
        RecipeFilterOperator::Gt
        | RecipeFilterOperator::Lt
        | RecipeFilterOperator::Gte
        | RecipeFilterOperator::Lte => {
            if matches!(column_dtype, DataType::Date | DataType::Datetime(_, None)) {
                let datetime = parse_recipe_filter_datetime(literal, effective_name)?;
                let (value, literal) = match column_dtype {
                    DataType::Date => {
                        let epoch =
                            NaiveDate::from_ymd_opt(1970, 1, 1).expect("la época Unix es válida");
                        let days =
                            i32::try_from((datetime.date() - epoch).num_days()).map_err(|_| {
                                "La fecha del filtro está fuera del rango admitido.".to_owned()
                            })?;
                        (value.cast(DataType::Int32), lit(days))
                    }
                    DataType::Datetime(unit, None) => (
                        value.cast(DataType::Int64),
                        lit(datetime_timestamp_in_unit(datetime, *unit)?),
                    ),
                    _ => unreachable!("el match exterior limita esta rama a fechas"),
                };
                match filter.operator {
                    RecipeFilterOperator::Gt => value.gt(literal),
                    RecipeFilterOperator::Lt => value.lt(literal),
                    RecipeFilterOperator::Gte => value.gt_eq(literal),
                    RecipeFilterOperator::Lte => value.lt_eq(literal),
                    _ => unreachable!("el match exterior limita esta rama a comparaciones"),
                }
            } else {
                let numeric_literal = strict_f64(literal, "El valor del filtro")?;
                let value = value.strict_cast(DataType::Float64);
                match filter.operator {
                    RecipeFilterOperator::Gt => value.gt(lit(numeric_literal)),
                    RecipeFilterOperator::Lt => value.lt(lit(numeric_literal)),
                    RecipeFilterOperator::Gte => value.gt_eq(lit(numeric_literal)),
                    RecipeFilterOperator::Lte => value.lt_eq(lit(numeric_literal)),
                    _ => {
                        unreachable!("el match exterior limita esta rama a comparaciones numéricas")
                    }
                }
            }
        }
    })
}

fn lazy_find_replace_targets(
    source: &DataFrame,
    recipe: &FindReplaceRecipe,
    renames: &HashMap<&str, &str>,
    casts: &[RecipeCast],
) -> Result<Vec<String>, String> {
    if recipe.find.is_empty() {
        return Err("El texto buscado no puede estar vacío.".into());
    }
    validate_find_replace_pattern(recipe)?;
    let cast_target = |effective_name: &str| {
        casts
            .iter()
            .find(|cast| remapped_name(&cast.column, renames) == effective_name)
            .map(|cast| cast.target)
    };
    let is_text_after_cast = |source_name: &str, source_dtype: &DataType| {
        cast_target(remapped_name(source_name, renames))
            .map(|target| target == RecipeCastTarget::String)
            .unwrap_or(source_dtype == &DataType::String)
    };

    match recipe.scope {
        FindReplaceScope::Column => {
            let column = recipe
                .column
                .as_deref()
                .ok_or_else(|| "La búsqueda por columna requiere una columna.".to_owned())?;
            let source_column = recipe_column(source, column)?;
            let effective_name = remapped_name(column, renames);
            if !is_text_after_cast(column, source_column.dtype()) {
                return Err(format!(
                    "La columna '{effective_name}' debe ser de texto para buscar y reemplazar."
                ));
            }
            Ok(vec![effective_name.to_owned()])
        }
        FindReplaceScope::AllTextColumns => {
            if recipe.column.is_some() {
                return Err(
                    "La búsqueda en todas las columnas no acepta una columna concreta.".into(),
                );
            }
            Ok(source
                .get_column_names()
                .iter()
                .zip(source.columns())
                .filter(|(name, column)| is_text_after_cast(name, column.dtype()))
                .map(|(name, _)| remapped_name(name, renames).to_owned())
                .collect())
        }
    }
}

fn lazy_summary_column(
    source: &DataFrame,
    name: &str,
    renames: &HashMap<&str, &str>,
    casts: &[RecipeCast],
) -> Result<Column, String> {
    let column = recipe_column(source, name)?;
    let effective_name = remapped_name(name, renames);
    let Some(cast) = casts
        .iter()
        .find(|cast| remapped_name(&cast.column, renames) == effective_name)
    else {
        return Ok(column.clone());
    };
    let already_target = matches!(
        (column.dtype(), cast.target),
        (DataType::String, RecipeCastTarget::String)
            | (DataType::Int64, RecipeCastTarget::Integer)
            | (DataType::Float64, RecipeCastTarget::Decimal)
            | (DataType::Boolean, RecipeCastTarget::Boolean)
    );
    if already_target {
        Ok(column.clone())
    } else {
        strict_cast_column(column, cast.target)
    }
}

fn lazy_summary_validation_column(
    source: &DataFrame,
    validation: Option<&DataFrame>,
    name: &str,
    renames: &HashMap<&str, &str>,
    casts: &[RecipeCast],
) -> Result<Column, String> {
    if let Some(validation) = validation {
        let effective_name = remapped_name(name, renames);
        return validation
            .column(effective_name)
            .cloned()
            .map_err(|_| format!("La columna '{effective_name}' no existe en el preflight."));
    }
    lazy_summary_column(source, name, renames, casts)
}

fn lazy_contact_targets(
    source: &DataFrame,
    treatments: &[ContactNormalization],
    renames: &HashMap<&str, &str>,
    casts: &[RecipeCast],
) -> Result<Vec<LazyContactTarget>, String> {
    if treatments.len() > 16 {
        return Err("La receta admite como máximo 16 normalizaciones de contacto.".into());
    }
    let mut unique = HashSet::new();
    treatments
        .iter()
        .map(|treatment| {
            if !unique.insert(treatment.column.as_str()) {
                return Err(format!(
                    "La columna '{}' tiene más de una normalización de contacto.",
                    treatment.column
                ));
            }
            let effective_name = remapped_name(&treatment.column, renames).to_owned();
            let column = lazy_summary_column(source, &treatment.column, renames, casts)?;
            if column.dtype() != &DataType::String {
                return Err(format!(
                    "La columna '{effective_name}' debe ser de texto para normalizar contactos."
                ));
            }
            Ok((effective_name, treatment.kind))
        })
        .collect()
}

fn lazy_contact_expression(name: &str, kind: ContactKind) -> Expr {
    let value = col(name);
    match kind {
        ContactKind::Email => value.str().strip_chars(lit(NULL)).str().to_lowercase(),
        ContactKind::Phone => {
            let trimmed = value.clone().str().strip_chars(lit(NULL));
            let digits = value.str().replace_all(lit(r"[^0-9]+"), lit(""), false);
            when(trimmed.str().starts_with(lit("+")))
                .then(concat_str(vec![lit("+"), digits.clone()], "", false))
                .otherwise(digits)
        }
        ContactKind::Address => value
            .str()
            .replace_all(lit(r"(?u)\s+"), lit(" "), false)
            .str()
            .strip_chars(lit(NULL)),
    }
}

fn lazy_text_extraction_targets(
    source: &DataFrame,
    extractions: &[TextExtraction],
    renames: &HashMap<&str, &str>,
    casts: &[RecipeCast],
) -> Result<Vec<LazyTextExtractionTarget>, String> {
    if extractions.len() > 16 {
        return Err("La receta admite como máximo 16 extracciones de texto.".into());
    }
    let mut names = HashSet::new();
    extractions
        .iter()
        .map(|extraction| {
            if extraction.name.trim().is_empty() || extraction.name != extraction.name.trim() {
                return Err(
                    "El nombre extraído no puede estar vacío ni tener espacios exteriores.".into(),
                );
            }
            if !names.insert(extraction.name.as_str()) {
                return Err(format!(
                    "La columna extraída '{}' está duplicada.",
                    extraction.name
                ));
            }
            let delimiter_based = matches!(
                extraction.kind,
                ExtractionKind::Before | ExtractionKind::After
            );
            if delimiter_based != extraction.delimiter.is_some() {
                return Err(format!(
                    "La extracción '{}' {} delimitador.",
                    extraction.name,
                    if delimiter_based {
                        "requiere"
                    } else {
                        "no acepta"
                    }
                ));
            }
            if extraction.delimiter.as_deref().is_some_and(str::is_empty) {
                return Err("El delimitador de extracción no puede estar vacío.".into());
            }
            let effective_source = remapped_name(&extraction.source, renames).to_owned();
            let source_column = lazy_summary_column(source, &extraction.source, renames, casts)?;
            if source_column.dtype() != &DataType::String {
                return Err(format!(
                    "La columna '{effective_source}' debe ser de texto para extraerse."
                ));
            }
            Ok((
                effective_source,
                extraction.kind,
                extraction.delimiter.clone(),
            ))
        })
        .collect()
}

fn lazy_text_extraction_expression(
    name: &str,
    kind: ExtractionKind,
    delimiter: Option<&str>,
) -> Result<Expr, String> {
    let pattern = match kind {
        ExtractionKind::FirstToken => r"(?u)^\s*(\S+)".to_owned(),
        ExtractionKind::LastToken => r"(?u)(\S+)\s*$".to_owned(),
        ExtractionKind::Digits => r"([0-9]+)".to_owned(),
        ExtractionKind::Letters => r"(?u)(\p{Alphabetic}+)".to_owned(),
        ExtractionKind::Before => format!(
            r"(?us)^(.*?){}",
            regex::escape(delimiter.ok_or_else(|| {
                "La extracción antes del delimitador requiere delimitador.".to_owned()
            })?)
        ),
        ExtractionKind::After => format!(
            r"(?us)^.*?{}(.*)$",
            regex::escape(delimiter.ok_or_else(|| {
                "La extracción después del delimitador requiere delimitador.".to_owned()
            })?)
        ),
    };
    Regex::new(&pattern)
        .map_err(|error| format!("No se pudo preparar la extracción de texto: {error}"))?;
    Ok(col(name).str().extract(lit(pattern), 1))
}

fn lazy_summary_group_key(
    column: &Column,
    row: usize,
    name: &str,
) -> Result<Option<String>, String> {
    match column
        .get(row)
        .map_err(|error| format!("No se pudo leer la clave de grupo '{name}': {error}"))?
    {
        AnyValue::Null => Ok(None),
        AnyValue::Float64(value) if !value.is_finite() => Err(format!(
            "La clave de grupo '{name}' contiene NaN o infinito."
        )),
        AnyValue::Float64(0.0) => Ok(Some("0".into())),
        value => Ok(Some(value.to_string())),
    }
}

fn validate_lazy_group_summary(
    source: &DataFrame,
    summary: &GroupSummaryRecipe,
    renames: &HashMap<&str, &str>,
    casts: &[RecipeCast],
    validation: Option<&DataFrame>,
) -> Result<LazySummaryPlan, String> {
    if summary.group_by.is_empty() || summary.group_by.len() > 8 {
        return Err("Agrupar requiere entre 1 y 8 columnas clave.".into());
    }
    if summary.aggregations.is_empty() || summary.aggregations.len() > 32 {
        return Err("Resumir requiere entre 1 y 32 agregaciones.".into());
    }

    let groups = summary
        .group_by
        .iter()
        .map(|name| remapped_name(name, renames).to_owned())
        .collect::<Vec<_>>();
    let mut group_unique = HashSet::new();
    let group_columns = groups
        .iter()
        .zip(&summary.group_by)
        .map(|(effective_name, source_name)| {
            if !group_unique.insert(effective_name.clone()) {
                return Err(format!(
                    "La clave de grupo '{effective_name}' está duplicada."
                ));
            }
            let column =
                lazy_summary_validation_column(source, validation, source_name, renames, casts)?;
            for row in 0..column.len() {
                lazy_summary_group_key(&column, row, effective_name)?;
            }
            Ok(column)
        })
        .collect::<Result<Vec<_>, String>>()?;

    let mut aggregation_unique = HashSet::new();
    let mut output_names = HashSet::new();
    let mut aggregations = Vec::with_capacity(summary.aggregations.len());
    let mut integer_sum_columns = Vec::new();
    for aggregation in &summary.aggregations {
        let name = remapped_name(&aggregation.column, renames).to_owned();
        if !aggregation_unique.insert((name.clone(), aggregation.operation)) {
            return Err(format!(
                "La agregación '{}_{}' está duplicada.",
                name,
                aggregation.operation.suffix()
            ));
        }
        let output = format!("{}_{}", name, aggregation.operation.suffix());
        if group_unique.contains(&output) || !output_names.insert(output.clone()) {
            return Err(format!(
                "El nombre de salida '{output}' colisiona con otra columna."
            ));
        }
        let column = lazy_summary_validation_column(
            source,
            validation,
            &aggregation.column,
            renames,
            casts,
        )?;
        match aggregation.operation {
            SummaryOperation::Sum | SummaryOperation::Mean
                if !matches!(column.dtype(), DataType::Int64 | DataType::Float64) =>
            {
                return Err(format!(
                    "La agregación {} requiere que '{name}' sea Int64 o Float64.",
                    aggregation.operation.suffix()
                ));
            }
            SummaryOperation::Min | SummaryOperation::Max
                if !matches!(
                    column.dtype(),
                    DataType::Int64
                        | DataType::Float64
                        | DataType::String
                        | DataType::Date
                        | DataType::Datetime(_, _)
                ) =>
            {
                return Err(format!(
                    "La agregación {} no admite el tipo de '{name}'.",
                    aggregation.operation.suffix()
                ));
            }
            _ => {}
        }

        if matches!(
            aggregation.operation,
            SummaryOperation::Sum
                | SummaryOperation::Mean
                | SummaryOperation::Min
                | SummaryOperation::Max
                | SummaryOperation::CountUnique
        ) {
            for row in 0..column.len() {
                match column.get(row).map_err(|error| error.to_string())? {
                    AnyValue::Float64(value) if !value.is_finite() => {
                        return Err(format!("La columna '{name}' contiene NaN o infinito."));
                    }
                    AnyValue::Int64(value)
                        if aggregation.operation == SummaryOperation::Mean
                            && value.unsigned_abs() > (1_u64 << 53) =>
                    {
                        return Err(format!("La media de '{name}' excede la precisión segura."));
                    }
                    _ => {}
                }
            }
        }
        if aggregation.operation == SummaryOperation::Sum && column.dtype() == &DataType::Int64 {
            integer_sum_columns.push((name.clone(), column.clone()));
        }
        aggregations.push((name, output, aggregation.operation));
    }

    if !integer_sum_columns.is_empty() {
        let mut sums = vec![HashMap::<Vec<Option<String>>, i64>::new(); integer_sum_columns.len()];
        let validation_height = validation.map_or(source.height(), DataFrame::height);
        for row in 0..validation_height {
            let key = group_columns
                .iter()
                .zip(&groups)
                .map(|(column, name)| lazy_summary_group_key(column, row, name))
                .collect::<Result<Vec<_>, String>>()?;
            for (index, (name, column)) in integer_sum_columns.iter().enumerate() {
                let Some(value) = (match column
                    .get(row)
                    .map_err(|error| format!("No se pudo leer '{name}': {error}"))?
                {
                    AnyValue::Null => None,
                    AnyValue::Int64(value) => Some(value),
                    _ => unreachable!("la validación de tipo garantiza Int64"),
                }) else {
                    continue;
                };
                let total = sums[index].entry(key.clone()).or_insert(0);
                *total = total
                    .checked_add(value)
                    .ok_or_else(|| format!("La suma de '{name}' desbordó Int64."))?;
            }
        }
    }

    Ok((groups, aggregations))
}

fn apply_lazy_recipe_to_frame(
    source: &DataFrame,
    recipe: &TransformRecipe,
) -> Result<RecipeFrameOutcome, String> {
    if recipe.filters.len() > 3 {
        return Err("La receta admite como máximo tres filtros combinados con AND.".into());
    }
    validate_lazy_recipe_inputs(source, recipe)?;

    let mut rename_sources = HashSet::new();
    let rename_map = recipe
        .renames
        .iter()
        .map(|rename| {
            if rename.from.trim().is_empty() || rename.to.trim().is_empty() {
                return Err("Los nombres de columna no pueden estar vacíos.".to_owned());
            }
            if rename.to != rename.to.trim() {
                return Err(
                    "El nuevo nombre de columna no puede tener espacios exteriores.".to_owned(),
                );
            }
            if !rename_sources.insert(rename.from.as_str()) {
                return Err(format!(
                    "La columna '{}' aparece en más de un renombrado.",
                    rename.from
                ));
            }
            recipe_column(source, &rename.from)?;
            Ok((rename.from.as_str(), rename.to.as_str()))
        })
        .collect::<Result<HashMap<_, _>, String>>()?;

    for cast in &recipe.casts {
        recipe_column(source, &cast.column)?;
    }
    for filter in &recipe.filters {
        recipe_column(source, &filter.column)?;
    }
    if let Some(calculation) = &recipe.calculated_column {
        recipe_column(source, &calculation.source)?;
        if let Some(CalculatedOperand {
            kind: CalculatedOperandKind::Column,
            value,
        }) = &calculation.operand
        {
            recipe_column(source, value)?;
        }
        if calculation.name.trim().is_empty() || calculation.name != calculation.name.trim() {
            return Err(
                "El nombre calculado no puede estar vacío ni tener espacios exteriores.".into(),
            );
        }
    }

    let final_names = source
        .get_column_names()
        .iter()
        .map(|name| {
            rename_map
                .get(name.as_str())
                .copied()
                .unwrap_or(name.as_str())
                .to_owned()
        })
        .collect::<Vec<_>>();
    let mut unique_names = HashSet::new();
    if final_names.iter().any(|name| !unique_names.insert(name)) {
        return Err("Los renombrados producirían nombres de columna duplicados.".to_owned());
    }
    let renamed_count = source
        .get_column_names()
        .iter()
        .zip(&final_names)
        .filter(|(before, after)| before.as_str() != after.as_str())
        .count();

    let mut plan = source.clone().lazy();
    if renamed_count > 0 {
        let old_names = source
            .get_column_names()
            .iter()
            .map(|name| name.as_str())
            .collect::<Vec<_>>();
        let new_names = final_names.iter().map(String::as_str).collect::<Vec<_>>();
        plan = plan.rename(old_names, new_names, true);
    }

    let mut cast_columns = HashSet::new();
    let mut cast_expressions = Vec::new();
    let mut cast_count = 0;
    for cast in &recipe.casts {
        let effective_name = rename_map
            .get(cast.column.as_str())
            .copied()
            .unwrap_or(cast.column.as_str());
        if !cast_columns.insert(effective_name) {
            return Err(format!(
                "La columna '{}' aparece en más de una conversión.",
                cast.column
            ));
        }
        let column = recipe_column(source, &cast.column)?;
        let already_target = matches!(
            (column.dtype(), cast.target),
            (DataType::String, RecipeCastTarget::String)
                | (DataType::Int64, RecipeCastTarget::Integer)
                | (DataType::Float64, RecipeCastTarget::Decimal)
                | (DataType::Boolean, RecipeCastTarget::Boolean)
        );
        if !already_target {
            let target = match cast.target {
                RecipeCastTarget::String => DataType::String,
                RecipeCastTarget::Integer => DataType::Int64,
                RecipeCastTarget::Decimal => DataType::Float64,
                RecipeCastTarget::Boolean => DataType::Boolean,
            };
            cast_expressions.push(
                col(effective_name)
                    .strict_cast(target)
                    .alias(effective_name),
            );
            cast_count += 1;
        }
    }
    if !cast_expressions.is_empty() {
        plan = plan.with_columns(cast_expressions);
    }

    let mut date_columns = HashSet::new();
    let mut date_expressions = Vec::new();
    let mut parsed_date_column_count = 0;
    for parse in &recipe.date_parses {
        let effective_name = remapped_name(&parse.column, &rename_map);
        if cast_columns.contains(effective_name) {
            return Err(format!(
                "La columna '{}' no puede convertirse y parsearse como fecha en la misma receta.",
                parse.column
            ));
        }
        if !date_columns.insert(effective_name) {
            return Err(format!(
                "La columna '{}' aparece en más de un parseo de fecha.",
                parse.column
            ));
        }
        let column = recipe_column(source, &parse.column)?;
        let already_target = matches!(
            (column.dtype(), parse.target),
            (DataType::Date, RecipeDateTarget::Date)
                | (DataType::Datetime(_, _), RecipeDateTarget::Datetime)
        );
        if already_target {
            continue;
        }
        if column.dtype() != &DataType::String {
            return Err(format!(
                "La columna '{}' debe ser de texto para parsearse como fecha.",
                parse.column
            ));
        }
        let expression = if parse.format == RecipeDateFormat::Iso8601 {
            let value = col(effective_name)
                .str()
                .strip_chars(lit(NULL))
                .str()
                .replace_all(lit("Z"), lit(""), true);
            let datetime_target = DataType::Datetime(TimeUnit::Milliseconds, None);
            let parsed = [
                "%Y-%m-%d",
                "%Y-%m-%dT%H:%M:%S%.f",
                "%Y-%m-%dT%H:%M:%S",
                "%Y-%m-%d %H:%M:%S%.f",
                "%Y-%m-%d %H:%M:%S",
            ]
            .into_iter()
            .map(|format| {
                value.clone().str().strptime(
                    datetime_target.clone(),
                    StrptimeOptions {
                        format: Some(format.into()),
                        strict: false,
                        ..Default::default()
                    },
                    lit("raise"),
                )
            })
            .collect::<Vec<_>>();
            let parsed = coalesce(&parsed);
            match parse.target {
                RecipeDateTarget::Date => parsed.cast(DataType::Date),
                RecipeDateTarget::Datetime => parsed,
            }
            .alias(effective_name)
        } else {
            let format = match parse.format {
                RecipeDateFormat::Ymd => "%Y-%m-%d",
                RecipeDateFormat::Dmy => "%d/%m/%Y",
                RecipeDateFormat::Mdy => "%m/%d/%Y",
                RecipeDateFormat::Iso8601 => unreachable!(),
            };
            let target = match parse.target {
                RecipeDateTarget::Date => DataType::Date,
                RecipeDateTarget::Datetime => DataType::Datetime(TimeUnit::Milliseconds, None),
            };
            col(effective_name)
                .str()
                .strip_chars(lit(NULL))
                .str()
                .strptime(
                    target,
                    StrptimeOptions {
                        format: Some(format.into()),
                        ..Default::default()
                    },
                    lit("raise"),
                )
                .alias(effective_name)
        };
        date_expressions.push(expression);
        parsed_date_column_count += 1;
    }
    if !date_expressions.is_empty() {
        plan = plan.with_columns(date_expressions);
    }

    for filter in &recipe.filters {
        let effective_name = remapped_name(&filter.column, &rename_map);
        let mut filter_dtype = recipe_column(source, &filter.column)?.dtype().clone();
        if let Some(cast) = recipe
            .casts
            .iter()
            .find(|cast| remapped_name(&cast.column, &rename_map) == effective_name)
        {
            filter_dtype = match cast.target {
                RecipeCastTarget::String => DataType::String,
                RecipeCastTarget::Integer => DataType::Int64,
                RecipeCastTarget::Decimal => DataType::Float64,
                RecipeCastTarget::Boolean => DataType::Boolean,
            };
        }
        if let Some(parse) = recipe
            .date_parses
            .iter()
            .find(|parse| remapped_name(&parse.column, &rename_map) == effective_name)
        {
            filter_dtype = match parse.target {
                RecipeDateTarget::Date => DataType::Date,
                RecipeDateTarget::Datetime => DataType::Datetime(TimeUnit::Milliseconds, None),
            };
        }
        plan = plan.filter(lazy_filter_expression(
            &filter_dtype,
            filter,
            effective_name,
        )?);
    }

    let replaced_cell_count = if let Some(find_replace) = &recipe.find_replace {
        let targets = lazy_find_replace_targets(source, find_replace, &rename_map, &recipe.casts)?;
        if targets.is_empty() {
            0
        } else {
            let count_aliases = targets
                .iter()
                .enumerate()
                .map(|(index, _)| format!("__columnia_replaced_{index}"))
                .collect::<Vec<_>>();
            let count_expressions = targets
                .iter()
                .zip(&count_aliases)
                .map(|(name, alias)| {
                    let original = col(name);
                    let replaced = original.clone().str().replace_all(
                        lit(find_replace.find.clone()),
                        lit(find_replace.replace.clone()),
                        !find_replace.regex,
                    );
                    replaced
                        .neq_missing(original)
                        .cast(DataType::UInt64)
                        .sum()
                        .alias(alias)
                })
                .collect::<Vec<_>>();
            let count_frame = collect_lazy_frame_streaming(
                plan.clone().select(count_expressions),
                "No se pudo contar el reemplazo de texto",
            )?;
            let count = count_aliases
                .iter()
                .map(|alias| {
                    let value = count_frame
                        .column(alias)
                        .map_err(|error| {
                            format!("No se pudo leer el conteo de reemplazos: {error}")
                        })?
                        .get(0)
                        .map_err(|error| {
                            format!("No se pudo leer el conteo de reemplazos: {error}")
                        })?;
                    match value {
                        AnyValue::UInt64(value) => usize::try_from(value).map_err(|_| {
                            "El conteo de reemplazos excede el límite de memoria.".to_owned()
                        }),
                        AnyValue::Int64(value) if value >= 0 => usize::try_from(value as u64)
                            .map_err(|_| {
                                "El conteo de reemplazos excede el límite de memoria.".to_owned()
                            }),
                        AnyValue::Null => Ok(0),
                        _ => Err("El conteo de reemplazos devolvió un tipo inválido.".to_owned()),
                    }
                })
                .collect::<Result<Vec<_>, String>>()?
                .into_iter()
                .sum();
            let replacement_expressions = targets
                .iter()
                .map(|name| {
                    col(name)
                        .str()
                        .replace_all(
                            lit(find_replace.find.clone()),
                            lit(find_replace.replace.clone()),
                            !find_replace.regex,
                        )
                        .alias(name)
                })
                .collect::<Vec<_>>();
            plan = plan.with_columns(replacement_expressions);
            count
        }
    } else {
        0
    };

    let renamed_source = if recipe.keep_columns.is_some() {
        let mut frame = source.clone();
        frame
            .set_column_names(&final_names)
            .map_err(|error| format!("No se pudieron validar las columnas conservadas: {error}"))?;
        Some(frame)
    } else {
        None
    };
    let keep_frame = renamed_source.as_ref().unwrap_or(source);
    let (keep_names, dropped_column_count, kept_order_changed) =
        resolve_keep_column_names(keep_frame, recipe.keep_columns.as_deref(), &rename_map)?;
    if recipe.keep_columns.is_some() {
        plan = plan.select(keep_names.iter().map(col).collect::<Vec<_>>());
    }

    let calculated_column_count = if let Some(calculation) = &recipe.calculated_column {
        let source_name = remapped_name(&calculation.source, &rename_map);
        if recipe.keep_columns.is_some() && !keep_names.iter().any(|name| name == source_name) {
            return Err(format!(
                "La columna fuente calculada '{source_name}' fue descartada por keepColumns."
            ));
        }
        let source_column = recipe_column(source, &calculation.source)?;
        let unary = matches!(
            calculation.operation,
            CalculatedOperation::Year | CalculatedOperation::Month | CalculatedOperation::Day
        );
        if unary != calculation.operand.is_none() {
            return Err(if unary {
                "year, month y day no aceptan operando.".into()
            } else {
                "La operación calculada requiere un operando.".into()
            });
        }
        let expression = match calculation.operation {
            CalculatedOperation::Add
            | CalculatedOperation::Subtract
            | CalculatedOperation::Multiply
            | CalculatedOperation::Divide => {
                if source_column.dtype() == &DataType::Boolean {
                    return Err(format!(
                        "La columna fuente calculada '{}' debe ser numérica.",
                        calculation.source
                    ));
                }
                let left = col(source_name).strict_cast(DataType::Float64);
                let operand = calculation.operand.as_ref().unwrap();
                let right = match operand.kind {
                    CalculatedOperandKind::Literal => {
                        lit(strict_f64(&operand.value, "El operando numérico")?)
                    }
                    CalculatedOperandKind::Column => {
                        let operand_name = remapped_name(&operand.value, &rename_map);
                        recipe_column(source, &operand.value)?;
                        col(operand_name).strict_cast(DataType::Float64)
                    }
                };
                match calculation.operation {
                    CalculatedOperation::Add => left + right,
                    CalculatedOperation::Subtract => left - right,
                    CalculatedOperation::Multiply => left * right,
                    CalculatedOperation::Divide => left / right,
                    _ => unreachable!(),
                }
            }
            CalculatedOperation::Concat => {
                let operand = calculation.operand.as_ref().unwrap();
                let right = match operand.kind {
                    CalculatedOperandKind::Literal => lit(operand.value.clone()),
                    CalculatedOperandKind::Column => {
                        let operand_name = remapped_name(&operand.value, &rename_map);
                        recipe_column(source, &operand.value)?;
                        col(operand_name).cast(DataType::String)
                    }
                };
                concat_str(
                    vec![col(source_name).cast(DataType::String), right],
                    "",
                    false,
                )
            }
            CalculatedOperation::Year => col(source_name).dt().year(),
            CalculatedOperation::Month => col(source_name).dt().month(),
            CalculatedOperation::Day => col(source_name).dt().day(),
        };
        if recipe_column(source, &calculation.name).is_ok() {
            return Err(format!(
                "La columna calculada '{}' ya existe.",
                calculation.name
            ));
        }
        plan = plan.with_columns(vec![expression.alias(calculation.name.clone())]);
        1
    } else {
        0
    };

    let (split_column_count, split_dropped_source_count) = if let Some(split) = &recipe.split_column
    {
        if split.delimiter.is_empty() {
            return Err("El delimitador de división no puede estar vacío.".into());
        }
        if !(2..=16).contains(&split.names.len()) {
            return Err("La división requiere entre 2 y 16 columnas de destino.".into());
        }
        let source_name = remapped_name(&split.source, &rename_map).to_owned();
        let mut output_names = if recipe.keep_columns.is_some() {
            keep_names.clone()
        } else {
            final_names.clone()
        };
        if let Some(calculation) = &recipe.calculated_column {
            output_names.push(calculation.name.clone());
        }
        if !output_names.iter().any(|name| name == &source_name) {
            return Err(format!(
                "La columna '{source_name}' requerida por split fue descartada por keepColumns."
            ));
        }
        let source_column = recipe_column(source, &split.source)?;
        let cast_target = recipe
            .casts
            .iter()
            .find(|cast| remapped_name(&cast.column, &rename_map) == source_name)
            .map(|cast| cast.target);
        let is_text = cast_target
            .map(|target| target == RecipeCastTarget::String)
            .unwrap_or(source_column.dtype() == &DataType::String);
        if !is_text {
            return Err(format!(
                "La columna '{source_name}' debe ser de texto para dividirse."
            ));
        }
        let mut unique = HashSet::new();
        for name in &split.names {
            let trimmed = name.trim();
            if trimmed.is_empty() || trimmed != name {
                return Err(
                    "Los nombres divididos no pueden estar vacíos ni tener espacios exteriores."
                        .into(),
                );
            }
            if !unique.insert(trimmed) {
                return Err(format!("El nombre dividido '{trimmed}' está duplicado."));
            }
            if output_names.iter().any(|existing| existing == trimmed) {
                return Err(format!("La columna dividida '{trimmed}' ya existe."));
            }
        }
        let split_expression = col(source_name.as_str())
            .str()
            .splitn(lit(split.delimiter.clone()), split.names.len());
        let split_expressions = split
            .names
            .iter()
            .enumerate()
            .map(|(index, name)| {
                split_expression
                    .clone()
                    .struct_()
                    .field_by_name(&format!("field_{index}"))
                    .alias(name.clone())
            })
            .collect::<Vec<_>>();
        plan = plan.with_columns(split_expressions);
        output_names.extend(split.names.iter().cloned());
        let split_dropped_source_count = if split.drop_source {
            plan = plan.select(
                output_names
                    .iter()
                    .filter(|name| name.as_str() != source_name)
                    .map(col)
                    .collect::<Vec<_>>(),
            );
            1
        } else {
            0
        };
        (split.names.len(), split_dropped_source_count)
    } else {
        (0, 0)
    };

    let (merged_column_count, dropped_source_column_count) = if let Some(merge) =
        &recipe.merge_columns
    {
        if !(2..=16).contains(&merge.sources.len()) {
            return Err("La unión requiere entre 2 y 16 columnas fuente.".into());
        }
        if merge.name.trim().is_empty() || merge.name != merge.name.trim() {
            return Err(
                "El nombre de la columna unida no puede estar vacío ni tener espacios exteriores."
                    .into(),
            );
        }
        let mut output_names = if recipe.keep_columns.is_some() {
            keep_names.clone()
        } else {
            final_names.clone()
        };
        if let Some(calculation) = &recipe.calculated_column {
            output_names.push(calculation.name.clone());
        }
        if let Some(split) = &recipe.split_column {
            let split_source = remapped_name(&split.source, &rename_map);
            if split.drop_source && merge.sources.contains(&split.source) {
                return Err(format!(
                    "La unión necesita '{split_source}', pero la división la descartaría."
                ));
            }
            if split.drop_source {
                output_names.retain(|name| name != split_source);
            }
            output_names.extend(split.names.iter().cloned());
        }
        if output_names.iter().any(|name| name == &merge.name) {
            return Err(format!("La columna unida '{}' ya existe.", merge.name));
        }
        let mut unique = HashSet::new();
        let sources = merge
                .sources
                .iter()
                .map(|source_name| {
                    if !unique.insert(source_name) {
                        return Err(format!(
                            "La columna fuente '{source_name}' está duplicada."
                        ));
                    }
                    let effective_name = remapped_name(source_name, &rename_map).to_owned();
                    if !output_names.iter().any(|name| name == &effective_name) {
                        return Err(format!(
                            "La columna '{effective_name}' requerida por merge fue descartada por keepColumns."
                        ));
                    }
                    let source_column = recipe_column(source, source_name)?;
                    let cast_target = recipe
                        .casts
                        .iter()
                        .find(|cast| {
                            remapped_name(&cast.column, &rename_map) == effective_name
                        })
                        .map(|cast| cast.target);
                    let is_text = cast_target
                        .map(|target| target == RecipeCastTarget::String)
                        .unwrap_or(source_column.dtype() == &DataType::String);
                    if !is_text {
                        return Err(format!(
                            "La columna '{effective_name}' debe ser de texto para unirse."
                        ));
                    }
                    Ok(effective_name)
                })
                .collect::<Result<Vec<_>, String>>()?;
        let source_expressions = sources.iter().map(col).collect::<Vec<_>>();
        let expression = when(coalesce(&source_expressions).is_not_null())
            .then(concat_str(source_expressions, &merge.separator, true))
            .otherwise(lit(NULL))
            .alias(merge.name.clone());
        plan = plan.with_columns(vec![expression]);
        output_names.push(merge.name.clone());
        let dropped_source_column_count = if merge.drop_sources {
            let dropped = sources.iter().collect::<HashSet<_>>();
            plan = plan.select(
                output_names
                    .iter()
                    .filter(|name| !dropped.contains(name))
                    .map(col)
                    .collect::<Vec<_>>(),
            );
            sources.len()
        } else {
            0
        };
        (1, dropped_source_column_count)
    } else {
        (0, 0)
    };

    let (adjusted_outlier_cell_count, outlier_removed_row_count, outlier_column_count) = if recipe
        .outlier_treatments
        .is_empty()
    {
        (0, 0, 0)
    } else {
        let filtered_outlier_values = if recipe.filters.is_empty() {
            None
        } else {
            let outlier_columns = recipe
                .outlier_treatments
                .iter()
                .map(|treatment| remapped_name(&treatment.column, &rename_map).to_owned())
                .collect::<Vec<_>>();
            Some(collect_lazy_frame_streaming(
                plan.clone()
                    .select(outlier_columns.iter().map(col).collect::<Vec<_>>()),
                "No se pudieron preparar los valores de atípicos después de los filtros",
            )?)
        };
        let outlier_source = filtered_outlier_values.as_ref().unwrap_or(source);
        let prepared =
            prepare_outlier_treatments(outlier_source, &recipe.outlier_treatments, &rename_map)?;
        let mut drop_mask = vec![false; outlier_source.height()];
        let mut drop_expression: Option<Expr> = None;
        let mut replacement_expressions = Vec::new();
        let mut adjusted = 0;

        for (name, action, values, lower, upper, median, dtype) in prepared {
            let outlier_rows = values
                .iter()
                .enumerate()
                .filter_map(|(row, value)| {
                    value.and_then(|value| (value < lower || value > upper).then_some(row))
                })
                .collect::<Vec<_>>();
            let value = col(name.as_str());
            let outlier = value.clone().is_not_null().and(
                value
                    .clone()
                    .lt(lit(lower))
                    .or(value.clone().gt(lit(upper))),
            );
            match action {
                OutlierAction::Cap => {
                    adjusted += outlier_rows.len();
                    if !outlier_rows.is_empty() {
                        replacement_expressions.push(
                            when(value.clone().lt(lit(lower)))
                                .then(lit(lower))
                                .when(value.clone().gt(lit(upper)))
                                .then(lit(upper))
                                .otherwise(value)
                                .alias(name),
                        );
                    }
                }
                OutlierAction::Drop => {
                    for row in outlier_rows {
                        drop_mask[row] = true;
                    }
                    drop_expression = Some(match drop_expression {
                        Some(existing) => existing.or(outlier),
                        None => outlier,
                    });
                }
                OutlierAction::Impute => {
                    adjusted += outlier_rows.len();
                    replacement_expressions.push(
                        when(outlier)
                            .then(lit(median))
                            .otherwise(value)
                            .cast(dtype)
                            .alias(name),
                    );
                }
            }
        }
        if !replacement_expressions.is_empty() {
            plan = plan.with_columns(replacement_expressions);
        }
        if let Some(drop_expression) = drop_expression {
            plan = plan.filter(drop_expression.not());
        }
        (
            adjusted,
            drop_mask.iter().filter(|drop| **drop).count(),
            recipe.outlier_treatments.len(),
        )
    };

    let (normalized_contact_cell_count, normalized_contact_column_count) = if recipe
        .contact_normalizations
        .is_empty()
    {
        (0, 0)
    } else {
        let schema = plan.collect_schema().map_err(|error| {
            format!("No se pudo validar el esquema de normalización de contactos: {error}")
        })?;
        let targets = lazy_contact_targets(
            source,
            &recipe.contact_normalizations,
            &rename_map,
            &recipe.casts,
        )?;
        for (name, _) in &targets {
            if schema.get(name).is_none() {
                return Err(format!(
                    "La columna '{name}' para contactos no sobrevivió las etapas estructurales."
                ));
            }
        }
        let count_aliases = targets
            .iter()
            .enumerate()
            .map(|(index, _)| format!("__columnia_contact_changed_{index}"))
            .collect::<Vec<_>>();
        let count_expressions = targets
            .iter()
            .zip(&count_aliases)
            .map(|((name, kind), alias)| {
                lazy_contact_expression(name, *kind)
                    .neq_missing(col(name))
                    .cast(DataType::UInt64)
                    .sum()
                    .alias(alias)
            })
            .collect::<Vec<_>>();
        let count_frame = collect_lazy_frame_streaming(
            plan.clone().select(count_expressions),
            "No se pudo contar la normalización de contactos",
        )?;
        let changed_cells = count_aliases
            .iter()
            .map(|alias| {
                let value = count_frame
                    .column(alias)
                    .map_err(|error| format!("No se pudo leer el conteo de contactos: {error}"))?
                    .get(0)
                    .map_err(|error| format!("No se pudo leer el conteo de contactos: {error}"))?;
                match value {
                    AnyValue::UInt64(value) => usize::try_from(value).map_err(|_| {
                        "El conteo de normalizaciones excede el límite de memoria.".to_owned()
                    }),
                    AnyValue::Int64(value) if value >= 0 => {
                        usize::try_from(value as u64).map_err(|_| {
                            "El conteo de normalizaciones excede el límite de memoria.".to_owned()
                        })
                    }
                    AnyValue::Null => Ok(0),
                    _ => Err("El conteo de contactos devolvió un tipo inválido.".to_owned()),
                }
            })
            .collect::<Result<Vec<_>, String>>()?
            .into_iter()
            .sum();
        let expressions = targets
            .iter()
            .map(|(name, kind)| lazy_contact_expression(name, *kind).alias(name))
            .collect::<Vec<_>>();
        plan = plan.with_columns(expressions);
        (changed_cells, targets.len())
    };

    let extracted_column_count = if recipe.text_extractions.is_empty() {
        0
    } else {
        let schema = plan.collect_schema().map_err(|error| {
            format!("No se pudo validar el esquema de extracción de texto: {error}")
        })?;
        let targets = lazy_text_extraction_targets(
            source,
            &recipe.text_extractions,
            &rename_map,
            &recipe.casts,
        )?;
        for ((source_name, _, _), extraction) in targets.iter().zip(&recipe.text_extractions) {
            if schema.get(source_name).is_none() {
                return Err(format!(
                    "La columna '{source_name}' para extracción no sobrevivió las etapas estructurales."
                ));
            }
            if schema.get(&extraction.name).is_some() {
                return Err(format!(
                    "La columna extraída '{}' ya existe.",
                    extraction.name
                ));
            }
        }
        let expressions = targets
            .iter()
            .zip(&recipe.text_extractions)
            .map(|((source_name, kind, delimiter), extraction)| {
                lazy_text_extraction_expression(source_name, *kind, delimiter.as_deref())
                    .map(|expression| expression.alias(&extraction.name))
            })
            .collect::<Result<Vec<_>, String>>()?;
        plan = plan.with_columns(expressions);
        targets.len()
    };

    let (group_summary_input_rows, summary_aggregations) = if let Some(summary) =
        &recipe.group_summary
    {
        let mut derived_names = recipe
            .text_extractions
            .iter()
            .map(|extraction| extraction.name.as_str())
            .collect::<HashSet<_>>();
        if let Some(calculation) = &recipe.calculated_column {
            derived_names.insert(calculation.name.as_str());
        }
        if let Some(split) = &recipe.split_column {
            derived_names.extend(split.names.iter().map(String::as_str));
        }
        if let Some(merge) = &recipe.merge_columns {
            derived_names.insert(merge.name.as_str());
        }
        for name in summary.group_by.iter().chain(
            summary
                .aggregations
                .iter()
                .map(|aggregation| &aggregation.column),
        ) {
            if !derived_names.contains(name.as_str()) {
                recipe_column(source, name)?;
            }
        }
        let schema = plan
            .collect_schema()
            .map_err(|error| format!("No se pudo validar el esquema del resumen: {error}"))?;
        let summary_names = summary
            .group_by
            .iter()
            .chain(
                summary
                    .aggregations
                    .iter()
                    .map(|aggregation| &aggregation.column),
            )
            .map(|name| remapped_name(name, &rename_map).to_owned())
            .collect::<HashSet<_>>();
        for name in &summary_names {
            if schema.get(name).is_none() {
                return Err(format!(
                    "La columna '{name}' requerida por agrupar/resumir no sobrevivió las etapas anteriores."
                ));
            }
        }
        let validation = if recipe.filters.is_empty()
            && recipe.contact_normalizations.is_empty()
            && recipe.text_extractions.is_empty()
            && recipe.calculated_column.is_none()
            && recipe.split_column.is_none()
            && recipe.merge_columns.is_none()
        {
            None
        } else {
            Some(collect_lazy_frame_streaming(
                plan.clone()
                    .select(summary_names.iter().map(col).collect::<Vec<_>>()),
                "No se pudo validar el resumen después de las etapas previas",
            )?)
        };
        let (groups, aggregations) = validate_lazy_group_summary(
            source,
            summary,
            &rename_map,
            &recipe.casts,
            validation.as_ref(),
        )?;
        let group_expressions = groups.iter().map(col).collect::<Vec<_>>();
        let aggregate_expressions = aggregations
            .iter()
            .map(|(name, output, operation)| {
                let expression = match operation {
                    SummaryOperation::Sum => col(name).sum(),
                    SummaryOperation::Mean => col(name).mean(),
                    SummaryOperation::Min => col(name).min(),
                    SummaryOperation::Max => col(name).max(),
                    SummaryOperation::Count => len().cast(DataType::Int64),
                    SummaryOperation::CountUnique => {
                        col(name).drop_nulls().n_unique().cast(DataType::Int64)
                    }
                };
                expression.alias(output)
            })
            .collect::<Vec<_>>();
        plan = plan
            .group_by_stable(group_expressions)
            .agg(aggregate_expressions);
        (
            Some(
                validation
                    .as_ref()
                    .map_or(source.height(), DataFrame::height),
            ),
            Some(aggregations),
        )
    } else {
        (None, None)
    };

    let candidate = collect_lazy_frame_streaming(plan, "No se pudo ejecutar la receta lazy")?;
    if let Some(aggregations) = &summary_aggregations {
        for (name, output, operation) in aggregations {
            if !matches!(
                operation,
                SummaryOperation::Sum
                    | SummaryOperation::Mean
                    | SummaryOperation::Min
                    | SummaryOperation::Max
            ) {
                continue;
            }
            let column = candidate
                .column(output)
                .map_err(|error| format!("No se pudo leer '{output}': {error}"))?;
            if column.dtype() == &DataType::Float64
                && (0..column.len()).any(|row| {
                    matches!(
                        column.get(row),
                        Ok(AnyValue::Float64(value)) if !value.is_finite()
                    )
                })
            {
                return Err(format!(
                    "La agregación de '{name}' produjo un valor no finito."
                ));
            }
        }
    }
    let removed_row_count = group_summary_input_rows
        .map(|input_rows| source.height().saturating_sub(input_rows))
        .unwrap_or_else(|| source.height().saturating_sub(candidate.height()));
    let group_count = summary_aggregations
        .as_ref()
        .map_or(0, |_| candidate.height());
    let collapsed_row_count =
        group_summary_input_rows.map_or(0, |input_rows| input_rows.saturating_sub(group_count));
    Ok((
        candidate,
        renamed_count,
        cast_count,
        parsed_date_column_count,
        removed_row_count,
        calculated_column_count,
        replaced_cell_count,
        dropped_column_count,
        kept_order_changed,
        split_column_count,
        merged_column_count,
        split_dropped_source_count + dropped_source_column_count,
        adjusted_outlier_cell_count,
        outlier_removed_row_count,
        outlier_column_count,
        group_count,
        summary_aggregations.as_ref().map_or(0, Vec::len),
        collapsed_row_count,
        normalized_contact_cell_count,
        normalized_contact_column_count,
        extracted_column_count,
    ))
}

fn apply_recipe_to_frame(
    source: &DataFrame,
    recipe: &TransformRecipe,
) -> Result<RecipeFrameOutcome, String> {
    if lazy_recipe_supported(source, recipe) {
        return apply_lazy_recipe_to_frame(source, recipe);
    }
    apply_eager_recipe_to_frame(source, recipe)
}

fn source_backed_projection_recipe_supported(schema: &DataFrame, recipe: &TransformRecipe) -> bool {
    (!recipe.renames.is_empty()
        || recipe.keep_columns.is_some()
        || !recipe.filters.is_empty()
        || !recipe.casts.is_empty()
        || !recipe.date_parses.is_empty()
        || recipe.calculated_column.is_some()
        || recipe.find_replace.is_some()
        || recipe.split_column.is_some()
        || recipe.merge_columns.is_some()
        || !recipe.contact_normalizations.is_empty()
        || !recipe.text_extractions.is_empty()
        || recipe.group_summary.is_some()
        || !recipe.outlier_treatments.is_empty())
        && recipe.date_parses.iter().all(|parse| {
            matches!(
                parse.format,
                RecipeDateFormat::Ymd
                    | RecipeDateFormat::Dmy
                    | RecipeDateFormat::Mdy
                    | RecipeDateFormat::Iso8601
            )
        })
        && recipe
            .calculated_column
            .as_ref()
            .is_none_or(|calculation| match calculation.operation {
                CalculatedOperation::Add
                | CalculatedOperation::Subtract
                | CalculatedOperation::Multiply
                | CalculatedOperation::Concat => true,
                CalculatedOperation::Year
                | CalculatedOperation::Month
                | CalculatedOperation::Day => {
                    recipe
                        .casts
                        .iter()
                        .all(|cast| cast.column != calculation.source)
                        && (recipe_column(schema, &calculation.source).is_ok_and(|column| {
                            matches!(column.dtype(), DataType::Date | DataType::Datetime(_, None))
                        }) || recipe.date_parses.iter().any(|parse| {
                            parse.column == calculation.source
                                && matches!(
                                    parse.target,
                                    RecipeDateTarget::Date | RecipeDateTarget::Datetime
                                )
                        }))
                }
                CalculatedOperation::Divide => calculation.operand.is_some(),
            })
        && recipe.find_replace.as_ref().is_none_or(|replacement| {
            !replacement.find.contains('\0')
                && !replacement.replace.contains('\0')
                && (!replacement.regex
                    || (Regex::new(&replacement.find).is_ok()
                        && source_backed_regex_replacement(&replacement.replace).is_ok()))
        })
        && recipe
            .merge_columns
            .as_ref()
            .is_none_or(|merge| !merge.name.contains('\0') && !merge.separator.contains('\0'))
        && recipe.split_column.as_ref().is_none_or(|split| {
            !split.delimiter.contains('\0') && split.names.iter().all(|name| !name.contains('\0'))
        })
        && recipe.text_extractions.iter().all(|extraction| {
            !extraction.name.contains('\0')
                && extraction.source.chars().all(|character| character != '\0')
                && extraction
                    .delimiter
                    .as_deref()
                    .is_none_or(|delimiter| !delimiter.contains('\0'))
        })
        && recipe
            .contact_normalizations
            .iter()
            .all(|normalization| !normalization.column.contains('\0'))
}

struct SourceBackedProjectionPlan {
    source_columns: Vec<String>,
    output_columns: Vec<String>,
    selected_columns: Vec<String>,
    renamed_column_count: usize,
    converted_column_count: usize,
    parsed_date_column_count: usize,
    calculated_column_count: usize,
    replacement_columns: Vec<String>,
    split_columns: Option<SourceBackedSplitPlan>,
    merge_columns: Option<SourceBackedMergePlan>,
    contact_normalizations: Vec<SourceBackedContactNormalizationPlan>,
    text_extractions: Vec<SourceBackedTextExtractionPlan>,
    outlier_treatments: Vec<SourceBackedOutlierPlan>,
    group_summary: Option<SourceBackedGroupSummaryPlan>,
    dropped_column_count: usize,
    kept_order_changed: bool,
}

struct SourceBackedSplitPlan {
    source: String,
    names: Vec<String>,
    delimiter: String,
    drop_source: bool,
}

struct SourceBackedMergePlan {
    sources: Vec<String>,
    name: String,
    separator: String,
    drop_sources: bool,
}

struct SourceBackedTextExtractionPlan {
    source: String,
    kind: ExtractionKind,
    name: String,
    delimiter: Option<String>,
}

struct SourceBackedContactNormalizationPlan {
    column: String,
    kind: ContactKind,
}

struct SourceBackedOutlierPlan {
    column: String,
    action: OutlierAction,
    dtype: DataType,
}

struct SourceBackedGroupSummaryPlan {
    group_by: Vec<String>,
    group_dtypes: Vec<DataType>,
    aggregations: Vec<SourceBackedSummaryAggregationPlan>,
}

struct SourceBackedSummaryAggregationPlan {
    column: String,
    output: String,
    operation: SummaryOperation,
    dtype: DataType,
}

fn source_backed_target_dtype(
    schema: &DataFrame,
    column: &str,
    recipe: &TransformRecipe,
    rename_map: &HashMap<String, String>,
) -> Result<DataType, String> {
    let source_column = recipe_column(schema, column)?;
    let effective = rename_map.get(column).map(String::as_str).unwrap_or(column);
    if let Some(cast) = recipe.casts.iter().find(|cast| {
        rename_map
            .get(&cast.column)
            .map(String::as_str)
            .unwrap_or(cast.column.as_str())
            == effective
    }) {
        return Ok(match cast.target {
            RecipeCastTarget::String => DataType::String,
            RecipeCastTarget::Integer => DataType::Int64,
            RecipeCastTarget::Decimal => DataType::Float64,
            RecipeCastTarget::Boolean => DataType::Boolean,
        });
    }
    if let Some(parse) = recipe.date_parses.iter().find(|parse| {
        rename_map
            .get(&parse.column)
            .map(String::as_str)
            .unwrap_or(parse.column.as_str())
            == effective
    }) {
        return Ok(match parse.target {
            RecipeDateTarget::Date => DataType::Date,
            RecipeDateTarget::Datetime => DataType::Datetime(TimeUnit::Milliseconds, None),
        });
    }
    Ok(source_column.dtype().clone())
}

fn source_backed_group_summary_plan(
    summary: &GroupSummaryRecipe,
    rename_map: &HashMap<String, String>,
    available_columns: &[String],
    available_types: &HashMap<String, DataType>,
) -> Result<SourceBackedGroupSummaryPlan, String> {
    if summary.group_by.is_empty() || summary.group_by.len() > 8 {
        return Err("Agrupar requiere entre 1 y 8 columnas clave.".into());
    }
    if summary.aggregations.is_empty() || summary.aggregations.len() > 32 {
        return Err("Resumir requiere entre 1 y 32 agregaciones.".into());
    }

    let effective_name = |name: &str| {
        rename_map
            .get(name)
            .cloned()
            .unwrap_or_else(|| name.to_owned())
    };
    let groups = summary
        .group_by
        .iter()
        .map(|name| effective_name(name))
        .collect::<Vec<_>>();
    let mut group_dtypes = Vec::with_capacity(groups.len());
    let mut group_unique = HashSet::new();
    for name in &groups {
        if !group_unique.insert(name.clone()) {
            return Err(format!("La clave de grupo '{name}' está duplicada."));
        }
        if !available_columns.iter().any(|column| column == name) {
            return Err(format!(
                "La columna '{name}' requerida por agrupar no sobrevivió las etapas anteriores."
            ));
        }
        if !available_types.contains_key(name) {
            return Err(format!(
                "No se pudo inferir el tipo de la clave de grupo '{name}'."
            ));
        }
        group_dtypes.push(
            available_types
                .get(name)
                .expect("la presencia del tipo fue validada")
                .clone(),
        );
    }

    let mut aggregation_unique = HashSet::new();
    let mut output_names = HashSet::new();
    let aggregations = summary
        .aggregations
        .iter()
        .map(|aggregation| {
            let name = effective_name(&aggregation.column);
            if !aggregation_unique.insert((name.clone(), aggregation.operation)) {
                return Err(format!(
                    "La agregación '{}_{}' está duplicada.",
                    name,
                    aggregation.operation.suffix()
                ));
            }
            if !available_columns.iter().any(|column| column == &name) {
                return Err(format!(
                    "La columna '{name}' requerida por resumir no sobrevivió las etapas anteriores."
                ));
            }
            let dtype = available_types.get(&name).ok_or_else(|| {
                format!("No se pudo inferir el tipo de la columna '{name}' para resumir.")
            })?;
            match aggregation.operation {
                SummaryOperation::Sum | SummaryOperation::Mean
                    if !matches!(dtype, DataType::Int64 | DataType::Float64) =>
                {
                    return Err(format!(
                        "La agregación {} requiere que '{name}' sea Int64 o Float64.",
                        aggregation.operation.suffix()
                    ));
                }
                SummaryOperation::Min | SummaryOperation::Max
                    if !matches!(
                        dtype,
                        DataType::Int64
                            | DataType::Float64
                            | DataType::String
                            | DataType::Date
                            | DataType::Datetime(_, _)
                    ) =>
                {
                    return Err(format!(
                        "La agregación {} no admite el tipo de '{name}'.",
                        aggregation.operation.suffix()
                    ));
                }
                _ => {}
            }
            let output = format!("{}_{}", name, aggregation.operation.suffix());
            if group_unique.contains(&output) || !output_names.insert(output.clone()) {
                return Err(format!(
                    "El nombre de salida '{output}' colisiona con otra columna."
                ));
            }
            Ok(SourceBackedSummaryAggregationPlan {
                column: name,
                output,
                operation: aggregation.operation,
                dtype: dtype.clone(),
            })
        })
        .collect::<Result<Vec<_>, String>>()?;

    Ok(SourceBackedGroupSummaryPlan {
        group_by: groups,
        group_dtypes,
        aggregations,
    })
}

fn source_backed_projection_plan(
    schema: &DataFrame,
    recipe: &TransformRecipe,
) -> Result<SourceBackedProjectionPlan, String> {
    if recipe.filters.len() > 3 {
        return Err("La receta admite como máximo tres filtros combinados con AND.".into());
    }
    if !lazy_renames_have_no_cycles(recipe) {
        return Err("Los renombrados contienen un ciclo.".to_owned());
    }

    let mut rename_map = HashMap::new();
    let mut rename_sources = HashSet::new();
    for rename in &recipe.renames {
        if rename.from.trim().is_empty() || rename.to.trim().is_empty() {
            return Err("Los nombres de columna no pueden estar vacíos.".to_owned());
        }
        if rename.to != rename.to.trim() {
            return Err(
                "El nuevo nombre de columna no puede tener espacios exteriores.".to_owned(),
            );
        }
        if !rename_sources.insert(rename.from.as_str()) {
            return Err(format!(
                "La columna '{}' aparece en más de un renombrado.",
                rename.from
            ));
        }
        recipe_column(schema, &rename.from)?;
        rename_map.insert(rename.from.clone(), rename.to.clone());
    }

    let source_columns = schema
        .get_column_names()
        .iter()
        .map(|name| name.to_string())
        .collect::<Vec<_>>();
    let output_columns = source_columns
        .iter()
        .map(|name| {
            rename_map
                .get(name)
                .cloned()
                .unwrap_or_else(|| name.clone())
        })
        .collect::<Vec<_>>();
    let mut unique_output_columns = HashSet::new();
    if output_columns
        .iter()
        .any(|name| !unique_output_columns.insert(name.as_str()))
    {
        return Err("Los renombrados producirían nombres de columna duplicados.".to_owned());
    }

    let renamed_column_count = source_columns
        .iter()
        .zip(&output_columns)
        .filter(|(before, after)| before != after)
        .count();
    let selected_columns = if let Some(keep_columns) = &recipe.keep_columns {
        if keep_columns.is_empty() {
            return Err("Debes conservar al menos una columna.".into());
        }
        let mut selected = Vec::with_capacity(keep_columns.len());
        let mut seen = HashSet::new();
        for name in keep_columns {
            let effective = rename_map
                .get(name)
                .cloned()
                .unwrap_or_else(|| name.clone());
            if !output_columns.iter().any(|column| column == &effective) {
                return Err(format!(
                    "La columna '{effective}' no existe en la selección source-backed."
                ));
            }
            if !seen.insert(effective.clone()) {
                return Err(format!(
                    "La columna '{name}' aparece más de una vez en la selección."
                ));
            }
            selected.push(effective);
        }
        selected
    } else {
        output_columns.clone()
    };

    let mut cast_columns = HashSet::new();
    let mut converted_column_count = 0;
    for cast in &recipe.casts {
        let effective = rename_map
            .get(&cast.column)
            .cloned()
            .unwrap_or_else(|| cast.column.clone());
        if !cast_columns.insert(effective) {
            return Err(format!(
                "La columna '{}' aparece en más de una conversión.",
                cast.column
            ));
        }
        let column = recipe_column(schema, &cast.column)?;
        let already_target = matches!(
            (column.dtype(), cast.target),
            (DataType::String, RecipeCastTarget::String)
                | (DataType::Int64, RecipeCastTarget::Integer)
                | (DataType::Float64, RecipeCastTarget::Decimal)
                | (DataType::Boolean, RecipeCastTarget::Boolean)
        );
        converted_column_count += usize::from(!already_target);
    }

    let mut date_columns = HashSet::new();
    let mut parsed_date_column_count = 0;
    for parse in &recipe.date_parses {
        let effective = rename_map
            .get(&parse.column)
            .cloned()
            .unwrap_or_else(|| parse.column.clone());
        if cast_columns.contains(&effective) {
            return Err(format!(
                "La columna '{}' no puede convertirse y parsearse como fecha en la misma receta.",
                parse.column
            ));
        }
        if !date_columns.insert(effective) {
            return Err(format!(
                "La columna '{}' aparece en más de un parseo de fecha.",
                parse.column
            ));
        }
        let column = recipe_column(schema, &parse.column)?;
        let already_target = matches!(
            (column.dtype(), parse.target),
            (DataType::Date, RecipeDateTarget::Date)
                | (DataType::Datetime(_, _), RecipeDateTarget::Datetime)
        );
        if !already_target {
            if column.dtype() != &DataType::String {
                return Err(format!(
                    "La columna '{}' debe ser de texto para parsearse como fecha.",
                    parse.column
                ));
            }
            parsed_date_column_count += 1;
        }
    }

    let calculated_column_count = if let Some(calculation) = &recipe.calculated_column {
        if calculation.name.trim().is_empty() || calculation.name != calculation.name.trim() {
            return Err(
                "El nombre calculado no puede estar vacío ni tener espacios exteriores.".into(),
            );
        }
        if output_columns.iter().any(|name| name == &calculation.name) {
            return Err(format!(
                "La columna calculada '{}' ya existe.",
                calculation.name
            ));
        }
        let source_column = recipe_column(schema, &calculation.source)?;
        let unary = matches!(
            calculation.operation,
            CalculatedOperation::Year | CalculatedOperation::Month | CalculatedOperation::Day
        );
        if unary {
            if calculation.operand.is_some() {
                return Err("year, month y day no aceptan operando.".to_owned());
            }
            let source_name = rename_map
                .get(&calculation.source)
                .cloned()
                .unwrap_or_else(|| calculation.source.clone());
            let source_is_date = matches!(
                source_column.dtype(),
                DataType::Date | DataType::Datetime(_, None)
            ) || date_columns.contains(&source_name);
            if !source_is_date {
                return Err(format!(
                    "La columna '{}' debe ser date o datetime para extraer componentes.",
                    calculation.source
                ));
            }
            if cast_columns.contains(&source_name) {
                return Err(format!(
                    "La columna '{}' no puede convertirse y usarse como fecha en la misma receta.",
                    calculation.source
                ));
            }
        } else if calculation.operand.is_none() {
            return Err("La operación calculada requiere un operando.".to_owned());
        }
        if matches!(
            calculation.operation,
            CalculatedOperation::Add
                | CalculatedOperation::Subtract
                | CalculatedOperation::Multiply
                | CalculatedOperation::Divide
        ) && source_column.dtype() == &DataType::Boolean
        {
            return Err(format!(
                "La columna fuente calculada '{}' debe ser numérica.",
                calculation.source
            ));
        }
        let source_name = rename_map
            .get(&calculation.source)
            .cloned()
            .unwrap_or_else(|| calculation.source.clone());
        if recipe.keep_columns.is_some()
            && !selected_columns.iter().any(|name| name == &source_name)
        {
            return Err(format!(
                "La columna fuente calculada '{source_name}' fue descartada por keepColumns."
            ));
        }
        if let Some(operand) = &calculation.operand {
            match operand.kind {
                CalculatedOperandKind::Literal
                    if matches!(
                        calculation.operation,
                        CalculatedOperation::Add
                            | CalculatedOperation::Subtract
                            | CalculatedOperation::Multiply
                            | CalculatedOperation::Divide
                    ) =>
                {
                    strict_f64(&operand.value, "El operando numérico")?;
                }
                CalculatedOperandKind::Column => {
                    let operand_name = rename_map
                        .get(&operand.value)
                        .cloned()
                        .unwrap_or_else(|| operand.value.clone());
                    recipe_column(schema, &operand.value)?;
                    if recipe.keep_columns.is_some()
                        && !selected_columns.iter().any(|name| name == &operand_name)
                    {
                        return Err(format!(
                            "La columna operando calculada '{operand_name}' fue descartada por keepColumns."
                        ));
                    }
                }
                _ => {}
            }
        } else if !unary {
            return Err("La operación calculada requiere un operando.".to_owned());
        }
        1
    } else {
        0
    };

    let text_after_cast = |source_name: &str, source_column: &Column| {
        recipe
            .casts
            .iter()
            .find(|cast| {
                rename_map
                    .get(&cast.column)
                    .map(String::as_str)
                    .unwrap_or(cast.column.as_str())
                    == source_name
            })
            .map(|cast| cast.target == RecipeCastTarget::String)
            .unwrap_or(source_column.dtype() == &DataType::String)
    };

    let replacement_columns = if let Some(replacement) = &recipe.find_replace {
        if replacement.find.is_empty() {
            return Err("El texto buscado no puede estar vacío.".to_owned());
        }
        match replacement.scope {
            FindReplaceScope::Column => {
                let column = replacement
                    .column
                    .as_deref()
                    .ok_or_else(|| "La búsqueda por columna requiere una columna.".to_owned())?;
                let source_column = recipe_column(schema, column)?;
                let effective = rename_map
                    .get(column)
                    .cloned()
                    .unwrap_or_else(|| column.to_owned());
                if !text_after_cast(&effective, source_column) {
                    return Err(format!(
                        "La columna '{effective}' debe ser de texto para buscar y reemplazar."
                    ));
                }
                vec![effective]
            }
            FindReplaceScope::AllTextColumns => {
                if replacement.column.is_some() {
                    return Err(
                        "La búsqueda en todas las columnas no acepta una columna concreta."
                            .to_owned(),
                    );
                }
                source_columns
                    .iter()
                    .zip(schema.columns())
                    .filter(|(name, column)| {
                        let effective = rename_map
                            .get(*name)
                            .map(String::as_str)
                            .unwrap_or(name.as_str());
                        text_after_cast(effective, column)
                    })
                    .map(|(name, _)| {
                        rename_map
                            .get(name)
                            .cloned()
                            .unwrap_or_else(|| name.clone())
                    })
                    .collect()
            }
        }
    } else {
        Vec::new()
    };

    let split_columns = if let Some(split) = &recipe.split_column {
        if split.delimiter.is_empty() {
            return Err("El delimitador de división no puede estar vacío.".into());
        }
        if !(2..=16).contains(&split.names.len()) {
            return Err("La división requiere entre 2 y 16 columnas de destino.".into());
        }
        let source_column = recipe_column(schema, &split.source)?;
        let source = rename_map
            .get(&split.source)
            .cloned()
            .unwrap_or_else(|| split.source.clone());
        if recipe.keep_columns.is_some() && !selected_columns.iter().any(|name| name == &source) {
            return Err(format!(
                "La columna '{source}' requerida por split fue descartada por keepColumns."
            ));
        }
        if !text_after_cast(&source, source_column) {
            return Err(format!(
                "La columna '{source}' debe ser de texto para dividirse."
            ));
        }
        let mut unique_names = HashSet::new();
        for name in &split.names {
            let trimmed = name.trim();
            if trimmed.is_empty() || trimmed != name {
                return Err(
                    "Los nombres divididos no pueden estar vacíos ni tener espacios exteriores."
                        .into(),
                );
            }
            if !unique_names.insert(trimmed) {
                return Err(format!("El nombre dividido '{trimmed}' está duplicado."));
            }
            if output_columns.iter().any(|existing| existing == trimmed)
                || recipe
                    .calculated_column
                    .as_ref()
                    .is_some_and(|calculation| calculation.name == trimmed)
                || recipe
                    .merge_columns
                    .as_ref()
                    .is_some_and(|merge| merge.name == trimmed)
            {
                return Err(format!("La columna dividida '{trimmed}' ya existe."));
            }
        }
        if split.drop_source
            && recipe
                .merge_columns
                .as_ref()
                .is_some_and(|merge| merge.sources.iter().any(|name| name == &split.source))
        {
            return Err(format!(
                "La unión necesita '{source}', pero la división la descartaría."
            ));
        }
        Some(SourceBackedSplitPlan {
            source,
            names: split.names.clone(),
            delimiter: split.delimiter.clone(),
            drop_source: split.drop_source,
        })
    } else {
        None
    };

    let merge_columns = if let Some(merge) = &recipe.merge_columns {
        if !(2..=16).contains(&merge.sources.len()) {
            return Err("La unión requiere entre 2 y 16 columnas fuente.".into());
        }
        if merge.name.trim().is_empty() || merge.name != merge.name.trim() {
            return Err(
                "El nombre de la columna unida no puede estar vacío ni tener espacios exteriores."
                    .into(),
            );
        }
        if output_columns.iter().any(|name| name == &merge.name)
            || split_columns
                .as_ref()
                .is_some_and(|split| split.names.iter().any(|name| name == &merge.name))
        {
            return Err(format!("La columna unida '{}' ya existe.", merge.name));
        }
        if recipe
            .calculated_column
            .as_ref()
            .is_some_and(|calculation| calculation.name == merge.name)
        {
            return Err(format!("La columna unida '{}' ya existe.", merge.name));
        }
        let mut unique_sources = HashSet::new();
        let sources = merge
            .sources
            .iter()
            .map(|source_name| {
                if !unique_sources.insert(source_name) {
                    return Err(format!(
                        "La columna fuente '{source_name}' está duplicada."
                    ));
                }
                let source_column = recipe_column(schema, source_name)?;
                let effective_name = rename_map
                    .get(source_name)
                    .cloned()
                    .unwrap_or_else(|| source_name.clone());
                if recipe.keep_columns.is_some()
                    && !selected_columns.iter().any(|name| name == &effective_name)
                {
                    return Err(format!(
                        "La columna '{effective_name}' requerida por merge fue descartada por keepColumns."
                    ));
                }
                if !text_after_cast(&effective_name, source_column) {
                    return Err(format!(
                        "La columna '{effective_name}' debe ser de texto para unirse."
                    ));
                }
                Ok(effective_name)
            })
            .collect::<Result<Vec<_>, String>>()?;
        Some(SourceBackedMergePlan {
            sources,
            name: merge.name.clone(),
            separator: merge.separator.clone(),
            drop_sources: merge.drop_sources,
        })
    } else {
        None
    };

    let contact_normalizations = if recipe.contact_normalizations.is_empty() {
        Vec::new()
    } else {
        let mut unique_columns = HashSet::new();
        recipe
            .contact_normalizations
            .iter()
            .map(|normalization| {
                if !unique_columns.insert(normalization.column.as_str()) {
                    return Err(format!(
                        "La columna '{}' tiene más de una normalización de contacto.",
                        normalization.column
                    ));
                }
                let source_column = recipe_column(schema, &normalization.column)?;
                let column = rename_map
                    .get(&normalization.column)
                    .cloned()
                    .unwrap_or_else(|| normalization.column.clone());
                if recipe.keep_columns.is_some()
                    && !selected_columns.iter().any(|name| name == &column)
                {
                    return Err(format!(
                        "La columna '{column}' requerida por contactos fue descartada por keepColumns."
                    ));
                }
                if split_columns
                    .as_ref()
                    .is_some_and(|split| split.drop_source && split.source == column)
                {
                    return Err(format!(
                        "La normalización necesita '{column}', pero la división la descartaría."
                    ));
                }
                if merge_columns.as_ref().is_some_and(|merge| {
                    merge.drop_sources && merge.sources.iter().any(|source| source == &column)
                }) {
                    return Err(format!(
                        "La normalización necesita '{column}', pero la unión la descartaría."
                    ));
                }
                if !text_after_cast(&column, source_column) {
                    return Err(format!(
                        "La columna '{column}' debe ser de texto para normalizar contactos."
                    ));
                }
                Ok(SourceBackedContactNormalizationPlan {
                    column,
                    kind: normalization.kind,
                })
            })
            .collect::<Result<Vec<_>, String>>()?
    };

    let text_extractions = if recipe.text_extractions.is_empty() {
        Vec::new()
    } else {
        let mut unique_names = HashSet::new();
        recipe
            .text_extractions
            .iter()
            .map(|extraction| {
                if extraction.name.trim().is_empty() || extraction.name != extraction.name.trim() {
                    return Err(
                        "El nombre extraído no puede estar vacío ni tener espacios exteriores."
                            .to_owned(),
                    );
                }
                if !unique_names.insert(extraction.name.as_str()) {
                    return Err(format!(
                        "La columna extraída '{}' está duplicada.",
                        extraction.name
                    ));
                }
                if output_columns.iter().any(|name| name == &extraction.name)
                    || calculated_column_count > 0
                        && recipe
                            .calculated_column
                            .as_ref()
                            .is_some_and(|calculation| calculation.name == extraction.name)
                    || split_columns.as_ref().is_some_and(|split| {
                        split.names.iter().any(|name| name == &extraction.name)
                    })
                    || merge_columns
                        .as_ref()
                        .is_some_and(|merge| merge.name == extraction.name)
                {
                    return Err(format!(
                        "La columna extraída '{}' ya existe.",
                        extraction.name
                    ));
                }
                let delimiter_based = matches!(
                    extraction.kind,
                    ExtractionKind::Before | ExtractionKind::After
                );
                if delimiter_based != extraction.delimiter.is_some() {
                    return Err(format!(
                        "La extracción '{}' {} delimitador.",
                        extraction.name,
                        if delimiter_based { "requiere" } else { "no acepta" }
                    ));
                }
                if extraction.delimiter.as_deref().is_some_and(str::is_empty) {
                    return Err("El delimitador de extracción no puede estar vacío.".to_owned());
                }
                let source_column = recipe_column(schema, &extraction.source)?;
                let source = rename_map
                    .get(&extraction.source)
                    .cloned()
                    .unwrap_or_else(|| extraction.source.clone());
                if recipe.keep_columns.is_some()
                    && !selected_columns.iter().any(|name| name == &source)
                {
                    return Err(format!(
                        "La columna '{source}' requerida por extracción fue descartada por keepColumns."
                    ));
                }
                if split_columns
                    .as_ref()
                    .is_some_and(|split| split.drop_source && split.source == source)
                {
                    return Err(format!(
                        "La extracción necesita '{source}', pero la división la descartaría."
                    ));
                }
                if merge_columns.as_ref().is_some_and(|merge| {
                    merge.drop_sources && merge.sources.iter().any(|name| name == &source)
                }) {
                    return Err(format!(
                        "La extracción necesita '{source}', pero la unión la descartaría."
                    ));
                }
                if !text_after_cast(&source, source_column) {
                    return Err(format!(
                        "La columna '{source}' debe ser de texto para extraerse."
                    ));
                }
                Ok(SourceBackedTextExtractionPlan {
                    source,
                    kind: extraction.kind,
                    name: extraction.name.clone(),
                    delimiter: extraction.delimiter.clone(),
                })
            })
            .collect::<Result<Vec<_>, String>>()?
    };

    let mut available_types = source_columns
        .iter()
        .zip(&output_columns)
        .map(|(source_name, output_name)| {
            (
                output_name.clone(),
                source_backed_target_dtype(schema, source_name, recipe, &rename_map)
                    .expect("las columnas fuente ya fueron validadas"),
            )
        })
        .collect::<HashMap<_, _>>();
    if let Some(calculation) = &recipe.calculated_column {
        let dtype = match calculation.operation {
            CalculatedOperation::Concat => DataType::String,
            CalculatedOperation::Year | CalculatedOperation::Month | CalculatedOperation::Day => {
                DataType::Int32
            }
            CalculatedOperation::Add
            | CalculatedOperation::Subtract
            | CalculatedOperation::Multiply
            | CalculatedOperation::Divide => DataType::Float64,
        };
        available_types.insert(calculation.name.clone(), dtype);
    }
    if let Some(split) = &split_columns {
        available_types.extend(
            split
                .names
                .iter()
                .cloned()
                .map(|name| (name, DataType::String)),
        );
    }
    if let Some(merge) = &merge_columns {
        available_types.insert(merge.name.clone(), DataType::String);
    }
    for normalization in &contact_normalizations {
        available_types.insert(normalization.column.clone(), DataType::String);
    }
    available_types.extend(
        text_extractions
            .iter()
            .map(|extraction| (extraction.name.clone(), DataType::String)),
    );

    let mut available_columns = selected_columns.clone();
    if let Some(calculation) = &recipe.calculated_column {
        available_columns.push(calculation.name.clone());
    }
    if let Some(split) = &split_columns {
        if split.drop_source {
            available_columns.retain(|column| column != &split.source);
        }
        available_columns.extend(split.names.iter().cloned());
    }
    if let Some(merge) = &merge_columns {
        if merge.drop_sources {
            available_columns.retain(|column| !merge.sources.iter().any(|source| source == column));
        }
        available_columns.push(merge.name.clone());
    }
    if split_columns
        .as_ref()
        .is_some_and(|split| split.drop_source)
    {
        available_types.remove(&split_columns.as_ref().expect("split está presente").source);
    }
    if let Some(merge) = &merge_columns {
        if merge.drop_sources {
            for source in &merge.sources {
                available_types.remove(source);
            }
        }
    }
    let outlier_treatments = if recipe.outlier_treatments.is_empty() {
        Vec::new()
    } else {
        if recipe.outlier_treatments.len() > 16 {
            return Err("La receta admite como máximo 16 tratamientos de atípicos.".into());
        }
        let mut unique_columns = HashSet::new();
        recipe
            .outlier_treatments
            .iter()
            .map(|treatment| {
                if !unique_columns.insert(treatment.column.as_str()) {
                    return Err(format!(
                        "La columna '{}' tiene más de un tratamiento de atípicos.",
                        treatment.column
                    ));
                }
                let column = rename_map
                    .get(&treatment.column)
                    .cloned()
                    .unwrap_or_else(|| treatment.column.clone());
                let dtype = available_types.get(&column).cloned().ok_or_else(|| {
                    format!(
                        "La columna '{column}' para tratar atípicos no sobrevivió las etapas estructurales."
                    )
                })?;
                if !matches!(&dtype, DataType::Int64 | DataType::Float64) {
                    return Err(format!(
                        "La columna '{column}' debe ser Int64 o Float64 para tratar valores numéricos."
                    ));
                }
                if treatment.action == OutlierAction::Cap {
                    available_types.insert(column.clone(), DataType::Float64);
                }
                Ok(SourceBackedOutlierPlan {
                    column,
                    action: treatment.action,
                    dtype,
                })
            })
            .collect::<Result<Vec<_>, String>>()?
    };
    let group_summary = recipe
        .group_summary
        .as_ref()
        .map(|summary| {
            source_backed_group_summary_plan(
                summary,
                &rename_map,
                &available_columns,
                &available_types,
            )
        })
        .transpose()?;

    for filter in &recipe.filters {
        let effective = rename_map
            .get(&filter.column)
            .cloned()
            .unwrap_or_else(|| filter.column.clone());
        if !output_columns.iter().any(|column| column == &effective) {
            return Err(format!(
                "La columna '{}' no existe para el filtro source-backed.",
                filter.column
            ));
        }
        let unary = matches!(
            filter.operator,
            RecipeFilterOperator::IsNull | RecipeFilterOperator::NotNull
        );
        if unary != filter.value.is_none() {
            return Err(format!(
                "El filtro '{}' {} un valor.",
                filter.column,
                if unary { "no acepta" } else { "requiere" }
            ));
        }
        let literal = filter.value.as_deref().unwrap_or_default();
        if matches!(
            filter.operator,
            RecipeFilterOperator::Gt
                | RecipeFilterOperator::Lt
                | RecipeFilterOperator::Gte
                | RecipeFilterOperator::Lte
                | RecipeFilterOperator::Contains
                | RecipeFilterOperator::NotContains
        ) && literal.is_empty()
        {
            return Err(format!(
                "El filtro '{}' requiere un valor no vacío.",
                filter.column
            ));
        }
        if literal.contains('\0') {
            return Err("El valor del filtro contiene un carácter no válido.".to_owned());
        }
        if recipe_filter_uses_temporal_literal(filter.operator) {
            let dtype = source_backed_target_dtype(schema, &filter.column, recipe, &rename_map)?;
            if matches!(&dtype, DataType::Date | DataType::Datetime(_, None)) {
                parse_recipe_filter_datetime(literal, &filter.column)?;
            } else if matches!(&dtype, DataType::Datetime(_, Some(_))) {
                return Err(format!(
                    "La comparación de '{}' no admite fechas con zona horaria.",
                    filter.column
                ));
            } else if recipe_filter_is_ordered(filter.operator) {
                strict_f64(literal, "El valor del filtro")?;
            }
        }
    }

    let dropped_column_count = output_columns.len().saturating_sub(selected_columns.len());
    let kept_order_changed = output_columns != selected_columns;
    Ok(SourceBackedProjectionPlan {
        source_columns,
        output_columns,
        selected_columns,
        renamed_column_count,
        converted_column_count,
        parsed_date_column_count,
        calculated_column_count,
        replacement_columns,
        split_columns,
        merge_columns,
        contact_normalizations,
        text_extractions,
        outlier_treatments,
        group_summary,
        dropped_column_count,
        kept_order_changed,
    })
}

fn duckdb_string_literal(value: &str) -> String {
    format!("'{}'", value.replace('\'', "''"))
}

fn source_backed_regex_replacement(value: &str) -> Result<String, String> {
    let mut output = String::with_capacity(value.len());
    let mut characters = value.chars();
    while let Some(character) = characters.next() {
        if character == '\\' {
            return Err(
                "La sustitución regex source-backed no admite barras invertidas literales."
                    .to_owned(),
            );
        }
        if character != '$' {
            output.push(character);
            continue;
        }
        match characters.next() {
            Some('$') => output.push('$'),
            Some(group @ '1'..='9') => {
                output.push('\\');
                output.push(group);
            }
            Some('{') => {
                let group = characters.next();
                if !matches!(group, Some('1'..='9')) || characters.next() != Some('}') {
                    return Err(
                        "La sustitución regex source-backed solo admite grupos $1 a $9.".to_owned(),
                    );
                }
                output.push('\\');
                output.push(group.expect("se validó el grupo regex"));
            }
            _ => return Err(
                "La sustitución regex source-backed solo admite texto literal y grupos $1 a $9."
                    .to_owned(),
            ),
        }
    }
    Ok(output)
}

fn source_backed_replace_expression(
    value: &str,
    replacement: &FindReplaceRecipe,
) -> Result<String, String> {
    if replacement.regex {
        let replacement_text = source_backed_regex_replacement(&replacement.replace)?;
        Ok(format!(
            "regexp_replace(CAST({value} AS VARCHAR), {}, {}, 'g')",
            duckdb_string_literal(&replacement.find),
            duckdb_string_literal(&replacement_text)
        ))
    } else {
        Ok(format!(
            "replace(CAST({value} AS VARCHAR), {}, {})",
            duckdb_string_literal(&replacement.find),
            duckdb_string_literal(&replacement.replace)
        ))
    }
}

fn source_backed_filter_expression(
    filter: &RecipeFilter,
    rename_map: &HashMap<String, String>,
    dtype: &DataType,
) -> Result<String, String> {
    let effective = rename_map
        .get(&filter.column)
        .map(String::as_str)
        .unwrap_or(filter.column.as_str());
    let column = format!("t.{}", duckdb_identifier(effective));
    let literal = filter.value.as_deref().unwrap_or_default();
    let expression = match filter.operator {
        RecipeFilterOperator::IsNull => format!("{column} IS NULL"),
        RecipeFilterOperator::NotNull => format!("{column} IS NOT NULL"),
        RecipeFilterOperator::Eq | RecipeFilterOperator::Neq
            if matches!(dtype, DataType::Date | DataType::Datetime(_, None)) =>
        {
            let datetime = parse_recipe_filter_datetime(literal, &filter.column)?;
            let operator = if filter.operator == RecipeFilterOperator::Eq {
                "="
            } else {
                "<>"
            };
            let literal = match dtype {
                DataType::Date => format!(
                    "DATE {}",
                    duckdb_string_literal(&datetime.date().format("%Y-%m-%d").to_string())
                ),
                DataType::Datetime(_, None) => format!(
                    "TIMESTAMP {}",
                    duckdb_string_literal(&datetime.format("%Y-%m-%d %H:%M:%S%.f").to_string(),)
                ),
                _ => unreachable!("el match exterior limita esta rama a fechas"),
            };
            format!("{column} {operator} {literal}")
        }
        RecipeFilterOperator::Eq => format!(
            "CAST({column} AS VARCHAR) = {}",
            duckdb_string_literal(literal)
        ),
        RecipeFilterOperator::Neq => format!(
            "CAST({column} AS VARCHAR) <> {}",
            duckdb_string_literal(literal)
        ),
        RecipeFilterOperator::Contains => format!(
            "strpos(lower(CAST({column} AS VARCHAR)), lower({})) > 0",
            duckdb_string_literal(literal)
        ),
        RecipeFilterOperator::NotContains => format!(
            "strpos(lower(CAST({column} AS VARCHAR)), lower({})) = 0",
            duckdb_string_literal(literal)
        ),
        RecipeFilterOperator::Gt
        | RecipeFilterOperator::Lt
        | RecipeFilterOperator::Gte
        | RecipeFilterOperator::Lte => {
            let operator = match filter.operator {
                RecipeFilterOperator::Gt => ">",
                RecipeFilterOperator::Lt => "<",
                RecipeFilterOperator::Gte => ">=",
                RecipeFilterOperator::Lte => "<=",
                _ => unreachable!("el match exterior limita los operadores numéricos"),
            };
            if matches!(dtype, DataType::Date | DataType::Datetime(_, None)) {
                let datetime = parse_recipe_filter_datetime(literal, &filter.column)?;
                let literal = match dtype {
                    DataType::Date => format!(
                        "DATE {}",
                        duckdb_string_literal(&datetime.date().format("%Y-%m-%d").to_string())
                    ),
                    DataType::Datetime(_, None) => format!(
                        "TIMESTAMP {}",
                        duckdb_string_literal(&datetime.format("%Y-%m-%d %H:%M:%S%.f").to_string(),)
                    ),
                    _ => unreachable!("el match exterior limita esta rama a fechas"),
                };
                format!("{column} {operator} {literal}")
            } else if matches!(dtype, DataType::Datetime(_, Some(_))) {
                return Err(format!(
                    "La comparación de '{}' no admite fechas con zona horaria.",
                    filter.column
                ));
            } else {
                let numeric_literal = strict_f64(literal, "El valor del filtro")?;
                format!("CAST({column} AS DOUBLE) {operator} {numeric_literal}")
            }
        }
    };
    Ok(expression)
}

fn duckdb_cast_type(target: RecipeCastTarget) -> &'static str {
    match target {
        RecipeCastTarget::String => "VARCHAR",
        RecipeCastTarget::Integer => "BIGINT",
        RecipeCastTarget::Decimal => "DOUBLE",
        RecipeCastTarget::Boolean => "BOOLEAN",
    }
}

fn duckdb_date_format(format: RecipeDateFormat) -> Result<&'static str, String> {
    match format {
        RecipeDateFormat::Ymd => Ok("%Y-%m-%d"),
        RecipeDateFormat::Dmy => Ok("%d/%m/%Y"),
        RecipeDateFormat::Mdy => Ok("%m/%d/%Y"),
        RecipeDateFormat::Iso8601 => Err("ISO no usa un formato único.".to_owned()),
    }
}

fn duckdb_iso8601_expression(column: &str, target: RecipeDateTarget) -> String {
    let raw = format!("TRIM(CAST({column} AS VARCHAR))");
    let without_utc_suffix = format!(
        "CASE WHEN RIGHT({raw}, 1) = 'Z' THEN SUBSTR({raw}, 1, LENGTH({raw}) - 1) ELSE {raw} END"
    );
    let value = format!("NULLIF({without_utc_suffix}, '')");
    let parsed = [
        "%Y-%m-%d",
        "%Y-%m-%dT%H:%M:%S.%f",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S.%f",
        "%Y-%m-%d %H:%M:%S",
    ]
    .into_iter()
    .map(|format| format!("try_strptime({value}, {})", duckdb_string_literal(format)))
    .collect::<Vec<_>>()
    .join(", ");
    let parsed = format!("COALESCE({parsed})");
    match target {
        RecipeDateTarget::Date => format!("CAST({parsed} AS DATE)"),
        RecipeDateTarget::Datetime => parsed,
    }
}

fn duckdb_date_expression(
    column: &str,
    format: RecipeDateFormat,
    target: RecipeDateTarget,
) -> Result<String, String> {
    if format == RecipeDateFormat::Iso8601 {
        return Ok(duckdb_iso8601_expression(column, target));
    }
    let parsed = format!(
        "strptime(NULLIF(TRIM(CAST({column} AS VARCHAR)), ''), {})",
        duckdb_string_literal(duckdb_date_format(format)?)
    );
    Ok(match target {
        RecipeDateTarget::Date => format!("CAST({parsed} AS DATE)"),
        RecipeDateTarget::Datetime => parsed,
    })
}

fn duckdb_calculation_expression(
    calculation: &CalculatedColumnRecipe,
    rename_map: &HashMap<String, String>,
) -> Result<String, String> {
    let source_name = rename_map
        .get(&calculation.source)
        .map(String::as_str)
        .unwrap_or(calculation.source.as_str());
    let source = format!("CAST(t.{} AS DOUBLE)", duckdb_identifier(source_name));
    match calculation.operation {
        CalculatedOperation::Concat => {
            let operand = calculation
                .operand
                .as_ref()
                .ok_or_else(|| "La operación calculada requiere un operando.".to_owned())?;
            let source = format!("CAST(t.{} AS VARCHAR)", duckdb_identifier(source_name));
            let operand = match operand.kind {
                CalculatedOperandKind::Literal => duckdb_string_literal(&operand.value),
                CalculatedOperandKind::Column => {
                    let operand_name = rename_map
                        .get(&operand.value)
                        .map(String::as_str)
                        .unwrap_or(operand.value.as_str());
                    format!("CAST(t.{} AS VARCHAR)", duckdb_identifier(operand_name))
                }
            };
            Ok(format!("{source} || {operand}"))
        }
        CalculatedOperation::Add
        | CalculatedOperation::Subtract
        | CalculatedOperation::Multiply
        | CalculatedOperation::Divide => {
            let operand = calculation
                .operand
                .as_ref()
                .ok_or_else(|| "La operación calculada requiere un operando.".to_owned())?;
            let operand = match operand.kind {
                CalculatedOperandKind::Literal => {
                    let value = strict_f64(&operand.value, "El operando numérico")?;
                    if calculation.operation == CalculatedOperation::Divide && value == 0.0 {
                        return Err("División por cero en el operando numérico.".to_owned());
                    }
                    value.to_string()
                }
                CalculatedOperandKind::Column => {
                    let operand_name = rename_map
                        .get(&operand.value)
                        .map(String::as_str)
                        .unwrap_or(operand.value.as_str());
                    format!("CAST(t.{} AS DOUBLE)", duckdb_identifier(operand_name))
                }
            };
            let operator = match calculation.operation {
                CalculatedOperation::Add => "+",
                CalculatedOperation::Subtract => "-",
                CalculatedOperation::Multiply => "*",
                CalculatedOperation::Divide => "/",
                _ => {
                    unreachable!("el match exterior limita las operaciones numéricas source-backed")
                }
            };
            let operand = if calculation.operation == CalculatedOperation::Divide {
                format!("NULLIF({operand}, 0)")
            } else {
                operand
            };
            Ok(format!("{source} {operator} {operand}"))
        }
        CalculatedOperation::Year => Ok(format!(
            "CAST(year(t.{}) AS INTEGER)",
            duckdb_identifier(source_name)
        )),
        CalculatedOperation::Month => Ok(format!(
            "CAST(month(t.{}) AS INTEGER)",
            duckdb_identifier(source_name)
        )),
        CalculatedOperation::Day => Ok(format!(
            "CAST(day(t.{}) AS INTEGER)",
            duckdb_identifier(source_name)
        )),
    }
}

fn source_backed_text_extraction_expression(
    extraction: &SourceBackedTextExtractionPlan,
) -> Result<String, String> {
    let value = format!(
        "CAST(t.{} AS VARCHAR)",
        duckdb_identifier(&extraction.source)
    );
    match extraction.kind {
        ExtractionKind::FirstToken
        | ExtractionKind::LastToken
        | ExtractionKind::Digits
        | ExtractionKind::Letters => {
            let pattern = match extraction.kind {
                ExtractionKind::FirstToken => r"^\s*(\S+)",
                ExtractionKind::LastToken => r"(\S+)\s*$",
                ExtractionKind::Digits => r"([0-9]+)",
                ExtractionKind::Letters => r"(\p{L}+)",
                ExtractionKind::Before | ExtractionKind::After => {
                    unreachable!("el match exterior limita las extracciones regex")
                }
            };
            let pattern = duckdb_string_literal(pattern);
            Ok(format!(
                "CASE WHEN {value} IS NOT NULL AND regexp_matches({value}, {pattern}) THEN regexp_extract({value}, {pattern}, 1) ELSE NULL END AS {}",
                duckdb_identifier(&extraction.name)
            ))
        }
        ExtractionKind::Before | ExtractionKind::After => {
            let delimiter = extraction.delimiter.as_deref().ok_or_else(|| {
                "La extracción antes/después del delimitador requiere delimitador.".to_owned()
            })?;
            let delimiter = duckdb_string_literal(delimiter);
            let position = format!("strpos({value}, {delimiter})");
            let expression = match extraction.kind {
                ExtractionKind::Before => {
                    format!("left({value}, {position} - 1)")
                }
                ExtractionKind::After => {
                    format!("substr({value}, {position} + length({delimiter}))")
                }
                ExtractionKind::FirstToken
                | ExtractionKind::LastToken
                | ExtractionKind::Digits
                | ExtractionKind::Letters => {
                    unreachable!("el match exterior limita las extracciones por delimitador")
                }
            };
            Ok(format!(
                "CASE WHEN {value} IS NOT NULL AND {position} > 0 THEN {expression} ELSE NULL END AS {}",
                duckdb_identifier(&extraction.name)
            ))
        }
    }
}

fn source_backed_contact_normalization_expression(
    normalization: &SourceBackedContactNormalizationPlan,
) -> String {
    let value = format!(
        "CAST(t.{} AS VARCHAR)",
        duckdb_identifier(&normalization.column)
    );
    let trimmed = format!(
        "regexp_replace({value}, {}, '', 'g')",
        duckdb_string_literal(r"^[\s\p{Z}]+|[\s\p{Z}]+$")
    );
    match normalization.kind {
        ContactKind::Email => format!("lower({trimmed})"),
        ContactKind::Phone => {
            let digits = format!(
                "regexp_replace({value}, {}, '', 'g')",
                duckdb_string_literal(r"[^0-9]+")
            );
            format!(
                "CASE WHEN {value} IS NULL THEN NULL WHEN left({trimmed}, 1) = '+' THEN '+' || {digits} ELSE {digits} END"
            )
        }
        ContactKind::Address => format!(
            "trim(regexp_replace({value}, {}, ' ', 'g'))",
            duckdb_string_literal(r"[\s\p{Z}]+")
        ),
    }
}

fn source_backed_summary_aggregate_expression(
    aggregation: &SourceBackedSummaryAggregationPlan,
) -> String {
    let identifier = duckdb_identifier(&aggregation.column);
    let value = format!("t.{identifier}");
    let expression = match aggregation.operation {
        SummaryOperation::Sum if aggregation.dtype == DataType::Int64 => {
            format!("CAST(SUM({value}) AS BIGINT)")
        }
        SummaryOperation::Sum => format!("SUM({value})"),
        SummaryOperation::Mean => format!("AVG({value})"),
        SummaryOperation::Min => format!("MIN({value})"),
        SummaryOperation::Max => format!("MAX({value})"),
        SummaryOperation::Count => "COUNT(*)".to_owned(),
        SummaryOperation::CountUnique => format!("COUNT(DISTINCT {value})"),
    };
    format!("{expression} AS {}", duckdb_identifier(&aggregation.output))
}

fn source_backed_outlier_alias(index: usize, metric: &str) -> String {
    duckdb_identifier(&format!("__columnia_outlier_{metric}_{index}"))
}

fn source_backed_outlier_value(plan: &SourceBackedOutlierPlan) -> String {
    format!("CAST(t.{} AS DOUBLE)", duckdb_identifier(&plan.column))
}

fn source_backed_outlier_condition(plan: &SourceBackedOutlierPlan, index: usize) -> String {
    let value = source_backed_outlier_value(plan);
    let lower = source_backed_outlier_alias(index, "lower");
    let upper = source_backed_outlier_alias(index, "upper");
    format!("{value} IS NOT NULL AND ({value} < s.{lower} OR {value} > s.{upper})")
}

fn source_backed_projection_query(
    schema: &DataFrame,
    recipe: &TransformRecipe,
) -> Result<SourceBackedProjectionQueries, String> {
    let plan = source_backed_projection_plan(schema, recipe)?;
    let rename_map = recipe
        .renames
        .iter()
        .map(|rename| (rename.from.clone(), rename.to.clone()))
        .collect::<HashMap<_, _>>();
    let renamed_expressions = plan
        .source_columns
        .iter()
        .zip(&plan.output_columns)
        .map(|(source_name, output_name)| {
            if output_name == source_name {
                duckdb_identifier(source_name)
            } else {
                format!(
                    "{} AS {}",
                    duckdb_identifier(source_name),
                    duckdb_identifier(output_name)
                )
            }
        })
        .collect::<Vec<_>>();
    let cast_targets = recipe
        .casts
        .iter()
        .filter_map(|cast| {
            let column = recipe_column(schema, &cast.column).ok()?;
            let already_target = matches!(
                (column.dtype(), cast.target),
                (DataType::String, RecipeCastTarget::String)
                    | (DataType::Int64, RecipeCastTarget::Integer)
                    | (DataType::Float64, RecipeCastTarget::Decimal)
                    | (DataType::Boolean, RecipeCastTarget::Boolean)
            );
            if already_target {
                None
            } else {
                let effective = rename_map
                    .get(&cast.column)
                    .cloned()
                    .unwrap_or_else(|| cast.column.clone());
                Some((effective, cast.target))
            }
        })
        .collect::<HashMap<_, _>>();
    let date_targets = recipe
        .date_parses
        .iter()
        .filter_map(|parse| {
            let column = recipe_column(schema, &parse.column).ok()?;
            let already_target = matches!(
                (column.dtype(), parse.target),
                (DataType::Date, RecipeDateTarget::Date)
                    | (DataType::Datetime(_, _), RecipeDateTarget::Datetime)
            );
            if already_target {
                None
            } else {
                let effective = rename_map
                    .get(&parse.column)
                    .cloned()
                    .unwrap_or_else(|| parse.column.clone());
                Some((effective, (parse.format, parse.target)))
            }
        })
        .collect::<HashMap<_, _>>();
    let transformed_expressions = plan
        .output_columns
        .iter()
        .map(|column| -> Result<String, String> {
            let input = format!("t.{}", duckdb_identifier(column));
            let expression = if let Some(target) = cast_targets.get(column) {
                format!(
                    "CAST({input} AS {}) AS {}",
                    duckdb_cast_type(*target),
                    duckdb_identifier(column)
                )
            } else if let Some((format, target)) = date_targets.get(column) {
                format!(
                    "{} AS {}",
                    duckdb_date_expression(&input, *format, *target)?,
                    duckdb_identifier(column)
                )
            } else {
                format!("{input} AS {}", duckdb_identifier(column))
            };
            Ok(expression)
        })
        .collect::<Result<Vec<_>, String>>()?;
    let filters = recipe
        .filters
        .iter()
        .map(|filter| {
            let dtype = source_backed_target_dtype(schema, &filter.column, recipe, &rename_map)?;
            source_backed_filter_expression(filter, &rename_map, &dtype)
        })
        .collect::<Result<Vec<_>, _>>()?;
    let filtered_source = if filters.is_empty() {
        "transformed"
    } else {
        "filtered"
    };
    let filter_cte = if filters.is_empty() {
        String::new()
    } else {
        format!(
            ", filtered AS (SELECT * FROM transformed AS t WHERE {})",
            filters.join(" AND ")
        )
    };
    let replacement_cte = if plan.replacement_columns.is_empty() {
        String::new()
    } else {
        let replacement = recipe
            .find_replace
            .as_ref()
            .expect("las columnas de reemplazo requieren una receta de reemplazo");
        let expressions = plan
            .output_columns
            .iter()
            .map(|column| -> Result<String, String> {
                let identifier = duckdb_identifier(column);
                if plan
                    .replacement_columns
                    .iter()
                    .any(|target| target == column)
                {
                    Ok(format!(
                        "{} AS {identifier}",
                        source_backed_replace_expression(&format!("t.{identifier}"), replacement,)?
                    ))
                } else {
                    Ok(format!("t.{identifier} AS {identifier}"))
                }
            })
            .collect::<Result<Vec<_>, String>>()?;
        format!(
            ", replaced AS (SELECT {} FROM {} AS t)",
            expressions.join(", "),
            filtered_source
        )
    };
    let mut result_source = if plan.replacement_columns.is_empty() {
        filtered_source
    } else {
        "replaced"
    };
    let calculation_input_source = if plan.replacement_columns.is_empty() {
        filtered_source
    } else {
        "replaced"
    };
    let calculation_validation = recipe
        .calculated_column
        .as_ref()
        .filter(|calculation| calculation.operation == CalculatedOperation::Divide)
        .and_then(|calculation| {
            let CalculatedOperand {
                kind: CalculatedOperandKind::Column,
                value,
            } = calculation.operand.as_ref()?
            else {
                return None;
            };
            let source_name = rename_map
                .get(&calculation.source)
                .map(String::as_str)
                .unwrap_or(calculation.source.as_str());
            let operand_name = rename_map
                .get(value)
                .map(String::as_str)
                .unwrap_or(value.as_str());
            let source = format!("t.{}", duckdb_identifier(source_name));
            let operand = format!("t.{}", duckdb_identifier(operand_name));
            Some(format!(
                "WITH renamed AS (SELECT {} FROM dataset), transformed AS (SELECT {} FROM renamed AS t){}{} SELECT CASE WHEN EXISTS (SELECT 1 FROM {calculation_input_source} AS t WHERE {source} IS NOT NULL AND {operand} IS NOT NULL AND CAST({operand} AS DOUBLE) = 0) THEN 1 ELSE 0 END",
                renamed_expressions.join(", "),
                transformed_expressions.join(", "),
                filter_cte,
                replacement_cte
            ))
        });
    let calculation_cte = if let Some(calculation) = &recipe.calculated_column {
        result_source = "calculated";
        format!(
            ", calculated AS (SELECT *, {} AS {} FROM {} AS t)",
            duckdb_calculation_expression(calculation, &rename_map)?,
            duckdb_identifier(&calculation.name),
            calculation_input_source
        )
    } else {
        String::new()
    };
    let split_cte = if let Some(split) = &plan.split_columns {
        let source = result_source;
        let value = format!("CAST(t.{} AS VARCHAR)", duckdb_identifier(&split.source));
        let parts = format!(
            "string_split({value}, {})",
            duckdb_string_literal(&split.delimiter)
        );
        let part_count = format!("array_length({parts})");
        let expressions = split
            .names
            .iter()
            .enumerate()
            .map(|(index, name)| {
                let position = index + 1;
                let value = if position == split.names.len() {
                    format!(
                        "CASE WHEN {part_count} >= {position} THEN array_to_string(list_slice({parts}, {position}, {part_count}), {}) ELSE NULL END",
                        duckdb_string_literal(&split.delimiter)
                    )
                } else {
                    format!(
                        "CASE WHEN {part_count} >= {position} THEN split_part({value}, {}, {position}) ELSE NULL END",
                        duckdb_string_literal(&split.delimiter)
                    )
                };
                format!("{value} AS {}", duckdb_identifier(name))
            })
            .collect::<Vec<_>>();
        result_source = "split";
        format!(
            ", split AS (SELECT *, {} FROM {source} AS t)",
            expressions.join(", ")
        )
    } else {
        String::new()
    };
    let merge_cte = if let Some(merge) = &plan.merge_columns {
        let source_expressions = merge
            .sources
            .iter()
            .map(|column| format!("CAST(t.{} AS VARCHAR)", duckdb_identifier(column)))
            .collect::<Vec<_>>();
        let any_source_present = source_expressions
            .iter()
            .map(|expression| format!("{expression} IS NOT NULL"))
            .collect::<Vec<_>>()
            .join(" OR ");
        let joined = format!(
            "concat_ws({}, {})",
            duckdb_string_literal(&merge.separator),
            source_expressions.join(", ")
        );
        let merge_expression = format!(
            "CASE WHEN {any_source_present} THEN {joined} ELSE NULL END AS {}",
            duckdb_identifier(&merge.name)
        );
        let source = result_source;
        result_source = "merged";
        format!(", merged AS (SELECT *, {merge_expression} FROM {source} AS t)")
    } else {
        String::new()
    };
    let mut output_columns = plan.selected_columns.clone();
    if let Some(calculation) = &recipe.calculated_column {
        output_columns.push(calculation.name.clone());
    }
    if let Some(split) = &plan.split_columns {
        if split.drop_source {
            output_columns.retain(|column| column != &split.source);
        }
        output_columns.extend(split.names.iter().cloned());
    }
    if let Some(merge) = &plan.merge_columns {
        if merge.drop_sources {
            output_columns.retain(|column| !merge.sources.iter().any(|source| source == column));
        }
        output_columns.push(merge.name.clone());
    }
    let outlier_input_source = result_source;
    let pre_outlier_ctes = format!(
        "WITH renamed AS (SELECT {} FROM dataset), transformed AS (SELECT {} FROM renamed AS t){}{}{}{}{}",
        renamed_expressions.join(", "),
        transformed_expressions.join(", "),
        filter_cte,
        replacement_cte,
        calculation_cte,
        split_cte,
        merge_cte
    );
    let outlier_quantile_cte = if plan.outlier_treatments.is_empty() {
        String::new()
    } else {
        let expressions = plan
            .outlier_treatments
            .iter()
            .enumerate()
            .flat_map(|(index, treatment)| {
                let value = format!("CAST(t.{} AS DOUBLE)", duckdb_identifier(&treatment.column));
                let median = if treatment.dtype == DataType::Int64 {
                    format!("quantile_disc({value}, 0.5)")
                } else {
                    format!("quantile_cont({value}, 0.5)")
                };
                [
                    format!(
                        "quantile_cont({value}, 0.25) AS {}",
                        source_backed_outlier_alias(index, "q1")
                    ),
                    format!(
                        "quantile_cont({value}, 0.75) AS {}",
                        source_backed_outlier_alias(index, "q3")
                    ),
                    format!(
                        "{median} AS {}",
                        source_backed_outlier_alias(index, "median")
                    ),
                    format!(
                        "COUNT(t.{}) AS {}",
                        duckdb_identifier(&treatment.column),
                        source_backed_outlier_alias(index, "valid_count")
                    ),
                ]
            })
            .collect::<Vec<_>>();
        format!(
            ", outlier_quantiles AS (SELECT {} FROM {outlier_input_source} AS t)",
            expressions.join(", ")
        )
    };
    let outlier_stats_cte = if plan.outlier_treatments.is_empty() {
        String::new()
    } else {
        let expressions = plan
            .outlier_treatments
            .iter()
            .enumerate()
            .flat_map(|(index, _)| {
                let q1 = source_backed_outlier_alias(index, "q1");
                let q3 = source_backed_outlier_alias(index, "q3");
                let median = source_backed_outlier_alias(index, "median");
                [
                    format!("q.{q1} AS {q1}"),
                    format!("q.{q3} AS {q3}"),
                    format!(
                        "q.{q1} - 1.5 * (q.{q3} - q.{q1}) AS {}",
                        source_backed_outlier_alias(index, "lower")
                    ),
                    format!(
                        "q.{q3} + 1.5 * (q.{q3} - q.{q1}) AS {}",
                        source_backed_outlier_alias(index, "upper")
                    ),
                    format!("q.{median} AS {median}"),
                    format!(
                        "q.{} AS {}",
                        source_backed_outlier_alias(index, "valid_count"),
                        source_backed_outlier_alias(index, "valid_count")
                    ),
                ]
            })
            .collect::<Vec<_>>();
        format!(
            ", outlier_stats AS (SELECT {} FROM outlier_quantiles AS q)",
            expressions.join(", ")
        )
    };
    let outlier_cte = if plan.outlier_treatments.is_empty() {
        String::new()
    } else {
        let expressions = output_columns
            .iter()
            .map(|column| {
                let identifier = duckdb_identifier(column);
                plan.outlier_treatments
                    .iter()
                    .enumerate()
                    .find(|(_, treatment)| treatment.column == *column)
                    .map_or_else(
                        || format!("t.{identifier} AS {identifier}"),
                        |(index, treatment)| {
                            let value = format!("CAST(t.{identifier} AS DOUBLE)");
                            let condition = source_backed_outlier_condition(treatment, index);
                            let lower = format!(
                                "s.{}",
                                source_backed_outlier_alias(index, "lower")
                            );
                            let upper = format!(
                                "s.{}",
                                source_backed_outlier_alias(index, "upper")
                            );
                            let median = format!(
                                "s.{}",
                                source_backed_outlier_alias(index, "median")
                            );
                            let expression = match treatment.action {
                                OutlierAction::Cap => format!(
                                    "CASE WHEN {value} IS NULL THEN NULL WHEN {value} < {lower} THEN {lower} WHEN {value} > {upper} THEN {upper} ELSE {value} END"
                                ),
                                OutlierAction::Impute => {
                                    let replacement = if treatment.dtype == DataType::Int64 {
                                        format!("CAST({median} AS BIGINT)")
                                    } else {
                                        median
                                    };
                                    let original = if treatment.dtype == DataType::Int64 {
                                        format!("t.{identifier}")
                                    } else {
                                        value.clone()
                                    };
                                    format!(
                                        "CASE WHEN {value} IS NULL THEN NULL WHEN {condition} THEN {replacement} ELSE {original} END"
                                    )
                                }
                                OutlierAction::Drop => format!("t.{identifier}"),
                            };
                            format!("{expression} AS {identifier}")
                        },
                    )
            })
            .collect::<Vec<_>>();
        let drop_conditions = plan
            .outlier_treatments
            .iter()
            .enumerate()
            .filter(|(_, treatment)| treatment.action == OutlierAction::Drop)
            .map(|(index, treatment)| source_backed_outlier_condition(treatment, index))
            .collect::<Vec<_>>();
        let where_clause = if drop_conditions.is_empty() {
            String::new()
        } else {
            format!(" WHERE NOT ({})", drop_conditions.join(" OR "))
        };
        result_source = "outliers";
        format!(
            "{outlier_quantile_cte}{outlier_stats_cte}, outliers AS (SELECT {} FROM {outlier_input_source} AS t CROSS JOIN outlier_stats AS s{where_clause})",
            expressions.join(", ")
        )
    };
    let contact_input_source = result_source;
    let contact_normalization_cte = if plan.contact_normalizations.is_empty() {
        String::new()
    } else {
        let expressions = output_columns
            .iter()
            .map(|column| {
                let identifier = duckdb_identifier(column);
                if let Some(normalization) = plan
                    .contact_normalizations
                    .iter()
                    .find(|normalization| normalization.column == *column)
                {
                    format!(
                        "{} AS {identifier}",
                        source_backed_contact_normalization_expression(normalization)
                    )
                } else {
                    format!("t.{identifier} AS {identifier}")
                }
            })
            .collect::<Vec<_>>();
        result_source = "normalized_contacts";
        format!(
            ", normalized_contacts AS (SELECT {} FROM {contact_input_source} AS t)",
            expressions.join(", ")
        )
    };
    let text_extraction_cte = if plan.text_extractions.is_empty() {
        String::new()
    } else {
        let source = result_source;
        let expressions = plan
            .text_extractions
            .iter()
            .map(source_backed_text_extraction_expression)
            .collect::<Result<Vec<_>, String>>()?;
        result_source = "text_extracted";
        format!(
            ", text_extracted AS (SELECT *, {} FROM {source} AS t)",
            expressions.join(", ")
        )
    };
    output_columns.extend(
        plan.text_extractions
            .iter()
            .map(|extraction| extraction.name.clone()),
    );
    let pre_group_ctes = format!(
        "WITH renamed AS (SELECT {} FROM dataset), transformed AS (SELECT {} FROM renamed AS t){}{}{}{}{}{}{}{}",
        renamed_expressions.join(", "),
        transformed_expressions.join(", "),
        filter_cte,
        replacement_cte,
        calculation_cte,
        split_cte,
        merge_cte,
        outlier_cte,
        contact_normalization_cte,
        text_extraction_cte
    );
    let group_input_source = result_source;
    let mut final_ctes = pre_group_ctes.clone();
    let mut final_source = result_source;
    let mut final_columns = output_columns;
    let mut final_order_column = None;
    let mut group_input_count = None;
    let mut group_validation = None;
    let mut output_validation = None;
    if let Some(summary) = &plan.group_summary {
        const GROUP_ORDER_COLUMN: &str = "__columnia_group_order";
        if final_columns
            .iter()
            .any(|column| column == GROUP_ORDER_COLUMN)
        {
            return Err(format!(
                "La receta no puede usar la columna reservada '{GROUP_ORDER_COLUMN}' para agrupar."
            ));
        }
        let order_identifier = duckdb_identifier(GROUP_ORDER_COLUMN);
        final_ctes.push_str(&format!(
            ", ordered AS (SELECT *, row_number() OVER () AS {order_identifier} FROM {group_input_source} AS t)"
        ));
        let group_select = summary
            .group_by
            .iter()
            .map(|column| {
                let identifier = duckdb_identifier(column);
                format!("t.{identifier} AS {identifier}")
            })
            .chain(
                summary
                    .aggregations
                    .iter()
                    .map(source_backed_summary_aggregate_expression),
            )
            .chain(std::iter::once(format!(
                "MIN(t.{order_identifier}) AS {order_identifier}"
            )))
            .collect::<Vec<_>>();
        let group_by = summary
            .group_by
            .iter()
            .map(|column| format!("t.{}", duckdb_identifier(column)))
            .collect::<Vec<_>>()
            .join(", ");
        final_ctes.push_str(&format!(
            ", grouped AS (SELECT {} FROM ordered AS t GROUP BY {})",
            group_select.join(", "),
            group_by
        ));
        final_source = "grouped";
        final_order_column = Some(GROUP_ORDER_COLUMN);
        final_columns = summary
            .group_by
            .iter()
            .cloned()
            .chain(
                summary
                    .aggregations
                    .iter()
                    .map(|aggregation| aggregation.output.clone()),
            )
            .collect();

        group_input_count = Some(format!(
            "{pre_group_ctes} SELECT CAST(COUNT(*) AS BIGINT) FROM {group_input_source}"
        ));

        let mut invalid_input_terms = Vec::new();
        for (column, dtype) in summary.group_by.iter().zip(&summary.group_dtypes) {
            if dtype == &DataType::Float64 {
                let identifier = duckdb_identifier(column);
                invalid_input_terms.push(format!(
                    "t.{identifier} IS NOT NULL AND NOT isfinite(CAST(t.{identifier} AS DOUBLE))"
                ));
            }
        }
        let mut integer_sum_overflow_terms = Vec::new();
        for aggregation in &summary.aggregations {
            let identifier = duckdb_identifier(&aggregation.column);
            if aggregation.dtype == DataType::Float64
                && matches!(
                    aggregation.operation,
                    SummaryOperation::Sum
                        | SummaryOperation::Mean
                        | SummaryOperation::Min
                        | SummaryOperation::Max
                        | SummaryOperation::CountUnique
                )
            {
                invalid_input_terms.push(format!(
                    "t.{identifier} IS NOT NULL AND NOT isfinite(CAST(t.{identifier} AS DOUBLE))"
                ));
            }
            if aggregation.dtype == DataType::Int64
                && aggregation.operation == SummaryOperation::Mean
            {
                invalid_input_terms.push(format!(
                    "t.{identifier} IS NOT NULL AND abs(CAST(t.{identifier} AS DOUBLE)) > 9007199254740992"
                ));
            }
            if aggregation.dtype == DataType::Int64
                && aggregation.operation == SummaryOperation::Sum
            {
                integer_sum_overflow_terms.push(format!(
                    "SUM(CAST(t.{identifier} AS HUGEINT)) > 9223372036854775807 OR SUM(CAST(t.{identifier} AS HUGEINT)) < -9223372036854775808"
                ));
            }
        }
        let raw_validation = if invalid_input_terms.is_empty() {
            "FALSE".to_owned()
        } else {
            format!(
                "EXISTS (SELECT 1 FROM {group_input_source} AS t WHERE {})",
                invalid_input_terms.join(" OR ")
            )
        };
        let overflow_validation = if integer_sum_overflow_terms.is_empty() {
            "FALSE".to_owned()
        } else {
            format!(
                "EXISTS (SELECT 1 FROM {group_input_source} AS t GROUP BY {group_by} HAVING {})",
                integer_sum_overflow_terms.join(" OR ")
            )
        };
        if raw_validation != "FALSE" || overflow_validation != "FALSE" {
            group_validation = Some(format!(
                "{pre_group_ctes} SELECT CASE WHEN {raw_validation} OR {overflow_validation} THEN 1 ELSE 0 END"
            ));
        }

        let output_invalid_terms = summary
            .group_by
            .iter()
            .zip(&summary.group_dtypes)
            .filter(|(_, dtype)| **dtype == DataType::Float64)
            .map(|(column, _)| {
                let identifier = duckdb_identifier(column);
                format!(
                    "t.{identifier} IS NOT NULL AND NOT isfinite(CAST(t.{identifier} AS DOUBLE))"
                )
            })
            .chain(
                summary
                    .aggregations
                    .iter()
                    .filter(|aggregation| {
                        aggregation.dtype == DataType::Float64
                            && matches!(
                                aggregation.operation,
                                SummaryOperation::Sum
                                    | SummaryOperation::Mean
                                    | SummaryOperation::Min
                                    | SummaryOperation::Max
                            )
                    })
                    .map(|aggregation| {
                        let identifier = duckdb_identifier(&aggregation.output);
                        format!(
                            "t.{identifier} IS NOT NULL AND NOT isfinite(CAST(t.{identifier} AS DOUBLE))"
                        )
                    }),
            )
            .collect::<Vec<_>>();
        if !output_invalid_terms.is_empty() {
            output_validation = Some(format!(
                "SELECT CASE WHEN EXISTS (SELECT 1 FROM dataset AS t WHERE {}) THEN 1 ELSE 0 END",
                output_invalid_terms.join(" OR ")
            ));
        }
    }
    let selected = final_columns
        .iter()
        .map(|column| format!("t.{}", duckdb_identifier(column)))
        .collect::<Vec<_>>();
    let order_clause = final_order_column
        .map(|column| format!(" ORDER BY t.{}", duckdb_identifier(column)))
        .unwrap_or_default();
    let output = format!(
        "{final_ctes} SELECT {} FROM {final_source} AS t{order_clause}",
        selected.join(", ")
    );
    let replacement_count = if plan.replacement_columns.is_empty() {
        None
    } else {
        let replacement = recipe
            .find_replace
            .as_ref()
            .expect("las columnas de reemplazo requieren una receta de reemplazo");
        let changed_terms = plan
            .replacement_columns
            .iter()
            .map(|column| -> Result<String, String> {
                let identifier = duckdb_identifier(column);
                Ok(format!(
                    "CASE WHEN t.{identifier} IS DISTINCT FROM {} THEN 1 ELSE 0 END",
                    source_backed_replace_expression(&format!("t.{identifier}"), replacement,)?
                ))
            })
            .collect::<Result<Vec<_>, String>>()?;
        Some(format!(
            "WITH renamed AS (SELECT {} FROM dataset), transformed AS (SELECT {} FROM renamed AS t){} SELECT CAST(COALESCE(SUM({}), 0) AS BIGINT) FROM {} AS t",
            renamed_expressions.join(", "),
            transformed_expressions.join(", "),
            filter_cte,
            changed_terms.join(" + "),
            filtered_source
        ))
    };
    let normalization_count = if plan.contact_normalizations.is_empty() {
        None
    } else {
        let changed_terms = plan
            .contact_normalizations
            .iter()
            .map(|normalization| {
                let identifier = duckdb_identifier(&normalization.column);
                format!(
                    "CASE WHEN t.{identifier} IS DISTINCT FROM {} THEN 1 ELSE 0 END",
                    source_backed_contact_normalization_expression(normalization)
                )
            })
            .collect::<Vec<_>>();
        Some(format!(
            "WITH renamed AS (SELECT {} FROM dataset), transformed AS (SELECT {} FROM renamed AS t){}{}{}{}{}{} SELECT CAST(COALESCE(SUM({}), 0) AS BIGINT) FROM {} AS t",
            renamed_expressions.join(", "),
            transformed_expressions.join(", "),
            filter_cte,
            replacement_cte,
            calculation_cte,
            split_cte,
            merge_cte,
            outlier_cte,
            changed_terms.join(" + "),
            contact_input_source
        ))
    };
    let outlier_validation = if plan.outlier_treatments.is_empty() {
        None
    } else {
        let mut invalid_terms = Vec::new();
        for (index, treatment) in plan.outlier_treatments.iter().enumerate() {
            let identifier = duckdb_identifier(&treatment.column);
            if treatment.dtype == DataType::Float64 {
                invalid_terms.push(format!(
                    "EXISTS (SELECT 1 FROM {outlier_input_source} AS t WHERE t.{identifier} IS NOT NULL AND NOT isfinite(CAST(t.{identifier} AS DOUBLE)))"
                ));
            } else {
                invalid_terms.push(format!(
                    "EXISTS (SELECT 1 FROM {outlier_input_source} AS t WHERE t.{identifier} IS NOT NULL AND abs(CAST(t.{identifier} AS DOUBLE)) > 9007199254740992)"
                ));
            }
            let q1 = source_backed_outlier_alias(index, "q1");
            let q3 = source_backed_outlier_alias(index, "q3");
            let median = source_backed_outlier_alias(index, "median");
            let lower = source_backed_outlier_alias(index, "lower");
            let upper = source_backed_outlier_alias(index, "upper");
            let valid_count = source_backed_outlier_alias(index, "valid_count");
            invalid_terms.push(format!(
                "EXISTS (SELECT 1 FROM outlier_stats AS s WHERE s.{valid_count} < 4 OR NOT isfinite(CAST(s.{q1} AS DOUBLE)) OR NOT isfinite(CAST(s.{q3} AS DOUBLE)) OR NOT isfinite(CAST(s.{median} AS DOUBLE)) OR NOT isfinite(CAST(s.{lower} AS DOUBLE)) OR NOT isfinite(CAST(s.{upper} AS DOUBLE)))"
            ));
        }
        Some(format!(
            "{pre_outlier_ctes}{outlier_quantile_cte}{outlier_stats_cte} SELECT CASE WHEN {} THEN 1 ELSE 0 END",
            invalid_terms.join(" OR ")
        ))
    };
    let outlier_adjusted_count = if plan.outlier_treatments.is_empty() {
        None
    } else {
        let changed_terms = plan
            .outlier_treatments
            .iter()
            .enumerate()
            .filter(|(_, treatment)| treatment.action != OutlierAction::Drop)
            .map(|(index, treatment)| {
                format!(
                    "CASE WHEN {} THEN 1 ELSE 0 END",
                    source_backed_outlier_condition(treatment, index)
                )
            })
            .collect::<Vec<_>>();
        if changed_terms.is_empty() {
            None
        } else {
            Some(format!(
                "{pre_outlier_ctes}{outlier_quantile_cte}{outlier_stats_cte} SELECT CAST(COALESCE(SUM({}), 0) AS BIGINT) FROM {outlier_input_source} AS t CROSS JOIN outlier_stats AS s",
                changed_terms.join(" + ")
            ))
        }
    };
    let outlier_removed_count = if plan.outlier_treatments.is_empty() {
        None
    } else {
        let drop_conditions = plan
            .outlier_treatments
            .iter()
            .enumerate()
            .filter(|(_, treatment)| treatment.action == OutlierAction::Drop)
            .map(|(index, treatment)| source_backed_outlier_condition(treatment, index))
            .collect::<Vec<_>>();
        if drop_conditions.is_empty() {
            None
        } else {
            Some(format!(
                "{pre_outlier_ctes}{outlier_quantile_cte}{outlier_stats_cte} SELECT CAST(COUNT(*) AS BIGINT) FROM {outlier_input_source} AS t CROSS JOIN outlier_stats AS s WHERE {}",
                drop_conditions.join(" OR ")
            ))
        }
    };
    let input_row_count = if plan.outlier_treatments.is_empty() && plan.group_summary.is_none() {
        None
    } else {
        Some(format!(
            "{pre_group_ctes} SELECT CAST(COUNT(*) AS BIGINT) FROM {filtered_source}"
        ))
    };
    Ok(SourceBackedProjectionQueries {
        output,
        replacement_count,
        normalization_count,
        outlier_adjusted_count,
        outlier_removed_count,
        outlier_validation,
        input_row_count,
        group_input_count,
        group_validation,
        output_validation,
        calculation_validation,
    })
}

struct SourceBackedProjectionQueries {
    output: String,
    replacement_count: Option<String>,
    normalization_count: Option<String>,
    outlier_adjusted_count: Option<String>,
    outlier_removed_count: Option<String>,
    outlier_validation: Option<String>,
    input_row_count: Option<String>,
    group_input_count: Option<String>,
    group_validation: Option<String>,
    output_validation: Option<String>,
    calculation_validation: Option<String>,
}

fn apply_source_backed_projection_recipe(
    dataset: &mut LoadedDataset,
    recipe: &TransformRecipe,
) -> Result<TransformRecipeResult, String> {
    let source_reference = dataset
        .source_path
        .as_deref()
        .ok_or_else(|| "La fuente source-backed ya no está disponible.".to_owned())?;
    let (original_source_path, source_size, original_extension) =
        validate_dataset_file(source_reference)?;
    if source_size != dataset.file_size_bytes {
        return Err("El archivo source-backed cambió después de la carga.".to_owned());
    }
    let (source_path, source_format, extension) = if let Some(snapshot_path) =
        dataset.history.source_snapshot_path.as_deref()
    {
        let (snapshot_path, _, snapshot_extension) = validate_dataset_file(snapshot_path)?;
        if snapshot_extension != "parquet" {
            return Err("El snapshot source-backed no es un Parquet válido.".to_owned());
        }
        (
            snapshot_path,
            crate::duckdb_query::DuckDbFileFormat::Parquet,
            snapshot_extension,
        )
    } else {
        let source_format = match original_extension.as_str() {
            "parquet" => crate::duckdb_query::DuckDbFileFormat::Parquet,
            "csv" | "tsv" | "txt" => {
                let delimiter = detect_delimiter(&original_source_path, &original_extension)?;
                crate::duckdb_query::DuckDbFileFormat::Delimited { delimiter }
            }
            "json" | "jsonl" | "ndjson" => crate::duckdb_query::DuckDbFileFormat::Json,
            _ => {
                return Err("La receta source-backed requiere una fuente compatible.".to_owned());
            }
        };
        (
            original_source_path.clone(),
            source_format,
            original_extension.clone(),
        )
    };
    let schema = dataset.frame.clone();
    let plan = source_backed_projection_plan(&schema, recipe)?;
    let split_column_count = plan
        .split_columns
        .as_ref()
        .map_or(0, |split| split.names.len());
    let split_dropped_source_count = plan
        .split_columns
        .as_ref()
        .map_or(0, |split| usize::from(split.drop_source));
    let merged_column_count = plan.merge_columns.as_ref().map_or(0, |_| 1);
    let merge_dropped_source_count = plan.merge_columns.as_ref().map_or(0, |merge| {
        usize::from(merge.drop_sources) * merge.sources.len()
    });
    let normalized_contact_column_count = plan.contact_normalizations.len();
    let extracted_column_count = plan.text_extractions.len();
    let dropped_source_column_count = split_dropped_source_count + merge_dropped_source_count;
    let structural_change = plan.renamed_column_count
        + plan.converted_column_count
        + plan.parsed_date_column_count
        + plan.calculated_column_count
        + split_column_count
        + merged_column_count
        + extracted_column_count
        + dropped_source_column_count
        + plan.dropped_column_count
        + usize::from(plan.kept_order_changed)
        + usize::from(plan.group_summary.is_some())
        > 0;

    if !structural_change
        && recipe.filters.is_empty()
        && recipe.find_replace.is_none()
        && recipe.contact_normalizations.is_empty()
        && recipe.outlier_treatments.is_empty()
        && recipe.group_summary.is_none()
    {
        let page_frame = collect_lazy_frame_streaming(
            source_scan(&source_path, &extension)?.slice(0, PREVIEW_ROW_LIMIT as IdxSize),
            "No se pudo leer la vista previa source-backed",
        )?;
        let expected_page_rows = dataset.row_count.min(PREVIEW_ROW_LIMIT);
        if page_frame.height() != expected_page_rows {
            return Err(
                "La fuente source-backed cambió durante la lectura de la vista previa.".to_owned(),
            );
        }
        let preview = dataset_preview_from_schema_and_page(
            &dataset.file_name,
            dataset.file_size_bytes,
            dataset.row_count,
            &schema,
            &page_frame,
        )?;
        return Ok(TransformRecipeResult {
            dataset: preview,
            renamed_column_count: plan.renamed_column_count,
            converted_column_count: plan.converted_column_count,
            parsed_date_column_count: plan.parsed_date_column_count,
            removed_row_count: 0,
            calculated_column_count: plan.calculated_column_count,
            replaced_cell_count: 0,
            dropped_column_count: plan.dropped_column_count,
            split_column_count,
            merged_column_count,
            dropped_source_column_count,
            adjusted_outlier_cell_count: 0,
            outlier_removed_row_count: 0,
            outlier_column_count: 0,
            group_count: 0,
            aggregated_column_count: 0,
            collapsed_row_count: 0,
            normalized_contact_cell_count: 0,
            normalized_contact_column_count,
            extracted_column_count,
            changed: false,
        });
    }

    let queries = source_backed_projection_query(&schema, recipe)?;
    if let Some(query) = queries.group_validation.as_deref() {
        let invalid = crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
        if invalid != 0 {
            return Err(
                "El resumen source-backed contiene claves, agregaciones o sumas no válidas."
                    .to_owned(),
            );
        }
    }
    if let Some(query) = queries.calculation_validation.as_deref() {
        let invalid = crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
        if invalid != 0 {
            return Err("La división source-backed contiene división por cero.".to_owned());
        }
    }
    if let Some(query) = queries.outlier_validation.as_deref() {
        let invalid = crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
        if invalid != 0 {
            return Err(
                "Los tratamientos IQR source-backed requieren al menos cuatro valores finitos y dentro de precisión segura."
                    .to_owned(),
            );
        }
    }
    let scalar_count = |query: Option<&String>, message: &str| {
        query
            .map(|query| {
                let count =
                    crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
                usize::try_from(count).map_err(|_| message.to_owned())
            })
            .transpose()
    };
    let adjusted_outlier_cell_count = scalar_count(
        queries.outlier_adjusted_count.as_ref(),
        "El conteo de celdas atípicas ajustadas excede el límite de memoria.",
    )?
    .unwrap_or(0);
    let outlier_removed_row_count = scalar_count(
        queries.outlier_removed_count.as_ref(),
        "El conteo de filas atípicas retiradas excede el límite de memoria.",
    )?
    .unwrap_or(0);
    let filtered_input_row_count = scalar_count(
        queries.input_row_count.as_ref(),
        "El conteo de filas de entrada excede el límite de memoria.",
    )?;
    let group_summary_input_rows = queries
        .group_input_count
        .as_deref()
        .map(|query| {
            let count = crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
            usize::try_from(count).map_err(|_| {
                "El conteo de filas para agrupar excede el límite de memoria.".to_owned()
            })
        })
        .transpose()?;
    let temporary =
        tempfile::NamedTempFile::with_suffix_in(".parquet", dataset.history.directory.path())
            .map_err(|error| {
                format!(
                    "No se pudo preparar la salida temporal de la receta source-backed: {error}"
                )
            })?;
    let output_path = temporary.path().to_owned();
    drop(temporary);
    if let Err(error) = crate::duckdb_query::materialize_file_query_to_parquet(
        &source_path,
        source_format,
        &queries.output,
        &output_path,
    ) {
        let _ = fs::remove_file(&output_path);
        return Err(error);
    }

    let output_size = fs::metadata(&output_path)
        .map_err(|error| format!("No se pudo verificar la receta source-backed: {error}"))?
        .len();
    let output_schema = read_parquet_schema_frame(&output_path)?;
    let output_row_count = crate::duckdb_query::count_file_rows(
        &output_path,
        crate::duckdb_query::DuckDbFileFormat::Parquet,
        || false,
    )?;
    if output_row_count > dataset.row_count {
        let _ = fs::remove_file(&output_path);
        return Err(
            "La receta source-backed aumentó inesperadamente el conteo de filas.".to_owned(),
        );
    }
    if let Some(query) = queries.output_validation.as_deref() {
        let invalid = crate::duckdb_query::query_file_scalar(
            &output_path,
            crate::duckdb_query::DuckDbFileFormat::Parquet,
            query,
        )
        .inspect_err(|_| {
            let _ = fs::remove_file(&output_path);
        })?;
        if invalid != 0 {
            let _ = fs::remove_file(&output_path);
            return Err("El resumen source-backed produjo un valor numérico no finito.".to_owned());
        }
    }
    let replaced_cell_count = queries
        .replacement_count
        .as_deref()
        .map(|query| {
            let count = crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
            usize::try_from(count)
                .map_err(|_| "El conteo de reemplazos excede el límite de memoria.".to_owned())
        })
        .transpose()?
        .unwrap_or(0);
    let normalized_contact_cell_count = queries
        .normalization_count
        .as_deref()
        .map(|query| {
            let count = crate::duckdb_query::query_file_scalar(&source_path, source_format, query)?;
            usize::try_from(count)
                .map_err(|_| "El conteo de normalizaciones excede el límite de memoria.".to_owned())
        })
        .transpose()?
        .unwrap_or(0);
    let (_, current_source_size, _) = validate_dataset_file(&original_source_path)?;
    if current_source_size != dataset.file_size_bytes {
        let _ = fs::remove_file(&output_path);
        return Err("El archivo source-backed cambió durante la receta.".to_owned());
    }
    let removed_row_count = filtered_input_row_count
        .map(|input_rows| dataset.row_count.saturating_sub(input_rows))
        .unwrap_or_else(|| dataset.row_count.saturating_sub(output_row_count));
    let group_count = usize::from(plan.group_summary.is_some()) * output_row_count;
    let aggregated_column_count = plan
        .group_summary
        .as_ref()
        .map_or(0, |summary| summary.aggregations.len());
    let collapsed_row_count = group_summary_input_rows
        .map(|input_rows| input_rows.saturating_sub(output_row_count))
        .unwrap_or(0);
    let changed = structural_change
        || removed_row_count > 0
        || replaced_cell_count > 0
        || normalized_contact_cell_count > 0
        || adjusted_outlier_cell_count > 0
        || outlier_removed_row_count > 0;
    if !changed {
        let _ = fs::remove_file(&output_path);
        let page_frame = collect_lazy_frame_streaming(
            source_scan(&source_path, &extension)?.slice(0, PREVIEW_ROW_LIMIT as IdxSize),
            "No se pudo leer la vista previa source-backed",
        )?;
        let preview = dataset_preview_from_schema_and_page(
            &dataset.file_name,
            dataset.file_size_bytes,
            dataset.row_count,
            &schema,
            &page_frame,
        )?;
        return Ok(TransformRecipeResult {
            dataset: preview,
            renamed_column_count: plan.renamed_column_count,
            converted_column_count: 0,
            parsed_date_column_count: 0,
            removed_row_count: 0,
            calculated_column_count: 0,
            replaced_cell_count: 0,
            dropped_column_count: plan.dropped_column_count,
            split_column_count,
            merged_column_count,
            dropped_source_column_count,
            adjusted_outlier_cell_count: 0,
            outlier_removed_row_count: 0,
            outlier_column_count: plan.outlier_treatments.len(),
            group_count: 0,
            aggregated_column_count: 0,
            collapsed_row_count: 0,
            normalized_contact_cell_count: 0,
            normalized_contact_column_count,
            extracted_column_count,
            changed: false,
        });
    }
    let page = dataset_page_from_parquet(&output_path, output_row_count, 0, PREVIEW_ROW_LIMIT)?;
    let page_frame = read_parquet_query_block(&output_path, 0, page.rows.len())?;
    let preview = dataset_preview_from_schema_and_page(
        &dataset.file_name,
        output_size,
        output_row_count,
        &output_schema,
        &page_frame,
    )?;
    let previous_source_path = dataset.source_path.clone();
    dataset.source_path = Some(output_path);
    dataset.file_size_bytes = output_size;
    dataset.row_count = output_row_count;
    dataset.frame = output_schema;
    dataset.source_backed = true;
    dataset.history.source_snapshot_path = None;
    dataset.profile = None;
    dataset.history.current_label = "Aplicar receta de transformación".to_owned();
    if previous_source_path.as_deref().and_then(Path::parent)
        == Some(dataset.history.directory.path())
    {
        if let Some(previous_source_path) = previous_source_path {
            let _ = fs::remove_file(previous_source_path);
        }
    }
    Ok(TransformRecipeResult {
        dataset: preview,
        renamed_column_count: plan.renamed_column_count,
        converted_column_count: plan.converted_column_count,
        parsed_date_column_count: plan.parsed_date_column_count,
        removed_row_count,
        calculated_column_count: plan.calculated_column_count,
        replaced_cell_count,
        dropped_column_count: plan.dropped_column_count,
        split_column_count,
        merged_column_count,
        dropped_source_column_count,
        adjusted_outlier_cell_count,
        outlier_removed_row_count,
        outlier_column_count: plan.outlier_treatments.len(),
        group_count,
        aggregated_column_count,
        collapsed_row_count,
        normalized_contact_cell_count,
        normalized_contact_column_count,
        extracted_column_count,
        changed,
    })
}

fn apply_eager_recipe_to_frame(
    source: &DataFrame,
    recipe: &TransformRecipe,
) -> Result<RecipeFrameOutcome, String> {
    let mut candidate = source.clone();
    let mut rename_sources = HashSet::new();
    let rename_map = recipe
        .renames
        .iter()
        .map(|rename| {
            if rename.from.trim().is_empty() || rename.to.trim().is_empty() {
                return Err("Los nombres de columna no pueden estar vacíos.".to_owned());
            }
            if rename.to != rename.to.trim() {
                return Err(
                    "El nuevo nombre de columna no puede tener espacios exteriores.".to_owned(),
                );
            }
            if !rename_sources.insert(rename.from.as_str()) {
                return Err(format!(
                    "La columna '{}' aparece en más de un renombrado.",
                    rename.from
                ));
            }
            recipe_column(source, &rename.from)?;
            Ok((rename.from.as_str(), rename.to.as_str()))
        })
        .collect::<Result<HashMap<_, _>, String>>()?;
    for cast in &recipe.casts {
        recipe_column(source, &cast.column)?;
    }
    for parse in &recipe.date_parses {
        recipe_column(source, &parse.column)?;
    }
    for filter in &recipe.filters {
        recipe_column(source, &filter.column)?;
    }
    if let Some(find_replace) = &recipe.find_replace {
        if let Some(column) = &find_replace.column {
            recipe_column(source, column)?;
        }
    }
    if let Some(keep_columns) = &recipe.keep_columns {
        for column in keep_columns {
            recipe_column(source, column)?;
        }
    }
    if let Some(split) = &recipe.split_column {
        recipe_column(source, &split.source)?;
    }
    if let Some(merge) = &recipe.merge_columns {
        for source_name in &merge.sources {
            recipe_column(source, source_name)?;
        }
    }
    for treatment in &recipe.outlier_treatments {
        recipe_column(source, &treatment.column)?;
    }
    if let Some(summary) = &recipe.group_summary {
        let mut derived_names = recipe
            .text_extractions
            .iter()
            .map(|extraction| extraction.name.as_str())
            .collect::<HashSet<_>>();
        if let Some(calculation) = &recipe.calculated_column {
            derived_names.insert(calculation.name.as_str());
        }
        if let Some(split) = &recipe.split_column {
            derived_names.extend(split.names.iter().map(String::as_str));
        }
        if let Some(merge) = &recipe.merge_columns {
            derived_names.insert(merge.name.as_str());
        }
        for name in &summary.group_by {
            if !derived_names.contains(name.as_str()) {
                recipe_column(source, name)?;
            }
        }
        for aggregation in &summary.aggregations {
            if !derived_names.contains(aggregation.column.as_str()) {
                recipe_column(source, &aggregation.column)?;
            }
        }
    }
    for treatment in &recipe.contact_normalizations {
        recipe_column(source, &treatment.column)?;
    }
    for extraction in &recipe.text_extractions {
        recipe_column(source, &extraction.source)?;
    }
    if let Some(calculation) = &recipe.calculated_column {
        recipe_column(source, &calculation.source)?;
        if let Some(CalculatedOperand {
            kind: CalculatedOperandKind::Column,
            value,
        }) = &calculation.operand
        {
            recipe_column(source, value)?;
        }
    }
    let final_names = source
        .get_column_names()
        .iter()
        .map(|name| {
            rename_map
                .get(name.as_str())
                .copied()
                .unwrap_or(name.as_str())
                .to_owned()
        })
        .collect::<Vec<_>>();
    let mut unique_names = HashSet::new();
    if final_names.iter().any(|name| !unique_names.insert(name)) {
        return Err("Los renombrados producirían nombres de columna duplicados.".to_owned());
    }
    let renamed_count = source
        .get_column_names()
        .iter()
        .zip(&final_names)
        .filter(|(before, after)| before.as_str() != after.as_str())
        .count();
    if renamed_count > 0 {
        candidate
            .set_column_names(&final_names)
            .map_err(|error| format!("No se pudieron aplicar los renombrados: {error}"))?;
    }

    let mut cast_columns = HashSet::new();
    let mut cast_count = 0;
    for cast in &recipe.casts {
        let effective_name = rename_map
            .get(cast.column.as_str())
            .copied()
            .unwrap_or(cast.column.as_str());
        if !cast_columns.insert(effective_name) {
            return Err(format!(
                "La columna '{}' aparece en más de una conversión.",
                cast.column
            ));
        }
        let column = recipe_column(&candidate, effective_name)?;
        let already_target = matches!(
            (column.dtype(), cast.target),
            (polars::prelude::DataType::String, RecipeCastTarget::String)
                | (polars::prelude::DataType::Int64, RecipeCastTarget::Integer)
                | (
                    polars::prelude::DataType::Float64,
                    RecipeCastTarget::Decimal
                )
                | (
                    polars::prelude::DataType::Boolean,
                    RecipeCastTarget::Boolean
                )
        );
        if !already_target {
            let converted = strict_cast_column(column, cast.target)?;
            candidate
                .replace(effective_name, converted)
                .map_err(|error| format!("No se pudo convertir '{}': {error}", effective_name))?;
            cast_count += 1;
        }
    }

    let mut date_columns = HashSet::new();
    let mut date_count = 0;
    for parse in &recipe.date_parses {
        let effective_name = rename_map
            .get(parse.column.as_str())
            .copied()
            .unwrap_or(parse.column.as_str());
        if cast_columns.contains(effective_name) {
            return Err(format!(
                "La columna '{}' no puede convertirse y parsearse como fecha en la misma receta.",
                parse.column
            ));
        }
        if !date_columns.insert(effective_name) {
            return Err(format!(
                "La columna '{}' aparece en más de un parseo de fecha.",
                parse.column
            ));
        }
        let column = recipe_column(&candidate, effective_name)?;
        let already_target = matches!(
            (column.dtype(), parse.target),
            (polars::prelude::DataType::Date, RecipeDateTarget::Date)
                | (
                    polars::prelude::DataType::Datetime(_, _),
                    RecipeDateTarget::Datetime
                )
        );
        if !already_target {
            let converted = strict_date_column(column, parse.format, parse.target)?;
            candidate
                .replace(effective_name, converted)
                .map_err(|error| {
                    format!(
                        "No se pudo convertir la fecha '{}': {error}",
                        effective_name
                    )
                })?;
            date_count += 1;
        }
    }

    let (mut candidate, removed_row_count) =
        apply_recipe_filters(candidate, &recipe.filters, &rename_map)?;
    let replaced_cell_count = if let Some(find_replace) = &recipe.find_replace {
        apply_find_replace(&mut candidate, find_replace, &rename_map)?
    } else {
        0
    };
    let (mut candidate, dropped_column_count, kept_order_changed) =
        apply_keep_columns(candidate, recipe.keep_columns.as_deref(), &rename_map)?;
    let calculated_column_count = if let Some(calculation) = &recipe.calculated_column {
        let source_name = remapped_name(&calculation.source, &rename_map);
        recipe_column(&candidate, source_name).map_err(|_| {
            format!("La columna fuente calculada '{source_name}' fue descartada por keepColumns.")
        })?;
        if let Some(CalculatedOperand {
            kind: CalculatedOperandKind::Column,
            value,
        }) = &calculation.operand
        {
            let operand_name = remapped_name(value, &rename_map);
            recipe_column(&candidate, operand_name).map_err(|_| {
                format!(
                    "La columna operando calculada '{operand_name}' fue descartada por keepColumns."
                )
            })?;
        }
        add_calculated_column(&mut candidate, calculation, &rename_map)?;
        1
    } else {
        0
    };
    if let (Some(split), Some(merge)) = (&recipe.split_column, &recipe.merge_columns) {
        if split.drop_source && merge.sources.contains(&split.source) {
            return Err(format!(
                "La unión necesita '{}', pero la división la descartaría.",
                split.source
            ));
        }
    }
    let (split_column_count, split_dropped) = if let Some(split) = &recipe.split_column {
        let effective = remapped_name(&split.source, &rename_map);
        recipe_column(&candidate, effective).map_err(|_| {
            format!("La columna '{effective}' requerida por split fue descartada por keepColumns.")
        })?;
        apply_split_column(&mut candidate, split, &rename_map)?
    } else {
        (0, 0)
    };
    let (merged_column_count, merge_dropped) = if let Some(merge) = &recipe.merge_columns {
        for source in &merge.sources {
            let effective = remapped_name(source, &rename_map);
            recipe_column(&candidate, effective).map_err(|_| format!("La columna '{effective}' requerida por merge fue descartada por keepColumns o split."))?;
        }
        apply_merge_columns(&mut candidate, merge, &rename_map)?
    } else {
        (0, 0)
    };
    let dropped_source_column_count = split_dropped + merge_dropped;
    for treatment in &recipe.outlier_treatments {
        let effective = remapped_name(&treatment.column, &rename_map);
        recipe_column(&candidate, effective).map_err(|_| format!("La columna '{effective}' para tratar atípicos no sobrevivió las etapas estructurales."))?;
    }
    let (candidate, adjusted_outlier_cell_count, outlier_removed_row_count, outlier_column_count) =
        apply_outlier_treatments(candidate, &recipe.outlier_treatments, &rename_map)?;
    let mut candidate = candidate;
    for treatment in &recipe.contact_normalizations {
        let effective = remapped_name(&treatment.column, &rename_map);
        recipe_column(&candidate, effective).map_err(|_| {
            format!(
                "La columna '{effective}' para contactos no sobrevivió las etapas estructurales."
            )
        })?;
    }
    for extraction in &recipe.text_extractions {
        let effective = remapped_name(&extraction.source, &rename_map);
        recipe_column(&candidate, effective).map_err(|_| {
            format!(
                "La columna '{effective}' para extracción no sobrevivió las etapas estructurales."
            )
        })?;
    }
    let (normalized_contact_cell_count, normalized_contact_column_count) =
        apply_contact_normalizations(&mut candidate, &recipe.contact_normalizations, &rename_map)?;
    let extracted_column_count =
        apply_text_extractions(&mut candidate, &recipe.text_extractions, &rename_map)?;
    let (candidate, group_count, aggregated_column_count, collapsed_row_count) = if let Some(
        summary,
    ) =
        &recipe.group_summary
    {
        for name in summary.group_by.iter().chain(
            summary
                .aggregations
                .iter()
                .map(|aggregation| &aggregation.column),
        ) {
            let effective = remapped_name(name, &rename_map);
            recipe_column(&candidate, effective).map_err(|_| format!("La columna '{effective}' requerida por agrupar/resumir no sobrevivió las etapas anteriores."))?;
        }
        apply_group_summary(candidate, summary, &rename_map)?
    } else {
        (candidate, 0, 0, 0)
    };

    Ok((
        candidate,
        renamed_count,
        cast_count,
        date_count,
        removed_row_count,
        calculated_column_count,
        replaced_cell_count,
        dropped_column_count,
        kept_order_changed,
        split_column_count,
        merged_column_count,
        dropped_source_column_count,
        adjusted_outlier_cell_count,
        outlier_removed_row_count,
        outlier_column_count,
        group_count,
        aggregated_column_count,
        collapsed_row_count,
        normalized_contact_cell_count,
        normalized_contact_column_count,
        extracted_column_count,
    ))
}

pub(crate) fn load_dataset_for_automation(
    input: &Path,
    sheet_name: Option<&str>,
    header_mode: Option<SpreadsheetHeaderMode>,
) -> Result<(DataFrame, DatasetPreview), String> {
    load_dataset_for_automation_with_progress(input, sheet_name, header_mode, |_, _| {}, || false)
}

pub(crate) fn load_dataset_for_automation_with_progress<F, C>(
    input: &Path,
    sheet_name: Option<&str>,
    header_mode: Option<SpreadsheetHeaderMode>,
    mut report: F,
    is_cancelled: C,
) -> Result<(DataFrame, DatasetPreview), String>
where
    F: FnMut(&'static str, u8),
    C: Fn() -> bool,
{
    ensure_not_cancelled(is_cancelled())?;
    let (canonical, file_size_bytes, extension) = validate_dataset_file(input)?;
    ensure_materialization_budget(file_size_bytes)?;
    if spreadsheet_extensions(&extension) {
        let sheet_name = sheet_name.ok_or_else(|| "Selecciona una hoja del libro.".to_owned())?;
        let header_mode = header_mode
            .ok_or_else(|| "Elige cómo interpretar los encabezados del libro.".to_owned())?;
        if sheet_name.is_empty() {
            return Err("La hoja seleccionada no es válida.".to_owned());
        }
        report("Validando archivo", 10);
        ensure_not_cancelled(is_cancelled())?;
        report("Leyendo y detectando columnas", 25);
        let available_sheets = inspect_workbook(&canonical)?;
        if available_sheets
            .iter()
            .filter(|name| *name == sheet_name)
            .count()
            != 1
        {
            return Err("La hoja seleccionada no existe de forma única en el libro.".to_owned());
        }
        let frame = load_spreadsheet_sheet(&canonical, sheet_name, header_mode)?;
        ensure_not_cancelled(is_cancelled())?;
        report("Preparando vista previa", 85);
        let preview = dataset_preview(&canonical, &frame)?;
        report("Preparando sesión", 95);
        Ok((frame, preview))
    } else {
        if sheet_name.is_some() || header_mode.is_some() {
            return Err("Este formato no utiliza selección de hoja ni encabezado.".to_owned());
        }
        load_dataset_with_progress(&canonical, report, is_cancelled)
    }
}

pub(crate) fn should_use_source_backed_automation(
    input: &Path,
    sheet_name: Option<&str>,
    header_mode: Option<SpreadsheetHeaderMode>,
) -> Result<bool, String> {
    let (_, file_size_bytes, extension) = validate_dataset_file(input)?;
    if spreadsheet_extensions(&extension) {
        if sheet_name.is_none() || header_mode.is_none() {
            return Err("Selecciona una hoja y un modo de encabezado para el libro.".to_owned());
        }
        return Ok(should_defer_source_load(&extension, file_size_bytes)
            && matches!(extension.as_str(), "xlsx" | "xlsb"));
    }
    if sheet_name.is_some() || header_mode.is_some() {
        return Err("Este formato no utiliza selección de hoja ni encabezado.".to_owned());
    }
    Ok(should_defer_source_load(&extension, file_size_bytes))
}

pub(crate) fn inspect_source_backed_for_automation(
    input: &Path,
    sheet_name: Option<&str>,
    header_mode: Option<SpreadsheetHeaderMode>,
) -> Result<DatasetPreview, String> {
    let (_, preview) = load_source_backed_dataset_for_automation(input, sheet_name, header_mode)?;
    Ok(preview)
}

pub(crate) struct AutomationSourceBackedTransformResult {
    pub(crate) exported: ExportResult,
    pub(crate) changed: bool,
    pub(crate) input_row_count: usize,
    pub(crate) output_row_count: usize,
    pub(crate) input_column_count: usize,
    pub(crate) output_column_count: usize,
}

fn export_source_backed_for_automation(
    dataset: &LoadedDataset,
    output: &Path,
    format: ExportFormat,
    quality_validation: Option<&QualityValidationResult>,
    recipe: Option<&StoredTransformRecipe>,
) -> Result<ExportResult, String> {
    let (source_path, _) = current_duckdb_file_source(dataset)
        .ok_or_else(|| "La fuente source-backed ya no está disponible para exportar.".to_owned())?;
    let expected_file_size = fs::metadata(&source_path)
        .map_err(|error| format!("No se pudo verificar la fuente source-backed: {error}"))?
        .len();
    let row_count = dataset.row_count;
    match format {
        ExportFormat::Csv => export_source_backed_csv_atomic(
            &source_path,
            expected_file_size,
            output,
            |_, _| {},
            || false,
        ),
        ExportFormat::Json => export_source_backed_json_atomic(
            &source_path,
            expected_file_size,
            output,
            |_, _| {},
            || false,
        ),
        ExportFormat::Parquet => export_source_backed_parquet_atomic(
            &source_path,
            expected_file_size,
            output,
            |_, _| {},
            || false,
        ),
        ExportFormat::Sql => export_source_backed_sql_atomic(
            &source_path,
            expected_file_size,
            output,
            |_, _| {},
            || false,
        ),
        ExportFormat::Excel => export_source_backed_xlsx_atomic(
            &source_path,
            expected_file_size,
            row_count,
            output,
            |_, _| {},
            || false,
        ),
        ExportFormat::Sqlite => export_source_backed_sqlite_atomic(
            &source_path,
            expected_file_size,
            row_count,
            output,
            |_, _| {},
            || false,
        ),
        ExportFormat::Bundle => export_source_backed_bundle_atomic(
            &source_path,
            expected_file_size,
            row_count,
            quality_validation,
            recipe,
            output,
            |_, _| {},
            || false,
        ),
    }
}

pub(crate) fn transform_source_backed_for_automation(
    input: &Path,
    sheet_name: Option<&str>,
    header_mode: Option<SpreadsheetHeaderMode>,
    recipe: &StoredTransformRecipe,
    output: &Path,
    format: ExportFormat,
) -> Result<AutomationSourceBackedTransformResult, String> {
    let (mut dataset, _) =
        load_source_backed_dataset_for_automation(input, sheet_name, header_mode)?;
    let input_row_count = dataset.row_count;
    let input_column_count = dataset.frame.width();
    let result = apply_recipe_to_dataset(&mut dataset, &recipe.recipe)?;
    let exported =
        export_source_backed_for_automation(&dataset, output, format, None, Some(recipe))?;
    Ok(AutomationSourceBackedTransformResult {
        exported,
        changed: result.changed,
        input_row_count,
        output_row_count: result.dataset.row_count,
        input_column_count,
        output_column_count: result.dataset.column_count,
    })
}

pub(crate) fn evaluate_source_backed_quality_rules_for_automation(
    input: &Path,
    sheet_name: Option<&str>,
    header_mode: Option<SpreadsheetHeaderMode>,
    quality_rules: &[QualityRule],
) -> Result<QualityValidationResult, String> {
    let (dataset, _) = load_source_backed_dataset_for_automation(input, sheet_name, header_mode)?;
    let (source_path, _) = current_duckdb_file_source(&dataset)
        .ok_or_else(|| "La fuente source-backed ya no está disponible para validar.".to_owned())?;
    let (source_path, expected_file_size, extension) = validate_dataset_file(&source_path)?;
    evaluate_source_quality_rules_with_cancel(
        &source_path,
        &extension,
        expected_file_size,
        dataset.row_count,
        quality_rules,
        || false,
    )
}

pub(crate) fn load_quality_rules_for_automation(input: &Path) -> Result<Vec<QualityRule>, String> {
    let document = parse_quality_rules_document(read_quality_rules_json(input)?, true)?;
    Ok(document.rules)
}

pub(crate) fn evaluate_quality_rules_for_automation(
    frame: &DataFrame,
    quality_rules: &[QualityRule],
) -> Result<QualityValidationResult, String> {
    evaluate_quality_rules(frame, quality_rules)
}

pub(crate) fn validate_project_workspace(
    frame: &DataFrame,
    quality_rules: &[QualityRule],
    recipe_draft: Option<&StoredTransformRecipe>,
) -> Result<(), String> {
    validate_quality_rules_payload(quality_rules)?;
    for rule in quality_rules {
        validate_quality_rule_definition(frame, rule)?;
    }
    if let Some(recipe) = recipe_draft {
        validate_stored_recipe(recipe)?;
    }
    Ok(())
}

pub(crate) fn validate_project_profile(
    frame: &DataFrame,
    profile: &DatasetProfile,
) -> Result<(), String> {
    validate_project_profile_with_row_count(frame, frame.height(), profile)
}

pub(crate) fn validate_project_profile_with_row_count(
    frame: &DataFrame,
    row_count: usize,
    profile: &DatasetProfile,
) -> Result<(), String> {
    let finite = |value: Option<f64>| value.is_none_or(f64::is_finite);
    if !profile.duplicate_percentage.is_finite()
        || !(0.0..=100.0).contains(&profile.duplicate_percentage)
        || profile.columns.iter().any(|column| {
            !column.completeness_percentage.is_finite()
                || !(0.0..=100.0).contains(&column.completeness_percentage)
                || !finite(column.mean)
                || !finite(column.average_length)
                || !finite(column.type_match_percentage)
                || !finite(column.standard_deviation)
                || !finite(column.first_quartile)
                || !finite(column.median)
                || !finite(column.third_quartile)
        })
    {
        return Err("El perfil guardado contiene métricas no válidas.".to_owned());
    }
    if let Some(correlations) = &profile.numeric_correlations {
        if correlations.columns.len() < 2
            || correlations.columns.len() > MAX_NUMERIC_CORRELATION_COLUMNS
            || correlations.sampled_row_count > MAX_NUMERIC_CORRELATION_SAMPLE_ROWS
            || correlations.pairs.iter().any(|pair| {
                pair.first_column == pair.second_column
                    || !correlations.columns.contains(&pair.first_column)
                    || !correlations.columns.contains(&pair.second_column)
                    || pair.coefficient.is_some_and(|coefficient| {
                        !coefficient.is_finite() || !(-1.0..=1.0).contains(&coefficient)
                    })
            })
        {
            return Err("El perfil guardado contiene correlaciones no válidas.".to_owned());
        }
    }
    if let Some(summaries) = &profile.categorical_group_summaries {
        if summaries.len() > MAX_CATEGORICAL_GROUP_COLUMNS
            || summaries.iter().any(|summary| {
                summary.groups.is_empty()
                    || summary.groups.len() > MAX_CATEGORICAL_GROUPS + 1
                    || summary.distinct_count < 2
                    || summary.groups.iter().filter(|group| group.is_other).count() > 1
                    || summary.groups.iter().any(|group| {
                        group.label.is_empty()
                            || group.row_count == 0
                            || !group.percentage.is_finite()
                            || !(0.0..=100.0).contains(&group.percentage)
                            || group.label.chars().count() > MAX_GROUP_LABEL_CHARS
                    })
                    || summary
                        .groups
                        .iter()
                        .map(|group| group.row_count)
                        .sum::<usize>()
                        != profile.row_count
            })
        {
            return Err(
                "El perfil guardado contiene resúmenes de categorías no válidos.".to_owned(),
            );
        }
    }
    if let Some(summaries) = &profile.temporal_series {
        if summaries.len() > MAX_TEMPORAL_COLUMNS
            || summaries.iter().any(|summary| {
                !matches!(summary.granularity.as_str(), "day" | "month" | "year")
                    || summary.periods.is_empty()
                    || summary.periods.len() > MAX_TEMPORAL_PERIODS
                    || summary.parsed_row_count == 0
                    || summary.parsed_row_count > profile.row_count
                    || summary.unparsed_row_count
                        != profile.row_count.saturating_sub(summary.parsed_row_count)
                    || summary.periods.iter().any(|period| {
                        period.period.is_empty()
                            || period.period.chars().count() > 64
                            || period.row_count > summary.parsed_row_count
                            || !period.percentage.is_finite()
                            || !(0.0..=100.0).contains(&period.percentage)
                    })
                    || summary
                        .periods
                        .iter()
                        .map(|period| period.row_count)
                        .sum::<usize>()
                        != summary.parsed_row_count
            })
        {
            return Err("El perfil guardado contiene tendencias temporales no válidas.".to_owned());
        }
    }
    if profile.row_count != row_count
        || profile.columns.len() != frame.width()
        || profile
            .columns
            .iter()
            .zip(frame.columns())
            .any(|(stored, column)| {
                stored.name != column.name().as_str()
                    || stored.data_type != column.dtype().to_string()
                    || stored.null_count > profile.row_count
                    || stored.unique_count > profile.row_count
            })
    {
        return Err("El perfil guardado no coincide con el dataset.".to_owned());
    }
    Ok(())
}

pub(crate) fn load_recipe_for_automation(input: &Path) -> Result<TransformRecipe, String> {
    load_recipe_file(input).map(|document| document.recipe)
}

pub(crate) fn load_stored_recipe_for_automation(
    input: &Path,
) -> Result<StoredTransformRecipe, String> {
    load_recipe_file(input)
}

pub(crate) fn apply_recipe_for_automation(
    source: &DataFrame,
    recipe: &TransformRecipe,
) -> Result<(DataFrame, bool), String> {
    validate_recipe_structure(recipe)?;
    let outcome = apply_recipe_to_frame(source, recipe)?;
    let candidate = outcome.0;
    let changed = !candidate.equals_missing(source);
    Ok((candidate, changed))
}

pub(crate) fn export_frame_for_automation(
    frame: &DataFrame,
    output: &Path,
    format: ExportFormat,
) -> Result<ExportResult, String> {
    export_frame_atomic(frame, output, format, |_, _| {}, || false)
}

pub(crate) fn export_frame_for_automation_with_recipe(
    frame: &DataFrame,
    output: &Path,
    format: ExportFormat,
    recipe: Option<&StoredTransformRecipe>,
) -> Result<ExportResult, String> {
    if recipe.is_none() {
        return export_frame_for_automation(frame, output, format);
    }
    export_frame_atomic_with_privacy_and_quality_and_recipe(
        frame,
        output,
        format,
        PrivacyMode::None,
        None,
        recipe,
        |_, _| {},
        || false,
    )
}

